import{d as e}from"./index-CzbpWx4N.js";var t=[{dayNumber:13,weekNumber:3,cefrLevel:`b1`,dayBadge:`DAY 13 · 화상 미팅 오프닝 & 연결 대처`,categoryLabel:`Week 3 오피스 실무 · 화상회의 진행 & 트러블슈팅`,title:`화면 공유가 잘 보이시나요?`,subtitle:`Zoom·Teams 글로벌 화상회의 오프닝부터 화면 공유, 오디오 끊김·음소거 대처, 아젠다 전환까지 당황하지 않고 리드하는 핵심 공식`,heroImage:`assets/scene_video_call.jpg`,secondaryImage:`assets/office_sitcom_scene.jpg`,estimatedSprintMin:8,estimatedLectureMin:40,keyExpression:`Let me share my screen — can everyone see this clearly?`,keySentenceByTier:{a1:`Can you hear me? I will share my screen now.`,a2:`Thanks for joining the call. Let me share my screen so we can start.`,b1:`Thanks for hopping on, everyone. Let me share my screen and jump right into today's agenda.`,b2:`Sorry, you're breaking up a bit—let me turn off my video while I share my screen and walk you through the slides.`,c1:`Since everyone is here, let's jump right in; I'll share my screen now, and please chime in if the audio cuts out at any point.`,c2:`Mindful of everyone's time, let's jump straight into the Q3 metrics—bear with me for a second while I pull up the deck and share my screen.`},youtubeVideo:e[13],readingPassage:{titleEn:`How Great Remote Hosts Run Smooth Video Calls`,titleKo:`글로벌 원격 팀장들이 화상회의를 매끄럽게 이끄는 비결`,genreBadge:`원격 협업 플레이북 · Lv.3`,estimatedMin:5,paragraphsEn:[`In global hybrid teams, the first ninety seconds of a video call set the tone for the entire meeting. Seasoned hosts rarely waste five minutes waiting in awkward silence. Instead, they thank everyone for hopping on, confirm that the audio is clear, and jump right into the agenda so colleagues across time zones feel their time is respected.`,`Technical hiccups happen to everyone, even senior directors with fiber-optic internet. When a speaker forgets to unmute or their voice starts breaking up, the smoothest response is calm and direct. Saying "Sorry, you are on mute" or "You cut out for a second—could you repeat that?" keeps the meeting moving without making anyone feel embarrassed.`,`Before walking teammates through a slide deck, strong presenters share their screen early and ask for a quick visual check. If someone's connection begins to lag or their screen freezes, suggesting they switch off their camera or log back in solves most issues within seconds. Wrapping up two minutes early with clear next steps leaves every participant energized for their next call.`],paragraphsSlash:[`In global hybrid teams, / the first ninety seconds of a video call / set the tone for the entire meeting. / Seasoned hosts rarely waste five minutes / waiting in awkward silence. / Instead, / they thank everyone for hopping on, / confirm that the audio is clear, / and jump right into the agenda / so colleagues across time zones / feel their time is respected.`,`Technical hiccups happen to everyone, / even senior directors with fiber-optic internet. / When a speaker forgets to unmute / or their voice starts breaking up, / the smoothest response is calm and direct. / Saying "Sorry, you are on mute" / or "You cut out for a second—could you repeat that?" / keeps the meeting moving / without making anyone feel embarrassed.`,`Before walking teammates through a slide deck, / strong presenters share their screen early / and ask for a quick visual check. / If someone's connection begins to lag / or their screen freezes, / suggesting they switch off their camera / or log back in / solves most issues within seconds. / Wrapping up two minutes early / with clear next steps / leaves every participant energized / for their next call.`],paragraphsKo:[`글로벌 하이브리드 팀에서는 화상회의의 처음 90초가 회의 전체의 분위기를 결정합니다. 노련한 진행자는 어색한 침묵 속에 5분씩 기다리며 시간을 낭비하지 않습니다. 대신 참석해 준 모두에게 감사 인사를 건네고, 오디오 상태를 확인한 뒤, 서로 다른 시간대에 있는 동료들이 자신의 시간을 존중받는다고 느끼도록 곧바로 아젠다로 들어갑니다.`,`기술적인 작은 사고는 초고속 광랜을 쓰는 임원에게도 누구에게나 일어납니다. 발표자가 음소거 해제를 잊었거나 목소리가 뚝뚝 끊기기 시작할 때 가장 매끄러운 대응은 차분하고 명확하게 알려주는 것입니다. "죄송하지만 음소거 상태예요" 또는 "방금 잠깐 끊겼는데 다시 말씀해 주시겠어요?"라고 말하면 누구도 민망하게 하지 않으면서 회의 흐름을 유지할 수 있습니다.`,`슬라이드 자료를 단계별로 설명하기 전에 뛰어난 발표자는 미리 화면을 공유하고 잘 보이는지 짧게 확인을 구합니다. 누군가의 연결이 버벅거리거나 화면이 멈추면 카메라를 끄거나 다시 접속해 보라고 제안하는 것만으로 대부분의 문제가 몇 초 안에 해결됩니다. 명확한 다음 단계를 정리하며 2분 일찍 회의를 마무리하면 모든 참석자가 활기찬 기분으로 다음 미팅을 맞이할 수 있습니다.`],keyExpressions:[`hop on a call`,`jump right into`,`on mute / unmute`,`break up / cut out`,`walk ~ through`,`wrap up`],comprehensionQuiz:[{id:`d13-rq01`,questionKo:`노련한 화상회의 진행자가 시작 후 90초 안에 하는 행동으로 본문에 언급된 것은?`,options:[`모든 참석자가 잡담을 끝낼 때까지 5분간 기다린다`,`참석 감사를 전하고 오디오 확인 후 곧바로 아젠다로 들어간다`,`카메라를 모두 끄고 채팅으로만 회의를 진행한다`,`이전 회의록을 처음부터 끝까지 소리 내어 낭독한다`],answer:`참석 감사를 전하고 오디오 확인 후 곧바로 아젠다로 들어간다`,explanationKo:`첫째 문단 "thank everyone for hopping on, confirm that the audio is clear, and jump right into the agenda"가 근거입니다.`},{id:`d13-rq02`,questionKo:`연결이 버벅거리거나(lag) 화면이 멈췄을 때(freeze) 본문이 제안하는 가장 빠른 해결책은?`,options:[`회의를 즉시 다음 주로 연기한다`,`마이크 볼륨을 최대로 높여 말한다`,`카메라를 끄거나 다시 접속(log back in)해 보라고 제안한다`,`발표 슬라이드를 모두 삭제하고 구두로만 설명한다`],answer:`카메라를 끄거나 다시 접속(log back in)해 보라고 제안한다`,explanationKo:`셋째 문단 "suggesting they switch off their camera or log back in solves most issues within seconds"를 확인하세요.`},{id:`d13-rq03`,questionKo:`본문에서 발표자의 목소리가 "뚝뚝 끊기기 시작하다"를 표현한 원어민 구동사는?`,options:[`wrap up`,`break up`,`drop off`,`jump in`],answer:`break up`,explanationKo:`통화나 화상회의에서 신호 불안정으로 음성이 뚝뚝 끊기는 현상을 break up이라고 표현합니다.`}]},vocabList:[{id:`d13-v01`,word:`hop on (a call)`,phonetic:`/hɑːp ɑːn/`,pos:`구동사`,cefr:`b1`,meaningKo:`(화상·전화 회의에) 가볍게 접속하다, 참여하다`,meaningEn:`join a phone call or video meeting quickly`,nuanceTipKo:`딱딱한 participate in a video conference 대신 실무에서 가장 많이 쓰는 자연스러운 오프닝 표현입니다. "Thanks for hopping on!"으로 외우세요.`,exampleEn:`Thanks for hopping on this call on such short notice.`,exampleKo:`이렇게 급히 잡힌 화상회의에 접속해 주셔서 감사합니다.`},{id:`d13-v02`,word:`jump right in`,phonetic:`/dʒʌmp raɪt ɪn/`,pos:`구동사 구문`,cefr:`b1`,meaningKo:`군더더기 없이 바로 본론으로 들어가다`,meaningEn:`start dealing with the main topic immediately without delay`,nuanceTipKo:`스몰토크를 끝내고 본격적으로 회의를 시작할 때 "Let’s jump right in(to the agenda)" 한마디면 진행자 포스가 살아납니다.`,exampleEn:`Since we only have thirty minutes, let's jump right into the Q3 update.`,exampleKo:`시간이 30분밖에 없으니 바로 3분기 업데이트로 들어가죠.`},{id:`d13-v03`,word:`share my screen`,phonetic:`/ʃer maɪ skriːn/`,pos:`동사 구문`,cefr:`a2`,meaningKo:`내 화면을 공유하다`,meaningEn:`display your computer screen to other participants in an online meeting`,nuanceTipKo:`"Let me share my screen"으로 예고한 뒤 "Can everyone see my screen?"으로 확인하는 2단 세트가 글로벌 표준입니다.`,exampleEn:`Let me share my screen so we can review the dashboard together.`,exampleKo:`대시보드를 함께 볼 수 있도록 제 화면을 공유하겠습니다.`},{id:`d13-v04`,word:`on mute`,phonetic:`/ɑːn mjuːt/`,pos:`전치사구`,cefr:`b1`,meaningKo:`음소거 상태인`,meaningEn:`having the microphone turned off so others cannot hear you`,nuanceTipKo:`한국인이 가장 자주 틀리는 "You are mute(말을 못 하는)"는 실례가 될 수 있습니다! 반드시 전치사 on을 붙여 "You're on mute"라고 말하세요.`,exampleEn:`Sorry, Liam—I think you're still on mute.`,exampleKo:`죄송해요 리암, 아직 음소거 상태이신 것 같아요.`},{id:`d13-v05`,word:`unmute`,phonetic:`/ˌʌnˈmjuːt/`,pos:`동사`,cefr:`b1`,meaningKo:`음소거를 해제하다`,meaningEn:`turn the microphone back on after being muted`,nuanceTipKo:`자동사("Can you unmute?")와 타동사("unmute yourself / your mic") 둘 다 자연스럽게 쓰입니다.`,exampleEn:`Could you unmute yourself before you start presenting?`,exampleKo:`발표 시작하시기 전에 음소거를 해제해 주시겠어요?`},{id:`d13-v06`,word:`break up`,phonetic:`/breɪk ʌp/`,pos:`구동사`,cefr:`b1`,meaningKo:`(통화·화상 음성이) 뚝뚝 끊기다`,meaningEn:`become fragmented and hard to hear due to a poor connection`,nuanceTipKo:`연인과 헤어지다는 뜻 외에, 통화 중 목소리가 지직거리며 끊길 때 진행형 "You're breaking up"으로 100% 쓰입니다.`,exampleEn:`You're breaking up a little—could you repeat the last sentence?`,exampleKo:`목소리가 조금 끊겨서요, 마지막 문장만 다시 말씀해 주시겠어요?`},{id:`d13-v07`,word:`cut out`,phonetic:`/kʌt aʊt/`,pos:`구동사`,cefr:`b2`,meaningKo:`(오디오·영상이) 갑자기 아예 끊기다`,meaningEn:`suddenly stop transmitting sound or signal completely`,nuanceTipKo:`break up이 부분적으로 지지직 끊기는 느낌이라면, cut out은 소리가 몇 초간 완전히 "뚝" 사라졌을 때 씁니다.`,exampleEn:`Your audio cut out for a few seconds right when you mentioned the budget.`,exampleKo:`예산 말씀하신 딱 그 순간에 오디오가 몇 초간 완전히 끊겼어요.`},{id:`d13-v08`,word:`lag`,phonetic:`/læɡ/`,pos:`동사/명사`,cefr:`b1`,meaningKo:`(화면·음성이) 지연되다, 버벅거리다 / 렉`,meaningEn:`fall behind in real time due to slow network speed`,nuanceTipKo:`게임에서 쓰는 "렉 걸린다"의 원래 영어 단어! "There's a slight lag on my end"처럼 명사로도, "My video is lagging"처럼 동사로도 씁니다.`,exampleEn:`There's a bit of a lag, so I'll turn off my camera to save bandwidth.`,exampleKo:`약간 지연(렉)이 있어서 대역폭을 아끼려고 카메라를 끌게요.`},{id:`d13-v09`,word:`echo`,phonetic:`/ˈekoʊ/`,pos:`명사/동사`,cefr:`b1`,meaningKo:`(마이크) 울림, 에코 / 소리가 울리다`,meaningEn:`a repeated sound caused by audio feedback between speakers and mic`,nuanceTipKo:`같은 회의실에 두 명이 동시에 노트북 마이크를 켜서 소리가 울릴 때 "We're getting a strong echo"라고 말하면 바로 상황 정리됩니다.`,exampleEn:`There's a slight echo on the line—could everyone else go on mute?`,exampleKo:`약간 울림이 있어서요, 발언자 외에는 음소거로 전환해 주실 수 있을까요?`},{id:`d13-v10`,word:`frozen`,phonetic:`/ˈfroʊzn/`,pos:`형용사`,cefr:`b1`,meaningKo:`(화면이) 멈춘, 얼어붙은`,meaningEn:`stuck on a single image and no longer updating on screen`,nuanceTipKo:`상대방 화면이 정지했을 때 "Your face stopped"가 아니라 "Your screen is frozen" 또는 "You froze for a second"가 정확한 원어민 표현입니다.`,exampleEn:`Maya, your video is frozen, though we can still hear you clearly.`,exampleKo:`마야, 목소리는 잘 들리는데 화면이 멈춰 있어요.`},{id:`d13-v11`,word:`walk ~ through`,phonetic:`/wɔːk θruː/`,pos:`구동사`,cefr:`b2`,meaningKo:`~을 단계별로 차근차근 설명해 주다`,meaningEn:`guide someone step by step through a document, deck, or process`,nuanceTipKo:`단순 explain보다 훨씬 전문적이며, 화면 공유로 슬라이드나 시트를 함께 보며 안내할 때 최고의 동사입니다. (walk [사람] through [자료])`,exampleEn:`I'll walk you through the updated timeline slide by slide.`,exampleKo:`업데이트된 타임라인을 슬라이드별로 차근차근 설명해 드리겠습니다.`},{id:`d13-v12`,word:`drop off`,phonetic:`/drɑːp ɔːf/`,pos:`구동사`,cefr:`b2`,meaningKo:`(화상회의에서) 먼저 퇴장하다 / 연결이 끊겨 나가다`,meaningEn:`leave a call early or get disconnected from a meeting`,nuanceTipKo:`다음 일정이 있어 일찍 나가야 할 때 "I have to drop off a few minutes early"라고 양해를 구하면 아주 매너 있게 들립니다.`,exampleEn:`Sorry everyone, I have a hard stop at 10 and need to drop off now.`,exampleKo:`죄송해요 여러분, 10시에 꼭 가야 할 일정이 있어서 먼저 나가봐야 합니다.`},{id:`d13-v13`,word:`log back in`,phonetic:`/lɔːɡ bæk ɪn/`,pos:`구동사 구문`,cefr:`b1`,meaningKo:`나갔다가 다시 로그인해 재접속하다`,meaningEn:`exit and sign in again to reset a technical issue`,nuanceTipKo:`음성이나 화면 공유가 먹통일 때 "Let me drop off and log back in"이라고 말하고 재접속하면 깔끔합니다.`,exampleEn:`My screen share isn't loading—let me leave and log back in real quick.`,exampleKo:`화면 공유가 안 떠서 잠깐 나갔다가 바로 다시 접속할게요.`},{id:`d13-v14`,word:`bear with me`,phonetic:`/ber wɪð miː/`,pos:`관용구`,cefr:`b2`,meaningKo:`(파일 로딩·준비 중) 잠시만 양해하고 기다려 주다`,meaningEn:`please be patient with me for a brief moment`,nuanceTipKo:`"Wait a second"는 다소 명령조로 들릴 수 있습니다. 파일을 찾거나 화면 공유 창을 고를 때 "Bear with me for a second"를 쓰면 프로다운 여유가 느껴집니다.`,exampleEn:`Bear with me for just a second while I pull up the latest deck.`,exampleKo:`최신 발표 자료를 여는 동안 딱 1초만 기다려 주세요.`},{id:`d13-v15`,word:`wrap up`,phonetic:`/ræp ʌp/`,pos:`구동사`,cefr:`b1`,meaningKo:`(회의·발표를) 깔끔하게 마무리 짓다`,meaningEn:`bring a meeting or discussion to an orderly close`,nuanceTipKo:`회의 종료 3분 전에 "To wrap up, let's confirm our action items"라고 외치면 정시에 회의를 끝내는 신뢰받는 진행자가 됩니다.`,exampleEn:`Let's wrap up here and send the meeting notes in Slack.`,exampleKo:`여기서 회의를 마무리하고 회의록은 슬랙에 공유하겠습니다.`}],dialogue:[{id:`d13-t01`,speaker:`Jiwon`,roleLabel:`프로덕트 매니저 · 서울`,voicePitch:1.06,sceneImage:`assets/scene_video_call.jpg`,cameraMotion:`zoom-in`,english:`Morning, Liam! Evening, Maya! Thanks for hopping on today—can everyone hear me okay?`,slashBroken:`Morning, Liam! / Evening, Maya! / Thanks for hopping on today— / can everyone hear me okay?`,korean:`좋은 아침이에요 리암! 마야는 저녁이네요! 오늘 접속해 주셔서 감사합니다. 제 목소리 다들 잘 들리시나요?`,keyHighlight:`Thanks for hopping on today`,noteKo:`글로벌 시차가 있는 팀원들에게 각자 시간대에 맞춰 인사한 뒤 hopping on과 오디오 체크로 매끄럽게 엽니다.`},{id:`d13-t02`,speaker:`Liam`,roleLabel:`엔지니어링 리드 · 샌프란시스코`,voicePitch:.92,sceneImage:`assets/scene_video_call.jpg`,cameraMotion:`pan-right`,english:`Loud and clear, Jiwon! Oh, Maya, I think your mouth is moving, but you are on mute.`,slashBroken:`Loud and clear, Jiwon! / Oh, Maya, / I think your mouth is moving, / but you are on mute.`,korean:`또렷하게 잘 들려요, 지원! 어, 마야, 입은 움직이는데 음소거 상태이신 것 같아요.`,keyHighlight:`you are on mute`,noteKo:`"Loud and clear"는 오디오 체크에 대한 최고의 원어민 응답이며, 음소거 알림은 반드시 on mute를 씁니다.`},{id:`d13-t03`,speaker:`Maya`,roleLabel:`UX 디자이너 · 오스틴`,voicePitch:1.12,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`pan-left`,english:`Haha, classic Monday! Sorry, I just unmuted myself. I'm ready to jump right in whenever you are.`,slashBroken:`Haha, classic Monday! / Sorry, I just unmuted myself. / I'm ready to jump right in / whenever you are.`,korean:`하하, 전형적인 월요일이네요! 죄송해요, 방금 음소거 풀었어요. 준비되시면 바로 본론으로 들어가시죠.`,keyHighlight:`jump right in`,noteKo:`실수를 가볍게 웃어넘기고 unmute yourself로 정리한 뒤 본론 진입(jump right in) 의사를 밝힙니다.`},{id:`d13-t04`,speaker:`Jiwon`,roleLabel:`프로덕트 매니저 · 서울`,voicePitch:1.06,sceneImage:`assets/scene_video_call.jpg`,cameraMotion:`zoom-in`,english:`Awesome. Bear with me for a second while I share my screen... Can everyone see the Q3 roadmap deck?`,slashBroken:`Awesome. / Bear with me for a second / while I share my screen... / Can everyone see / the Q3 roadmap deck?`,korean:`좋습니다. 제가 화면 공유하는 동안 잠깐만 기다려 주세요... 다들 3분기 로드맵 자료 보이시나요?`,keyHighlight:`Bear with me for a second while I share my screen`,noteKo:`화면 공유 로딩 중 정적을 메우는 만능 멘트가 바로 "Bear with me for a second"입니다.`},{id:`d13-t05`,speaker:`Liam`,roleLabel:`엔지니어링 리드 · 샌프란시스코`,voicePitch:.92,sceneImage:`assets/scene_video_call.jpg`,cameraMotion:`pan-right`,english:`Yep, we can see it! Wait—Jiwon, you're breaking up a bit, and your video just froze.`,slashBroken:`Yep, we can see it! / Wait—Jiwon, / you're breaking up a bit, / and your video just froze.`,korean:`네, 잘 보여요! 잠깐만요 지원, 목소리가 조금 끊기고 화면이 방금 멈췄어요.`,keyHighlight:`you're breaking up a bit`,noteKo:`오디오 끊김(breaking up)과 화면 정지(froze)를 짧고 명확하게 알려 주어 발표자가 즉시 대처하게 돕습니다.`},{id:`d13-t06`,speaker:`Jiwon`,roleLabel:`프로덕트 매니저 · 서울`,voicePitch:1.06,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`pan-left`,english:`Thanks for letting me know. Let me switch off my camera to fix the lag—if I cut out again, I'll log back in.`,slashBroken:`Thanks for letting me know. / Let me switch off my camera / to fix the lag— / if I cut out again, / I'll log back in.`,korean:`알려줘서 고마워요. 지연 현상을 잡으려고 카메라를 잠깐 끌게요. 또 끊기면 다시 접속하겠습니다.`,keyHighlight:`if I cut out again, I'll log back in`,noteKo:`네트워크 불안정 시 카메라 끄기(switch off my camera) + 재접속 예고(log back in)는 실무 만점 대처입니다.`},{id:`d13-t07`,speaker:`Maya`,roleLabel:`UX 디자이너 · 오스틴`,voicePitch:1.12,sceneImage:`assets/scene_video_call.jpg`,cameraMotion:`zoom-in`,english:`Much better now! Go ahead and walk us through slide three, and let’s aim to wrap up by the half-hour.`,slashBroken:`Much better now! / Go ahead and walk us through slide three, / and let’s aim to wrap up / by the half-hour.`,korean:`지금 훨씬 좋아졌어요! 3번 슬라이드부터 차근차근 설명해 주시고, 30분 정각에 마무리하는 걸로 하죠.`,keyHighlight:`walk us through slide three`,noteKo:`"by the half-hour"는 30분(예: 9:30, 10:30)에 맞춰 끝내자는 회의 실무 시간 표현입니다.`}],grammarSections:[{title:`원리 01 · 화상회의 오디오·화면 장애 영어: break up vs. cut out vs. freeze`,coreFormula:`음성 지직 끊김 = be breaking up / 소리 완전 소실 = cut out / 화면 정지 = be frozen (froze)`,wrongKonglish:`Your voice is cutting and your face stopped on the screen.`,rightNative:`You're breaking up a bit, and your video is frozen.`,explanationKo:`한국어 "목소리가 끊긴다"를 직역해 cutting이라고 하면 어색합니다. 화상회의에서 신호가 약해 말이 토막 나면 진행형으로 "You're breaking up", 몇 초간 소리가 아예 증발했으면 과거형으로 "You cut out for a second", 화면이 멈췄으면 "Your screen is frozen"이라고 증상별로 정확히 구분해 말하세요.`,registerSpectrum:{casual:`Hey, you're breaking up—and you totally froze!`,standard:`Sorry, you're breaking up a bit, and your video is frozen.`,formal:`Apologies for interrupting, but your audio cut out briefly—would you mind repeating that last point?`}},{title:`원리 02 · 음소거 표현의 전치사 공식: on mute (상태) vs. unmute (동작)`,coreFormula:`상태: be on mute / 동작: mute (or unmute) yourself / your mic`,wrongKonglish:`Excuse me, you are mute now. Please open your microphone.`,rightNative:`Excuse me, I think you're on mute. Could you unmute yourself?`,explanationKo:`사람을 주어로 "You are mute"라고 쓰면 "당신은 말을 못 하는 사람이다"라는 실례 표현이 됩니다! 마이크가 꺼진 상태를 말할 때는 반드시 전치사 on을 붙여 "You're on mute"라고 하며, 마이크를 켜달라고 할 때는 "open your mic" 대신 동사 unmute를 씁니다.`,registerSpectrum:{casual:`Oops, you're on mute!`,standard:`Sorry, I think you're still on mute—could you unmute?`,formal:`Pardon me, it looks like your microphone is currently on mute.`}},{title:`원리 03 · 회의 리드 3단 전환 패턴: jump right in → walk you through → wrap up`,coreFormula:`Let's jump right into [주제] → I'll walk you through [자료] → Let's wrap up with [결론]`,wrongKonglish:`Let's enter the main topic and I will explain you the slides.`,rightNative:`Let's jump right into the agenda, and I'll walk you through the slides.`,explanationKo:`한국인이 자주 실수하는 "explain you the slides"는 어법 오류입니다(explain은 바로 뒤에 사람을 목적어로 취할 수 없음). 반면 walk [사람] through [자료]는 사람을 바로 목적어로 쓰며 "화면의 자료를 단계별로 친절히 안내하다"라는 고급 회의 뉘앙스까지 살아납니다.`,registerSpectrum:{casual:`Let's jump right in—I'll quickly walk you guys through these slides.`,standard:`Let's jump right into today's agenda. I'll walk you through the main deck.`,formal:`To make the best use of our time, let's dive directly into the agenda while I walk you through the key figures.`}}],sprintDrills:[{id:`d13-s01`,drillType:`chunk-build`,promptKo:`오늘 회의에 접속해 주셔서 감사합니다.`,promptEnHint:`Thanks for + hopping on 조합으로 화상회의 오프닝을 조립하세요.`,targetEn:`Thanks for hopping on today.`,chunks:[`Thanks for`,`hopping on`,`today.`],explanationKo:`화상·전화 회의 참여 감사는 "Thanks for hopping on"이 가장 자연스럽습니다.`},{id:`d13-s02`,drillType:`konglish-fix`,promptKo:`"죄송한데, 지금 음소거 상태이신 것 같아요."`,promptEnHint:`음소거 상태를 나타내는 정확한 전치사구를 고르세요.`,targetEn:`Sorry, I think you're on mute.`,wrongKonglishOption:`Sorry, I think you're mute now.`,explanationKo:`마이크가 꺼진 상태는 반드시 전치사 on을 붙여 "on mute"라고 표현합니다.`},{id:`d13-s03`,drillType:`chunk-build`,promptKo:`제 화면을 공유해 드릴게요—다들 잘 보이시나요?`,promptEnHint:`Let me share my screen + 확인 질문 순서로 조립하세요.`,targetEn:`Let me share my screen— can everyone see it?`,chunks:[`Let me`,`share my screen—`,`can everyone`,`see it?`],explanationKo:`화면 공유 직후 "Can everyone see it?"으로 확인하는 것이 실무 기본 매너입니다.`},{id:`d13-s04`,drillType:`active-blank`,promptKo:`목소리가 조금 끊기고 있어요.`,promptEnHint:`음성이 지직거리며 끊기다: break의 -ing형(8글자)`,targetEn:`You're breaking up a bit.`,blankData:{before:`You're`,answer:`breaking`,after:`up a bit.`,firstLetterHint:`b_______ (8글자)`},explanationKo:`통화 중 음성이 끊기는 상황은 현재진행형 "You're breaking up"을 사용합니다.`},{id:`d13-s05`,drillType:`active-blank`,promptKo:`최신 자료를 여는 동안 잠시만 기다려 주세요.`,promptEnHint:`잠시만 양해하고 기다려 주세요: ____ with me (4글자)`,targetEn:`Bear with me for a second.`,blankData:{before:``,answer:`Bear`,after:`with me for a second.`,firstLetterHint:`B___ (4글자)`},explanationKo:`Bear with me는 기술적 준비나 파일 로딩 중 정중히 양해를 구하는 핵심 표현입니다.`},{id:`d13-s06`,drillType:`konglish-fix`,promptKo:`"화면에 있는 3분기 자료를 차근차근 설명해 드릴게요."`,promptEnHint:`explain you는 문법 오류! 올바른 구동사 구문을 고르세요.`,targetEn:`I'll walk you through the Q3 slides.`,wrongKonglishOption:`I'll explain you the Q3 slides.`,explanationKo:`walk [사람] through [자료]는 문법적으로도 정확하고 발표에 최적화된 표현입니다.`},{id:`d13-s07`,drillType:`chunk-build`,promptKo:`바로 오늘 아젠다로 들어가 보죠.`,promptEnHint:`Let’s + jump right into 패턴을 조립하세요.`,targetEn:`Let's jump right into today's agenda.`,chunks:[`Let's`,`jump right into`,`today's`,`agenda.`],explanationKo:`불필요한 지연 없이 본론으로 진입할 때 jump right into를 씁니다.`},{id:`d13-s08`,drillType:`active-blank`,promptKo:`방금 몇 초간 소리가 완전히 끊겼어요.`,promptEnHint:`소리가 뚝 끊기다: cut ___ (3글자)`,targetEn:`Your audio cut out for a second.`,blankData:{before:`Your audio cut`,answer:`out`,after:`for a second.`,firstLetterHint:`o__ (3글자)`},explanationKo:`오디오 신호가 일시적으로 완전히 사라질 때 cut out을 사용합니다.`},{id:`d13-s09`,drillType:`konglish-fix`,promptKo:`"제 화면이 멈춰서 나갔다가 다시 접속할게요."`,promptEnHint:`화면이 멈추다(frozen) + 재접속(log back in) 표현을 확인하세요.`,targetEn:`My screen is frozen, so I'll log back in.`,wrongKonglishOption:`My monitor stopped, so I'll enter again.`,explanationKo:`화면 멈춤은 frozen, 화상회의 재접속은 log back in이라고 합니다.`},{id:`d13-s10`,drillType:`chunk-build`,promptKo:`다음 일정이 있어서 5분 일찍 먼저 나가봐야 해요.`,promptEnHint:`drop off + a few minutes early 청크를 연결하세요.`,targetEn:`I need to drop off five minutes early.`,chunks:[`I need to`,`drop off`,`five minutes`,`early.`],explanationKo:`화상회의에서 먼저 퇴장할 때는 leave보다 drop off가 훨씬 자연스럽습니다.`}],worksheetExam:[{id:`d13-e01`,number:1,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`화상회의 오프닝 hop on`,questionKo:`빈칸에 알맞은 구동사(2단어, 동명사 포함)를 넣어 "오늘 회의에 접속해 주셔서 감사합니다"를 완성하세요.`,stimulusEn:`Thanks for __________ __________ this morning, everyone.`,answer:`hopping on`,acceptableAlt:[`joining us`],explanationKo:`전치사 for 뒤이므로 동명사 형태인 hopping on을 씁니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "지금 잠깐 10분 통화 가능할까요?" 빈칸 구동사(2단어)를 채우세요.`,stimulusEn:`Can you __________ __________ a quick ten-minute call right now?`,answer:`hop on`,explanationKo:`조동사 Can 뒤이므로 원형 hop on을 씁니다.`}},{id:`d13-e02`,number:2,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`음소거 전치사 on mute`,questionKo:`빈칸에 전치사구(2단어)를 넣어 "죄송하지만 아직 음소거 상태이신 것 같아요"를 완성하세요.`,stimulusEn:`Sorry, I think you're still __________ __________.`,answer:`on mute`,explanationKo:`마이크가 꺼진 상태는 반드시 전치사 on과 함께 on mute라고 씁니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "음소거를 해제해 주시겠어요?" 빈칸 동사(1단어)를 쓰세요.`,stimulusEn:`Could you please __________ yourself?`,answer:`unmute`,explanationKo:`음소거 해제는 동사 unmute를 씁니다.`}},{id:`d13-e03`,number:3,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`음성 끊김 break up`,questionKo:`빈칸에 알맞은 구동사(2단어, 진행형)를 넣어 "목소리가 좀 끊겨서요"를 완성하세요.`,stimulusEn:`Sorry, you're __________ __________ a bit—could you repeat that?`,answer:`breaking up`,explanationKo:`신호 불량으로 음성이 지직거리며 끊길 때는 진행형 breaking up을 씁니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "방금 몇 초간 오디오가 완전히 끊겼어요" 빈칸 구동사(2단어, 과거형)를 채우세요.`,stimulusEn:`Your audio __________ __________ for a few seconds.`,answer:`cut out`,explanationKo:`cut의 과거형은 cut이며, 소리 완전 소실은 cut out입니다.`}},{id:`d13-e04`,number:4,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`단계별 설명 walk through`,questionKo:`빈칸에 알맞은 2단어를 넣어 "제가 새 대시보드를 차근차근 설명해 드릴게요"를 완성하세요.`,stimulusEn:`I'll __________ you __________ the new dashboard.`,answer:`walk through`,explanationKo:`walk [사람] through [자료]는 슬라이드나 화면을 함께 보며 안내할 때 필수 표현입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "파일 여는 동안 잠시만 기다려 주세요" 빈칸(3단어)을 채우세요.`,stimulusEn:`__________ __________ __________ for just a second while I open the file.`,answer:`Bear with me`,explanationKo:`정중한 대기 요청은 Bear with me입니다.`}},{id:`d13-e05`,number:5,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`회의 퇴장·마무리 drop off / wrap up`,questionKo:`빈칸에 구동사(2단어)를 넣어 "다음 회의가 있어 5분 일찍 먼저 나가야 해요"를 완성하세요.`,stimulusEn:`I have another meeting at 3, so I need to __________ __________ five minutes early.`,answer:`drop off`,explanationKo:`화상회의에서 먼저 나가는 것은 drop off가 가장 자연스럽습니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "여기서 회의를 깔끔하게 마무리하죠" 빈칸 구동사(2단어)를 쓰세요.`,stimulusEn:`Let's __________ __________ here and follow up in Slack.`,answer:`wrap up`,explanationKo:`회의를 마무리 짓는 구동사는 wrap up입니다.`}},{id:`d13-e06`,number:6,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`on mute 콩글리시 구분`,questionKo:`화상회의 중 동료가 마이크를 끈 채 말하고 있을 때 가장 자연스럽고 예의 바른 알림은?`,stimulusEn:`상대방의 마이크가 꺼져 있는 상황입니다.`,options:[`Hey, you are mute! Open your voice.`,`Sorry, I think you're on mute.`,`Your microphone is dead now.`,`Please turn on your speaking.`],answer:`Sorry, I think you're on mute.`,explanationKo:`"You are mute"는 실례가 되는 표현이며, "You're on mute"가 글로벌 화상회의 표준입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "배경 소음 때문에 잠시 음소거로 전환할게요" 빈칸 전치사구(2단어)를 쓰세요.`,stimulusEn:`There's some background noise here, so I'll go __________ __________ for a second.`,answer:`on mute`,explanationKo:`음소거로 전환하다는 go on mute라고 씁니다.`}},{id:`d13-e07`,number:7,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`화면 멈춤 & 재접속 표현`,questionKo:`상대방의 영상이 정지해 있고 연결이 버벅거릴 때 원어민이 쓰는 가장 자연스러운 문장은?`,stimulusEn:`영상 정지 + 재접속 제안 상황입니다.`,options:[`Your face stopped and you have computer delay.`,`Your screen is frozen—maybe try logging back in.`,`Your camera died completely to ice.`,`Your picture is closing on my window.`],answer:`Your screen is frozen—maybe try logging back in.`,explanationKo:`화면 정지는 frozen, 나갔다가 다시 들어오는 것은 log back in입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "약간의 지연(렉)이 있어서 카메라를 끌게요" 빈칸 명사(1단어)를 쓰세요.`,stimulusEn:`There's a slight __________ on my end, so I'll turn off my camera.`,answer:`lag`,explanationKo:`네트워크 지연 현상은 lag이라고 합니다.`}},{id:`d13-e08`,number:8,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`explain 오류 vs walk through`,questionKo:`발표 자료를 공유하며 "제가 이 보고서를 차례대로 설명해 드릴게요"라고 할 때 어법상 올바른 문장은?`,stimulusEn:`explain과 walk through의 목적어 구조를 비교하세요.`,options:[`I'll explain you this report step by step.`,`I'll walk you through this report.`,`I'll explain about you this report.`,`I'll walk through you this report.`],answer:`I'll walk you through this report.`,explanationKo:`explain은 바로 뒤에 사람을 목적어로 취할 수 없으며, walk [사람] through [자료] 어순이 정확합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "바로 오늘의 핵심 안건으로 들어가 보죠" 빈칸(3단어)을 채우세요.`,stimulusEn:`Let's __________ __________ __________ today's main agenda.`,answer:`jump right into`,explanationKo:`명사 목적어(today's main agenda)가 바로 이어지면 전치사 into를 써서 jump right into로 연결합니다.`}},{id:`d13-e09`,number:9,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`마이크 울림(echo) 대처`,questionKo:`회의 중 같은 공간에서 두 명이 마이크를 켜서 소리가 울릴 때 가장 정확한 표현은?`,stimulusEn:`오디오 하울링·울림이 발생하는 상황입니다.`,options:[`We're getting a strong echo on the line.`,`We're hearing double mirror sounds.`,`The speaker is ringing like a bell.`,`Our voices are copying twice loudly.`],answer:`We're getting a strong echo on the line.`,explanationKo:`화상회의에서 마이크 울림 현상은 echo라고 하며 "There's an echo / We're getting an echo"로 말합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "제 목소리 또렷하게 잘 들리시나요?"에 대한 원어민 단골 응답(3단어: L___ a__ c____)을 쓰세요.`,stimulusEn:`Yes, we can hear you __________ __________ __________!`,answer:`loud and clear`,explanationKo:`loud and clear는 통화·화상회의에서 소리가 아주 선명하게 들린다는 관용 표현입니다.`}},{id:`d13-e10`,number:10,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`정중한 대기 요청 bear with me`,questionKo:`화면 공유할 슬라이드 창을 찾는 3초 동안 상대방에게 양해를 구할 때 가장 프로다운 표현은?`,stimulusEn:`Wait! 대신 세련된 비즈니스 표현을 고르세요.`,options:[`Stop and wait me until I find.`,`Bear with me for a second while I pull up the slides.`,`Be patient to my slow computer now.`,`Hold your mouth while I open window.`],answer:`Bear with me for a second while I pull up the slides.`,explanationKo:`Bear with me for a second + while I pull up ~ 은 글로벌 회의에서 매일 쓰이는 매너 표현입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "발표 자료를 화면에 띄우다"에 알맞은 구동사(2단어)를 빈칸에 쓰세요.`,stimulusEn:`Let me __________ __________ the Q3 sales deck right now.`,answer:`pull up`,explanationKo:`컴퓨터 화면에 파일이나 창을 불러와 띄우는 동작을 pull up이라고 합니다.`}},{id:`d13-e11`,number:11,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`화면 공유 확인 질문 배열`,questionKo:`주어진 청크를 올바른 순서로 배열하여 화면 공유 확인 문장을 완성하세요.`,stimulusEn:`[ my screen / everyone / Let me / share / — can / see it? ]`,answer:`Let me share my screen—can everyone see it?`,acceptableAlt:[`Let me share my screen — can everyone see it?`,`Let me share my screen, can everyone see it?`],explanationKo:`Let me share my screen(예고) + can everyone see it?(확인) 조합입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "제 슬라이드가 잘 보이시나요?" (Can everyone / see my slides / clearly?)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`Can everyone see my slides clearly?`,explanationKo:`Can everyone see + [대상] + clearly? 패턴입니다.`}},{id:`d13-e12`,number:12,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`오디오 끊김 대처 배열`,questionKo:`주어진 청크를 배열하여 음성 끊김을 알리고 다시 말해 달라고 요청하는 문장을 완성하세요.`,stimulusEn:`[ a bit / breaking up / Sorry, / could you / you're / — / repeat that? ]`,answer:`Sorry, you're breaking up a bit—could you repeat that?`,acceptableAlt:[`Sorry, you're breaking up a bit — could you repeat that?`,`Sorry, you're breaking up a bit, could you repeat that?`],explanationKo:`Sorry, you're breaking up a bit 뒤에 정중한 요청 could you repeat that?을 연결합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "방금 잠깐 끊겼어요." (You cut out / for a second.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`You cut out for a second.`,explanationKo:`일시적 오디오 소실은 You cut out for a second.라고 간단히 말합니다.`}},{id:`d13-e13`,number:13,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`본론 진입 & 안내 영작`,questionKo:`우리말 뜻에 맞게 주어진 단어를 활용해 자연스러운 오프닝 문장을 완성하세요.`,stimulusEn:`우리말: 바로 본론으로 들어가서 슬라이드를 차근차근 설명해 드릴게요. (Let’s / jump right in / and I’ll / walk you through / the slides.)`,answer:`Let's jump right in, and I'll walk you through the slides.`,acceptableAlt:[`Let's jump right in and I'll walk you through the slides.`],explanationKo:`jump right in(본론 진입)과 walk you through(단계별 안내)를 자연스럽게 연결한 문장입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "오늘 아젠다로 바로 들어가 보죠." (Let’s jump right into / today’s agenda.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`Let's jump right into today's agenda.`,explanationKo:`jump right into + 명사 패턴입니다.`}},{id:`d13-e14`,number:14,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`콩글리시 교정 서술형`,questionKo:`다음 콩글리시 문장을 오늘 배운 표현(on mute, unmute yourself)으로 바르게 고쳐 쓰세요.`,stimulusEn:`오류 문장: Sorry, you are mute. Could you open your mic?`,answer:`Sorry, you're on mute. Could you unmute yourself?`,acceptableAlt:[`Sorry, you are on mute. Could you unmute yourself?`,`Sorry, you're on mute. Could you unmute your mic?`],explanationKo:`you are mute → you're on mute, open your mic → unmute yourself로 고치면 완벽합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 오류 교정: Your face stopped! → frozen을 사용해 4단어로 고치세요.`,stimulusEn:`힌트: Your video is ~.`,answer:`Your video is frozen.`,explanationKo:`화면 정지는 Your video(screen) is frozen.이라고 표현합니다.`}},{id:`d13-e15`,number:15,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`실전 통문장 영작`,questionKo:`다음 우리말을 영어로 자연스럽게 작성하세요.`,stimulusEn:`우리말: 다시 끊기면 잠깐 나갔다가 재접속할게요. (힌트: If I cut out again, / I’ll drop off / and log back in.)`,answer:`If I cut out again, I'll drop off and log back in.`,explanationKo:`기술 장애 시 프로페셔널하게 대처 계획을 공유하는 실전 문장입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "여기서 마무리하고 회의록은 슬랙에 공유할게요." (Let’s wrap up here / and share the notes / on Slack.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`Let's wrap up here and share the notes on Slack.`,explanationKo:`wrap up here로 회의를 닫고 후속 공유 채널을 명확히 안내합니다.`}}],tutorScenario:{openingQuestionEn:`Hi! Thanks for hopping on today's weekly sync. Before we jump right in, could you share your screen with the Q3 draft? Oh—wait, I think you're breaking up a little bit!`,openingQuestionKo:`안녕하세요! 오늘 주간 싱크에 접속해 주셔서 감사합니다. 바로 시작하기 전에 3분기 초안 화면 공유해 주실 수 있을까요? 어, 잠깐만요, 목소리가 조금 끊기시는 것 같아요! (카메라를 끄거나 양해를 구하며 화면 공유를 확인해 보세요.)`,followUpQuestionEn:`Much clearer now, and yes, I can see your screen loud and clear! Go ahead and walk me through the main highlights whenever you are ready.`,followUpQuestionKo:`이제 훨씬 선명하게 들리고 화면도 잘 보입니다! 준비되시면 핵심 내용을 차근차근 설명해 주세요.`,recommendedChunks:[`Bear with me for a second`,`switch off my camera`,`share my screen`,`can you see it clearly?`,`walk you through`],modelAnswerEn:`Thanks for letting me know! Let me switch off my camera to fix the lag—bear with me for a second while I share my screen. Can you see the Q3 draft clearly now?`}},{dayNumber:14,weekNumber:3,cefrLevel:`b1`,dayBadge:`DAY 14 · 영문 이메일 구조 & 회신 요청`,categoryLabel:`Week 3 오피스 실무 · 영문 이메일 & 협업 팔로업`,title:`첨부 파일 확인 부탁드립니다`,subtitle:`콩글리시 직역 이메일에서 벗어나, 미국 오피스 표준 구조로 첨부 안내·리마인드·회신 요청을 간결하고 세련되게 쓰는 법`,heroImage:`assets/office_sitcom_scene.jpg`,secondaryImage:`assets/scene_video_call.jpg`,estimatedSprintMin:8,estimatedLectureMin:40,keyExpression:`Please find the deck attached, and I'll circle back by Friday.`,keySentenceByTier:{a1:`I attached the file. Please check it and reply to me.`,a2:`Please check the attached file and let me know what you think.`,b1:`I've attached the updated proposal for your review—please let me know your thoughts by Thursday.`,b2:`Per our conversation, please find the Q4 deck attached, and I'll circle back with final numbers by EOD Friday.`,c1:`I'm reaching out to touch base on the attached contract; I've CC'd legal to keep everyone in the loop and would appreciate your sign-off at your earliest convenience.`,c2:`Following up on yesterday's sync, I've attached the revised scope along with a quick heads-up on timeline risks—do let me know if any adjustments are needed before we lock in the launch.`},youtubeVideo:e[14],readingPassage:{titleEn:`Subject: Q4 Launch Deck & Quick Follow-Up`,titleKo:`[실무 이메일 사례] 4분기 런칭 덱 첨부 및 정중한 회신 팔로업`,genreBadge:`실무 이메일 스레드 · Lv.3`,estimatedMin:5,paragraphsEn:[`Hi Marcus, I hope your week is off to a smooth start. Per our conversation yesterday, I have attached the revised Q4 campaign deck along with the media budget breakdown. I also CC'd Hannah from finance on this thread to keep her in the loop on the updated spend.`,`Just a quick heads-up: our agency needs final approval on the creative assets by Thursday afternoon to hold our ad slots. If you could look over slides four through seven and sign off on the copy at your earliest convenience, we will stay right on schedule.`,`I know you have a busy week ahead, so I will circle back tomorrow morning as a gentle reminder if I haven't heard from you. In the meantime, feel free to reach out on Slack if you would like to touch base on any details before I am out of office on Friday.`],paragraphsSlash:[`Hi Marcus, / I hope your week is off to a smooth start. / Per our conversation yesterday, / I have attached the revised Q4 campaign deck / along with the media budget breakdown. / I also CC'd Hannah from finance on this thread / to keep her in the loop / on the updated spend.`,`Just a quick heads-up: / our agency needs final approval / on the creative assets by Thursday afternoon / to hold our ad slots. / If you could look over slides four through seven / and sign off on the copy / at your earliest convenience, / we will stay right on schedule.`,`I know you have a busy week ahead, / so I will circle back tomorrow morning / as a gentle reminder / if I haven't heard from you. / In the meantime, / feel free to reach out on Slack / if you would like to touch base on any details / before I am out of office on Friday.`],paragraphsKo:[`안녕하세요 마커스, 이번 주 순조롭게 시작하셨길 바랍니다. 어제 나눈 대화에 따라 수정된 4분기 캠페인 자료와 매체 예산 세부 내역을 첨부해 드립니다. 변경된 지출 내역을 함께 공유받으실 수 있도록 재무팀의 한나 님도 이 이메일 스레드 참조(CC)에 넣었습니다.`,`미리 한 가지 귀띔드리자면, 광고 구좌를 확보하기 위해 에이전시에서 목요일 오후까지 크리에이티브 시안 최종 승인이 필요합니다. 편하신 가장 빠른 시간에 4~7번 슬라이드를 검토하시고 카피를 최종 승인해 주시면 일정대로 정확히 진행할 수 있습니다.`,`이번 주 많이 바쁘신 줄 알기에 회신이 없으시면 내일 오전에 정중한 리마인드로 다시 연락드리겠습니다. 그사이에 제가 금요일 부재중(휴가)에 들어가기 전 세부 사항을 간단히 논의하고 싶으시다면 언제든 슬랙으로 편하게 연락 주세요.`],keyExpressions:[`per our conversation`,`attach / as attached`,`keep ~ in the loop`,`a quick heads-up`,`sign off on`,`circle back / touch base`],comprehensionQuiz:[{id:`d14-rq01`,questionKo:`발신자가 재무팀의 한나(Hannah) 님을 참조(CC)에 넣은 이유는 무엇인가요?`,options:[`크리에이티브 카피를 직접 수정해 달라고 요청하기 위해`,`변경된 예산 지출 내역을 계속 공유받도록 하기 위해(keep her in the loop)`,`금요일에 대신 휴가 업무를 인계받기 위해`,`에이전시 담당자 연락처를 물어보기 위해`],answer:`변경된 예산 지출 내역을 계속 공유받도록 하기 위해(keep her in the loop)`,explanationKo:`첫째 문단 "to keep her in the loop on the updated spend"가 정확한 이유입니다.`},{id:`d14-rq02`,questionKo:`에이전시가 목요일 오후까지 최종 승인을 필요로 하는 이유는 무엇인가요?`,options:[`광고 구좌(ad slots)를 확보·유지하기 위해`,`재무 감사가 목요일에 시작되기 때문에`,`마커스가 금요일에 출장을 떠나기 때문에`,`예산안을 처음부터 다시 작성해야 하기 때문에`],answer:`광고 구좌(ad slots)를 확보·유지하기 위해`,explanationKo:`둘째 문단 "needs final approval on the creative assets by Thursday afternoon to hold our ad slots"를 확인하세요.`},{id:`d14-rq03`,questionKo:`본문에서 "어제 나눈 대화에 따라(말씀드린 대로)"를 격식 있게 표현한 문구는?`,options:[`As a gentle reminder`,`At your earliest convenience`,`Per our conversation yesterday`,`In the meantime`],answer:`Per our conversation yesterday`,explanationKo:`Per our conversation / Per our call은 이전 논의를 깔끔하게 연결하는 영문 이메일 핵심 표현입니다.`}]},vocabList:[{id:`d14-v01`,word:`attach`,phonetic:`/əˈtætʃ/`,pos:`동사`,cefr:`b1`,meaningKo:`(이메일에 파일을) 첨부하다`,meaningEn:`include a document or file with an email`,nuanceTipKo:`능동형 "I've attached the file" 또는 수동/형용사형 "Please find the file attached" 둘 다 이메일 필수 패턴입니다.`,exampleEn:`I've attached the signed contract for your records.`,exampleKo:`보관하실 수 있도록 서명된 계약서를 첨부해 드렸습니다.`},{id:`d14-v02`,word:`as attached`,phonetic:`/æz əˈtætʃt/`,pos:`관용 구문`,cefr:`b1`,meaningKo:`첨부된 바와 같이, 첨부 파일처럼`,meaningEn:`as shown in the file included with this email`,nuanceTipKo:`표나 문서를 언급하며 "첨부 파일과 같이 정리했습니다"라고 쓸 때 "as attached" 또는 "in the attached file"을 활용합니다.`,exampleEn:`Please review the updated schedule as attached and confirm your slot.`,exampleKo:`첨부된 바와 같이 수정된 일정을 확인하시고 가능 시간을 확정해 주세요.`},{id:`d14-v03`,word:`touch base`,phonetic:`/tʌtʃ beɪs/`,pos:`관용구`,cefr:`b2`,meaningKo:`(진행 상황 확인·안부를 위해) 가볍게 연락하다`,meaningEn:`make brief contact with someone to check in or align on updates`,nuanceTipKo:`야구 주자가 베이스를 살짝 밟고 지나가듯, 무겁지 않게 근황이나 업무 진행을 짧게 확인하려 연락할 때 씁니다. (touch base with [사람] on [안건])`,exampleEn:`Just wanted to touch base with you on the Q4 budget proposal.`,exampleKo:`4분기 예산안 건으로 진행 상황 가볍게 여쭤보려고 연락드렸습니다.`},{id:`d14-v04`,word:`circle back`,phonetic:`/ˈsɜːrkl bæk/`,pos:`구동사`,cefr:`b2`,meaningKo:`(검토·확인 후) 다시 회신하다, 추후 재논의하다`,meaningEn:`return to a person or topic later after checking details`,nuanceTipKo:`지금 당장 확답하기 어려울 때 "I'll check with the team and circle back by tomorrow"라고 하면 신뢰감이 배가 됩니다.`,exampleEn:`Let me confirm with legal and circle back to you by 3 PM.`,exampleKo:`법무팀에 확인한 뒤 오후 3시까지 다시 회신드리겠습니다.`},{id:`d14-v05`,word:`follow up on`,phonetic:`/ˈfɑːloʊ ʌp ɑːn/`,pos:`구동사`,cefr:`b1`,meaningKo:`~에 대해 후속 확인하다, 리마인드 메일을 보내다`,meaningEn:`check on the status of something previously sent or discussed`,nuanceTipKo:`답장이 안 온 상대에게 "Why didn't you reply?" 대신 "Just following up on my email from Tuesday"라고 쓰면 세련된 재촉이 됩니다.`,exampleEn:`I'm writing to follow up on the invoice I sent last Monday.`,exampleKo:`지난주 월요일에 보내드린 인보이스 건을 후속 확인차 연락드립니다.`},{id:`d14-v06`,word:`give ~ a heads-up`,phonetic:`/ɡɪv ə ˈhedz ʌp/`,pos:`관용구`,cefr:`b2`,meaningKo:`~에게 미리 귀띔하다, 사전 공지하다`,meaningEn:`warn or inform someone in advance about something upcoming`,nuanceTipKo:`일정 변경, 휴가, 급한 승인 요청 등을 미리 알려줄 때 "Just a quick heads-up:"으로 시작하면 배려심 있는 프로로 보입니다.`,exampleEn:`Just wanted to give you a heads-up that the server maintenance starts at 8 PM.`,exampleKo:`오후 8시에 서버 점검이 시작된다는 점 미리 귀띔드리려고요.`},{id:`d14-v07`,word:`at your earliest convenience`,phonetic:`/æt jʊr ˈɜːrliɪst kənˈviːniəns/`,pos:`전치사구`,cefr:`b2`,meaningKo:`편하신 가장 빠른 시간에 (정중한 회신 요청)`,meaningEn:`as soon as you reasonably can, without being pushy`,nuanceTipKo:`"ASAP"는 상사나 클라이언트에게 무례하게 들릴 수 있습니다! 격식 있는 영문 이메일에서는 "at your earliest convenience"가 정답입니다.`,exampleEn:`Could you please review and return the signed form at your earliest convenience?`,exampleKo:`편하신 가장 빠른 시간에 양식을 검토해 서명 후 회신해 주실 수 있을까요?`},{id:`d14-v08`,word:`keep ~ in the loop`,phonetic:`/kiːp ɪn ðə luːp/`,pos:`관용구`,cefr:`b2`,meaningKo:`~에게 계속 진행 상황을 공유하다, 소통 고리에 포함시키다`,meaningEn:`continue to inform someone about developments in a project`,nuanceTipKo:`CC에 팀장이나 협업 부서를 추가할 때 이유를 밝히는 최고의 표현입니다. 반대말은 out of the loop(정보에서 소외된)입니다.`,exampleEn:`I've added our designer to the thread to keep her in the loop.`,exampleKo:`디자이너님께도 계속 진행 상황을 공유드리려고 스레드에 추가했습니다.`},{id:`d14-v09`,word:`cc (someone) on`,phonetic:`/ˌsiːˈsiː ɑːn/`,pos:`동사 구문`,cefr:`b1`,meaningKo:`~를 이메일 참조(CC)에 넣다`,meaningEn:`include someone as a carbon copy recipient on an email thread`,nuanceTipKo:`전치사는 in이 아니라 on을 씁니다! "I've CC'd David on this email(thread)" 형태로 정확히 기억하세요.`,exampleEn:`I've CC'd our account manager on this email so she can assist with billing.`,exampleKo:`결제 지원을 도와드릴 수 있도록 담당 어카운트 매니저를 이 메일 참조에 넣었습니다.`},{id:`d14-v10`,word:`reach out`,phonetic:`/riːtʃ aʊt/`,pos:`구동사`,cefr:`b1`,meaningKo:`(문의·협업·도움을 위해) 연락하다`,meaningEn:`contact someone to ask a question, offer help, or initiate a conversation`,nuanceTipKo:`contact보다 따뜻하고 협업 친화적인 표현이며, 사람 앞에는 반드시 전치사 to(reach out to you)를 붙입니다.`,exampleEn:`Please feel free to reach out if you have any questions about the report.`,exampleKo:`보고서와 관련해 궁금한 점이 있으시면 언제든 편하게 연락 주세요.`},{id:`d14-v11`,word:`get back to`,phonetic:`/ɡet bæk tuː/`,pos:`구동사`,cefr:`b1`,meaningKo:`(확인 후) ~에게 다시 답장·연락하다`,meaningEn:`reply to someone once you have the needed information`,nuanceTipKo:`이메일 마무리 문장 "I'll get back to you by tomorrow afternoon"은 circle back과 함께 가장 자주 쓰이는 회신 약속입니다.`,exampleEn:`Thank you for your patience—I'll get back to you with an update by noon.`,exampleKo:`기다려 주셔서 감사합니다. 정오까지 업데이트 내용으로 회신드리겠습니다.`},{id:`d14-v12`,word:`per our conversation`,phonetic:`/pɜːr ˈaʊər ˌkɑːnvərˈseɪʃn/`,pos:`전치사구`,cefr:`b2`,meaningKo:`앞서 나눈 대화에 따라, 말씀드린 대로`,meaningEn:`as agreed or mentioned in our earlier discussion`,nuanceTipKo:`전화나 미팅 직후 후속 자료를 보낼 때 첫 문장을 "Per our conversation," 또는 "As discussed,"로 시작하면 프로페셔널합니다.`,exampleEn:`Per our conversation earlier, here is the revised onboarding checklist.`,exampleKo:`앞서 나눈 대화대로 수정된 온보딩 체크리스트를 보내드립니다.`},{id:`d14-v13`,word:`a gentle reminder`,phonetic:`/ə ˈdʒentl rɪˈmaɪndər/`,pos:`명사구`,cefr:`b2`,meaningKo:`정중한 리마인드, 부드러운 재안내`,meaningEn:`a polite follow-up message prompting someone to take action`,nuanceTipKo:`마감이 다가오는데 회신이 없을 때 공격적으로 들리지 않게 쿠션을 깔아주는 이메일 치트키입니다.`,exampleEn:`Just sending a gentle reminder that feedback is due by 5 PM today.`,exampleKo:`오늘 오후 5시가 피드백 마감이라는 점을 정중히 다시 안내드립니다.`},{id:`d14-v14`,word:`sign off on`,phonetic:`/saɪn ɔːf ɑːn/`,pos:`구동사`,cefr:`b2`,meaningKo:`~을 최종 승인하다, 결재하다`,meaningEn:`give official approval to a plan, budget, or document`,nuanceTipKo:`confirm보다 명확하게 "최종 의사결정권자의 승인(OK)"을 요청할 때 전치사 on과 함께 씁니다.`,exampleEn:`Once the client signs off on the wireframe, development can begin.`,exampleKo:`클라이언트가 와이어프레임을 최종 승인하면 바로 개발에 착수할 수 있습니다.`},{id:`d14-v15`,word:`out of office (OOO)`,phonetic:`/aʊt əv ˈɔːfɪs/`,pos:`전치사구`,cefr:`b1`,meaningKo:`부재중 (휴가·외근·출장 등으로 자리를 비운 상태)`,meaningEn:`away from work on vacation, leave, or business travel`,nuanceTipKo:`자동 회신 메일이나 사전 공지에서 "I'll be out of office from Thursday to Friday"라고 쓰며 슬랙에서는 OOO로 줄여 씁니다.`,exampleEn:`Just a heads-up that I will be out of office next Monday with limited access to email.`,exampleKo:`다음 주 월요일에 부재중이라 이메일 확인이 어렵다는 점 미리 안내드립니다.`}],dialogue:[{id:`d14-t01`,speaker:`Minseo`,roleLabel:`마케팅 매니저`,voicePitch:1.07,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`zoom-in`,english:`Hey Daniel, do you have two minutes? Could you look over this client email before I hit send?`,slashBroken:`Hey Daniel, / do you have two minutes? / Could you look over this client email / before I hit send?`,korean:`다니엘, 2분만 시간 괜찮아? 발송 버튼 누르기 전에 이 클라이언트 이메일 한 번만 봐줄래?`,keyHighlight:`before I hit send`,noteKo:`이메일 전송 버튼을 누르다는 "click the send button"보다 "hit send"가 훨씬 원어민답습니다.`},{id:`d14-t02`,speaker:`Daniel`,roleLabel:`시니어 카피라이터`,voicePitch:.93,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`pan-right`,english:`Sure thing! Hmm, right here you wrote "Please reply ASAP." For a new client, that might sound a bit pushy.`,slashBroken:`Sure thing! / Hmm, right here you wrote "Please reply ASAP." / For a new client, / that might sound a bit pushy.`,korean:`물론이지! 음, 여기 "ASAP로 답장해 주세요"라고 썼네. 신규 클라이언트한테는 좀 재촉하는 느낌으로 들릴 수 있어.`,keyHighlight:`sound a bit pushy`,noteKo:`ASAP는 급박한 내부 장애 대응 외에는 무례하거나 압박(pushy)처럼 느껴질 수 있어 주의해야 합니다.`},{id:`d14-t03`,speaker:`Minseo`,roleLabel:`마케팅 매니저`,voicePitch:1.07,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`pan-left`,english:`Good catch! Should I change it to "at your earliest convenience" or give them a specific deadline?`,slashBroken:`Good catch! / Should I change it to "at your earliest convenience" / or give them a specific deadline?`,korean:`잘 짚어줬어! "편하신 가장 빠른 시간에"로 바꾸는 게 좋을까, 아니면 구체적인 마감일을 적어주는 게 나을까?`,keyHighlight:`at your earliest convenience`,noteKo:`상대가 실수나 포인트를 잘 찾아냈을 때 "Good catch!"라고 칭찬하는 표현도 오피스 필수입니다.`},{id:`d14-t04`,speaker:`Daniel`,roleLabel:`시니어 카피라이터`,voicePitch:.93,sceneImage:`assets/scene_video_call.jpg`,cameraMotion:`zoom-in`,english:`Try combining both: "Please find the proposal attached, and let us know if you can sign off on it by Thursday."`,slashBroken:`Try combining both: / "Please find the proposal attached, / and let us know / if you can sign off on it by Thursday."`,korean:`둘 다 섞어 봐. "제안서를 첨부해 드리오니, 목요일까지 최종 승인 가능하신지 알려주세요"처럼 부드럽지만 명확하게.`,keyHighlight:`Please find the proposal attached`,noteKo:`구체적인 날짜(by Thursday)를 정중한 조건절(if you can ~)로 감싸면 부담은 줄고 회신율은 높아집니다.`},{id:`d14-t05`,speaker:`Minseo`,roleLabel:`마케팅 매니저`,voicePitch:1.07,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`pan-right`,english:`That reads way smoother! Also, I CC'd our finance lead on this thread to keep him in the loop.`,slashBroken:`That reads way smoother! / Also, I CC'd our finance lead on this thread / to keep him in the loop.`,korean:`훨씬 매끄럽게 읽힌다! 그리고 재무 리드님도 계속 진행 상황을 아시도록 이 스레드 참조에 넣었어.`,keyHighlight:`CC'd our finance lead on this thread`,noteKo:`글이 자연스럽게 읽힌다고 할 때 "That reads smooth(er)"처럼 read를 자동사로 쓰는 표현도 아주 고급스럽습니다.`},{id:`d14-t06`,speaker:`Daniel`,roleLabel:`시니어 카피라이터`,voicePitch:.93,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`pan-left`,english:`Smart move. One last thing—add a quick heads-up that you'll be out of office on Friday, so they know who to reach out to.`,slashBroken:`Smart move. / One last thing— / add a quick heads-up / that you'll be out of office on Friday, / so they know who to reach out to.`,korean:`잘했어. 마지막으로 하나만 더—금요일에 네가 부재중이라는 점 미리 귀띔해 두면 누구에게 연락해야 할지 알 수 있잖아.`,keyHighlight:`add a quick heads-up`,noteKo:`휴가·출장 전에는 out of office 일정과 대체 연락처(reach out to)를 미리 안내하는 것이 글로벌 에티켓입니다.`},{id:`d14-t07`,speaker:`Minseo`,roleLabel:`마케팅 매니저`,voicePitch:1.07,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`zoom-in`,english:`Done! I'll hit send now and circle back with them tomorrow afternoon if I don't hear back.`,slashBroken:`Done! / I'll hit send now / and circle back with them tomorrow afternoon / if I don't hear back.`,korean:`수정 완료! 지금 바로 보내고 답장 안 오면 내일 오후에 다시 팔로업할게.`,keyHighlight:`circle back with them`,noteKo:`hear back(회신을 받다)과 circle back(다시 연락·회신하다)이 한 문장에서 완벽하게 호흡을 맞춥니다.`}],grammarSections:[{title:`원리 01 · 첨부 파일 안내 3단계 공식: attach 동사 vs. attached 과거분사`,coreFormula:`I've attached [파일] / Please find [파일] attached / Please see the attached [파일]`,wrongKonglish:`I attach file in this mail. Please check the attach.`,rightNative:`I've attached the updated deck for your review. Please find the budget sheet attached as well.`,explanationKo:`attach는 동사이므로 명사처럼 "the attach"라고 쓰면 안 되며, 이메일을 발송하는 시점에는 이미 첨부가 완료된 상태이므로 현재완료("I've attached ~") 또는 목적격보어 과거분사("Please find [파일] attached")가 표준입니다. "첨부 파일" 명사는 attachment입니다.`,registerSpectrum:{casual:`Here's the deck—I attached it below!`,standard:`I've attached the updated proposal for your review.`,formal:`Please find the finalized agreement attached for your signature.`}},{title:`원리 02 · 미묘한 이메일 팔로업 3대장: follow up on vs. circle back vs. touch base`,coreFormula:`미회신 재확인 = follow up on / 확인 후 재회신 약속 = circle back / 가벼운 근황·점검 = touch base`,wrongKonglish:`Why didn't you answer my mail? Please reply fast.`,rightNative:`Just following up on my email from Tuesday—please let me know your thoughts when you get a chance.`,explanationKo:`세 표현 모두 "다시 연락하다"로 번역되지만 쓰임이 분명히 다릅니다. ① follow up on은 보낸 메일·요청의 후속 결과를 물을 때, ② circle back은 내가 먼저 알아본 뒤 다시 돌아와 답할 때(또는 추후 재논의), ③ touch base는 안부 겸 진행 상황을 가볍게 맞출 때 씁니다.`,registerSpectrum:{casual:`Hey, just checking in on that file from Tuesday!`,standard:`Just following up on my earlier email—let me know if you've had a chance to review it.`,formal:`I am writing to follow up on my previous message regarding the Q4 contract and would appreciate an update at your earliest convenience.`}},{title:`원리 03 · 이메일 전치사 함정 완전 정복: reach out to / CC on / sign off on`,coreFormula:`reach out to [사람] / CC [사람] on [메일/스레드] / sign off on [문서/안건]`,wrongKonglish:`I reached you to ask about the contract and CCed Jason in this email.`,rightNative:`I'm reaching out to you regarding the contract, and I've CC'd Jason on this thread.`,explanationKo:`reach는 타동사라 바로 사람이 오지만("reach you by phone"), 구동사 reach out은 반드시 전치사 to가 필요합니다. 또한 참조에 넣을 때는 in이 아니라 on("CC Jason on this email"), 최종 승인할 때도 반드시 on("sign off on the draft")이 짝을 이룹니다.`,registerSpectrum:{casual:`Reaching out about the contract—I CC'd Jason on this too.`,standard:`I'm reaching out regarding the contract, and I've CC'd Jason on this email.`,formal:`I am reaching out to request your sign-off on the revised agreement; I have copied Jason on this thread for visibility.`}}],sprintDrills:[{id:`d14-s01`,drillType:`chunk-build`,promptKo:`검토하실 수 있도록 수정된 제안서를 첨부해 드렸습니다.`,promptEnHint:`I've attached + for your review 청크를 조립하세요.`,targetEn:`I've attached the revised proposal for your review.`,chunks:[`I've attached`,`the revised proposal`,`for your review.`],explanationKo:`현재완료 "I've attached"와 목적 표현 "for your review"는 영문 이메일 최빈출 조합입니다.`},{id:`d14-s02`,drillType:`konglish-fix`,promptKo:`"제이슨 님을 이 이메일 스레드 참조(CC)에 넣었습니다."`,promptEnHint:`CC 뒤에 쓰이는 정확한 전치사를 확인하세요.`,targetEn:`I've CC'd Jason on this thread.`,wrongKonglishOption:`I've CC'd Jason in this thread.`,explanationKo:`이메일 참조(CC)에는 전치사 in이 아니라 on(on this email / on this thread)을 씁니다.`},{id:`d14-s03`,drillType:`chunk-build`,promptKo:`팀과 확인해 본 뒤 금요일까지 다시 회신드리겠습니다.`,promptEnHint:`check with the team + circle back by Friday를 연결하세요.`,targetEn:`I'll check with the team and circle back by Friday.`,chunks:[`I'll check with`,`the team`,`and circle back`,`by Friday.`],explanationKo:`확인 후 재회신 약속에는 circle back by [시점]을 씁니다.`},{id:`d14-s04`,drillType:`active-blank`,promptKo:`지난주에 보낸 인보이스 건을 후속 확인차 연락드립니다.`,promptEnHint:`~에 대해 후속 확인하다: follow __ on (2글자)`,targetEn:`I'm writing to follow up on the invoice.`,blankData:{before:`I'm writing to follow`,answer:`up`,after:`on the invoice.`,firstLetterHint:`u_ (2글자)`},explanationKo:`follow up on + [이전 안건/메일] 구조입니다.`},{id:`d14-s05`,drillType:`active-blank`,promptKo:`편하신 가장 빠른 시간에 검토해 주시면 감사하겠습니다.`,promptEnHint:`at your earliest ___________ (11글자)`,targetEn:`Please review it at your earliest convenience.`,blankData:{before:`Please review it at your earliest`,answer:`convenience`,after:`.`,firstLetterHint:`c__________ (11글자)`},explanationKo:`ASAP 대신 정중하게 빠른 회신을 요청할 때 at your earliest convenience를 씁니다.`},{id:`d14-s06`,drillType:`konglish-fix`,promptKo:`"재무팀에도 계속 진행 상황을 공유하기 위해 참조에 넣었습니다."`,promptEnHint:`"계속 상황을 공유하다"의 원어민 관용구를 고르세요.`,targetEn:`I added finance to keep them in the loop.`,wrongKonglishOption:`I added finance to share them in the circle.`,explanationKo:`소통 고리에 계속 포함시켜 진행 상황을 공유하다는 keep ~ in the loop입니다.`},{id:`d14-s07`,drillType:`chunk-build`,promptKo:`어제 나눈 대화에 따라 최종 보고서를 첨부해 드립니다.`,promptEnHint:`Per our conversation + Please find ~ attached 패턴을 조립하세요.`,targetEn:`Per our conversation, please find the final report attached.`,chunks:[`Per our conversation,`,`please find`,`the final report`,`attached.`],explanationKo:`격식 있는 비즈니스 이메일의 교과서적인 첫 문장 공식입니다.`},{id:`d14-s08`,drillType:`active-blank`,promptKo:`4분기 예산안 건으로 가볍게 진행 상황 여쭤보려 연락드렸어요.`,promptEnHint:`가볍게 연락해 맞추다: touch ____ (4글자)`,targetEn:`I wanted to touch base on the Q4 budget.`,blankData:{before:`I wanted to touch`,answer:`base`,after:`on the Q4 budget.`,firstLetterHint:`b___ (4글자)`},explanationKo:`touch base (with 사람 / on 안건)은 가벼운 중간 점검 연락에 최적입니다.`},{id:`d14-s09`,drillType:`konglish-fix`,promptKo:`"금요일에 제가 부재중이라는 점 미리 귀띔드리려고요."`,promptEnHint:`사전 공지(heads-up) + 부재중(out of office) 조합을 고르세요.`,targetEn:`Just a quick heads-up that I'll be out of office on Friday.`,wrongKonglishOption:`Just a quick alarm that I'll be empty in office on Friday.`,explanationKo:`미리 알려주는 귀띔은 heads-up, 휴가·외근 부재중은 out of office입니다.`},{id:`d14-s10`,drillType:`chunk-build`,promptKo:`궁금한 점이 있으시면 언제든 편하게 연락 주세요.`,promptEnHint:`Please feel free to + reach out 패턴을 조립하세요.`,targetEn:`Please feel free to reach out with any questions.`,chunks:[`Please feel free to`,`reach out`,`with any`,`questions.`],explanationKo:`이메일 끝인사로 가장 따뜻하고 매너 있는 마무리 문장입니다.`}],worksheetExam:[{id:`d14-e01`,number:1,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`첨부 안내 Please find ~ attached`,questionKo:`빈칸에 알맞은 과거분사(1단어)를 넣어 "수정된 예산안을 첨부해 드립니다"를 완성하세요.`,stimulusEn:`Please find the revised budget __________.`,answer:`attached`,explanationKo:`Please find [목적어] attached는 격식 있는 영문 이메일의 정석 첨부 문구입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "첨부된 바와 같이 일정을 확인해 주세요" 빈칸(2단어)을 채우세요.`,stimulusEn:`Please confirm the timeline __________ __________.`,answer:`as attached`,explanationKo:`첨부된 바와 같이는 as attached라고 씁니다.`}},{id:`d14-e02`,number:2,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`추후 회신 circle back`,questionKo:`빈칸에 알맞은 구동사(2단어)를 넣어 "내일 오후까지 다시 회신드리겠습니다"를 완성하세요.`,stimulusEn:`Let me double-check with engineering and __________ __________ to you tomorrow.`,answer:`circle back`,acceptableAlt:[`get back`],explanationKo:`내부 확인 후 다시 회신하겠다는 뜻으로 circle back(또는 get back)을 씁니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "지난주 회의 건으로 가볍게 연락드렸습니다" 빈칸 관용구(2단어)를 채우세요.`,stimulusEn:`Just wanted to __________ __________ regarding last week’s meeting.`,answer:`touch base`,explanationKo:`가벼운 진행 점검 연락은 touch base입니다.`}},{id:`d14-e03`,number:3,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`사전 공지 heads-up`,questionKo:`빈칸에 하이픈(-) 포함 명사(1단어)를 넣어 "일정 변경에 대해 미리 귀띔드리고 싶었어요"를 완성하세요.`,stimulusEn:`I wanted to give you a quick __________ about the schedule change.`,answer:`heads-up`,explanationKo:`사전 공지·귀띔을 뜻하는 명사는 하이픈을 써서 heads-up이라고 합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "금요일에 휴가로 부재중입니다" 빈칸(3단어)을 채우세요.`,stimulusEn:`I will be __________ __________ __________ this Friday.`,answer:`out of office`,explanationKo:`부재중 상태는 out of office(약어 OOO)라고 표현합니다.`}},{id:`d14-e04`,number:4,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`진행 공유 in the loop`,questionKo:`빈칸에 관용구(3단어)를 넣어 "팀장님께 계속 진행 상황을 공유드리려 참조에 넣었습니다"를 완성하세요.`,stimulusEn:`I CC'd our director to keep him __________ __________ __________.`,answer:`in the loop`,explanationKo:`keep [사람] in the loop은 협업 정보 공유를 유지한다는 오피스 필수 관용구입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "마감이 내일이라는 점을 정중히 다시 안내드립니다" 빈칸(2단어: g_____ r_______)을 채우세요.`,stimulusEn:`Just a __________ __________ that the draft is due tomorrow.`,answer:`gentle reminder`,explanationKo:`부드러운 재안내는 a gentle reminder입니다.`}},{id:`d14-e05`,number:5,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`최종 승인 sign off on`,questionKo:`빈칸에 3단어 구동사를 넣어 "클라이언트가 카피를 최종 승인하면 바로 게시하겠습니다"를 완성하세요.`,stimulusEn:`Once the client __________ __________ __________ the copy, we will publish it.`,answer:`signs off on`,explanationKo:`3인칭 단수 주어 the client에 맞춰 signs off on을 써야 어법까지 완벽합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "화요일에 보낸 견적서 건을 후속 확인차 연락드립니다" 빈칸(3단어)을 채우세요.`,stimulusEn:`I'm writing to __________ __________ __________ the quote I sent Tuesday.`,answer:`follow up on`,explanationKo:`후속 확인은 follow up on + 명사입니다.`}},{id:`d14-e06`,number:6,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`ASAP 대체 격식 표현`,questionKo:`외부 클라이언트에게 부담을 주지 않으면서도 빠른 회신을 요청할 때 가장 적절한 문장은?`,stimulusEn:`비즈니스 격식 톤에 가장 잘 맞는 표현을 고르세요.`,options:[`Please answer me very fast ASAP.`,`Please review and respond at your earliest convenience.`,`I demand your reply immediately today.`,`Reply me quickly when you finish reading.`],answer:`Please review and respond at your earliest convenience.`,explanationKo:`at your earliest convenience는 외부 파트너·상사에게 빠른 회신을 요청하는 가장 세련된 표현입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "앞서 나눈 대화에 따라"를 뜻하는 이메일 오프닝 3단어(P__ o__ c___________)를 쓰세요.`,stimulusEn:`__________ __________ __________, I have updated the deck.`,answer:`Per our conversation`,explanationKo:`Per our conversation은 직전 논의를 깔끔하게 이어주는 표현입니다.`}},{id:`d14-e07`,number:7,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`첨부 파일 문법 오류 판별`,questionKo:`다음 중 영문 이메일에서 첨부 파일을 안내하는 문장으로 어법상 가장 자연스러운 것은?`,stimulusEn:`동사 attach와 형용사 attached의 쓰임을 확인하세요.`,options:[`Please check the attach in this mail.`,`I've attached the Q4 roadmap for your review.`,`I am attaching to you the file inside.`,`Please find attaching the Q4 roadmap.`],answer:`I've attached the Q4 roadmap for your review.`,explanationKo:`attach는 명사가 아니며, 이미 파일을 첨부한 상태이므로 현재완료 "I've attached ~"가 가장 자연스럽습니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "첨부 파일"을 뜻하는 명사(1단어)를 빈칸에 쓰세요.`,stimulusEn:`Let me know if you have trouble opening the __________.`,answer:`attachment`,explanationKo:`첨부 파일 자체를 가리키는 명사는 attachment입니다.`}},{id:`d14-e08`,number:8,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`reach out & CC 전치사 호응`,questionKo:`다음 빈칸 (A), (B)에 들어갈 전치사가 바르게 짝지어진 것은?`,stimulusEn:`Please feel free to reach out (A) me directly—I've also CC'd Maya (B) this thread.`,options:[`(A) to — (B) on`,`(A) at — (B) in`,`(A) for — (B) to`,`(A) with — (B) at`],answer:`(A) to — (B) on`,explanationKo:`reach out to [사람], CC [사람] on [메일/스레드]가 정확한 전치사 호응입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "정오까지 업데이트 내용으로 회신드릴게요" 빈칸 구동사(3단어)를 채우세요.`,stimulusEn:`I'll __________ __________ __________ you with an update by noon.`,answer:`get back to`,explanationKo:`get back to [사람]은 확인 후 답장하겠다는 필수 표현입니다.`}},{id:`d14-e09`,number:9,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`circle back vs follow up 구분`,questionKo:`고객이 물어본 기술 스펙을 개발팀에 확인한 뒤 "오후에 다시 회신드리겠습니다"라고 답할 때 가장 알맞은 표현은?`,stimulusEn:`내가 확인 후 다시 돌아와 답하는 상황입니다.`,options:[`I'll check with engineering and circle back this afternoon.`,`I'll sign off on engineering this afternoon.`,`I'll be out of office to engineering this afternoon.`,`I'll CC engineering as a gentle reminder.`],answer:`I'll check with engineering and circle back this afternoon.`,explanationKo:`정보를 확인한 뒤 다시 회신하겠다는 뉘앙스는 circle back이 정확히 전달합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 이메일 전송 버튼을 누르다: hit ____ (1단어)`,stimulusEn:`Always double-check the attachment before you hit __________.`,answer:`send`,explanationKo:`이메일을 발송할 때 hit send라는 표현을 자주 씁니다.`}},{id:`d14-e10`,number:10,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`회신 재촉 톤 조절`,questionKo:`3일 전 보낸 이메일에 답장이 없을 때, 상대방 기분을 상하지 않게 보내는 팔로업 첫 문장으로 가장 적절한 것은?`,stimulusEn:`공손하고 전문적인 팔로업 톤을 선택하세요.`,options:[`Why are you ignoring my email from three days ago?`,`Just following up on my email from Monday—any updates on your end?`,`You forgot to reply me, so do it now.`,`I am angry because there is no response yet.`],answer:`Just following up on my email from Monday—any updates on your end?`,explanationKo:`"Just following up on ~"으로 부드럽게 시작하고 "any updates on your end?"로 공을 넘기는 것이 표준입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "궁금한 점 있으시면 언제든 편하게 연락 주세요" 빈칸(3단어)을 채우세요.`,stimulusEn:`Please __________ __________ __________ reach out if you have any questions.`,answer:`feel free to`,explanationKo:`Please feel free to + 동사원형은 부담 없이 행동하라는 정중한 권유 표현입니다.`}},{id:`d14-e11`,number:11,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`첨부 안내 격식문 배열`,questionKo:`주어진 청크를 올바른 순서로 배열하여 격식 있는 첨부 안내 문장을 완성하세요.`,stimulusEn:`[ attached / the updated report / Per our conversation, / please find ]`,answer:`Per our conversation, please find the updated report attached.`,explanationKo:`Per our conversation, + please find [명사] attached. 어순입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "검토하실 수 있도록 계약서를 첨부해 드렸습니다." (I’ve attached / the contract / for your review.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`I've attached the contract for your review.`,explanationKo:`현재완료 I've attached + 목적어 + for your review 구조입니다.`}},{id:`d14-e12`,number:12,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`팔로업 + 회신 요청 배열`,questionKo:`주어진 청크를 배열하여 정중한 후속 확인 문장을 작성하세요.`,stimulusEn:`[ on / Just / from Tuesday. / my email / following up ]`,answer:`Just following up on my email from Tuesday.`,explanationKo:`Just following up on + [이전 메일/안건]은 매일 쓰는 팔로업 오프닝입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "금요일까지 다시 회신드리겠습니다." (I’ll circle back / with you / by Friday.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`I'll circle back with you by Friday.`,explanationKo:`circle back with(또는 to) [사람] by [기한] 패턴입니다.`}},{id:`d14-e13`,number:13,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`CC 및 소통 공유 영작`,questionKo:`우리말 뜻에 맞게 주어진 단어를 활용해 자연스러운 이메일 문장을 완성하세요.`,stimulusEn:`우리말: 한나 님께 계속 진행 상황을 공유드리려고 이 스레드 참조에 넣었습니다. (I’ve CC’d / Hannah / on this thread / to keep her / in the loop.)`,answer:`I've CC'd Hannah on this thread to keep her in the loop.`,explanationKo:`CC [사람] on [스레드] + to keep [사람] in the loop 완벽한 조합입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "다음 주 월요일에 부재중이라는 점 미리 귀띔드려요." (Just a quick heads-up / that I’ll be / out of office / next Monday.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`Just a quick heads-up that I'll be out of office next Monday.`,explanationKo:`Just a quick heads-up that ~ 절로 사전 공지를 매끄럽게 전달합니다.`}},{id:`d14-e14`,number:14,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`콩글리시 교정 서술형`,questionKo:`다음 콩글리시 문장을 오늘 배운 표현(at your earliest convenience, sign off on)으로 고쳐 쓰세요.`,stimulusEn:`오류 문장: Please confirm the draft ASAP.`,answer:`Please sign off on the draft at your earliest convenience.`,acceptableAlt:[`Could you please sign off on the draft at your earliest convenience?`,`Please review and sign off on the draft at your earliest convenience.`],explanationKo:`ASAP를 at your earliest convenience로, confirm을 최종 승인 의미의 sign off on으로 다듬었습니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 오류 교정: I reached you about the budget. → reach out to를 써서 9단어로 고치세요.`,stimulusEn:`힌트: I am reaching ~.`,answer:`I am reaching out to you about the budget.`,explanationKo:`reach out 뒤에는 반드시 전치사 to가 필요합니다. (축약형 I'm reaching out to you about the budget.도 동일)`}},{id:`d14-e15`,number:15,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`실전 통문장 영작`,questionKo:`다음 우리말을 영어로 자연스럽게 작성하세요.`,stimulusEn:`우리말: 프로젝트 일정 건으로 가볍게 진행 상황 여쭤보려고 연락드렸습니다. (힌트: I wanted to / touch base / on the project timeline.)`,answer:`I wanted to touch base on the project timeline.`,acceptableAlt:[`Just wanted to touch base on the project timeline.`],explanationKo:`I wanted to touch base on [안건]은 부담 없이 대화를 여는 원어민 비즈니스 치트키입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "궁금한 점이 있으시면 언제든 편하게 연락 주세요." (Please feel free to / reach out / if you have any questions.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`Please feel free to reach out if you have any questions.`,explanationKo:`영문 이메일 엔딩의 정석 문장입니다.`}}],tutorScenario:{openingQuestionEn:`Hi! Thanks for sending over the Q4 draft earlier. I haven't had a chance to review it yet—when do you need my sign-off, and should I copy anyone else on my reply?`,openingQuestionKo:`안녕하세요! 아까 4분기 초안 보내주셔서 감사해요. 아직 검토를 못 했는데 언제까지 최종 승인이 필요하신가요? 회신할 때 참조에 넣어야 할 분이 있나요? (목요일까지 승인 요청 + 재무팀 CC 요청 + 금요일 부재중 귀띔을 영어로 답해보세요!)`,followUpQuestionEn:`Got it! I'll look it over tomorrow morning and circle back before Thursday noon, keeping finance in the loop. Have a great long weekend!`,followUpQuestionKo:`알겠습니다! 내일 오전에 검토하고 재무팀 참조 포함해서 목요일 정오 전까지 회신드릴게요. 좋은 연휴 보내세요!`,recommendedChunks:[`at your earliest convenience`,`sign off on it by Thursday`,`CC finance on the thread`,`keep them in the loop`,`a quick heads-up that I will be out of office`],modelAnswerEn:`No rush at all, though it would be great if you could sign off on it by Thursday afternoon at your earliest convenience. Please CC our finance lead on the thread to keep him in the loop—and just a quick heads-up, I'll be out of office on Friday.`}},{dayNumber:15,weekNumber:3,cefrLevel:`b2`,dayBadge:`DAY 15 · 업무 진행 보고 & 마감 지연 대응`,categoryLabel:`Week 3 오피스 실무 · 프로젝트 현황 보고 & 우선순위 조율`,title:`일정은 순조롭지만 병목이 하나 생겼습니다`,subtitle:`진행률 보고부터 우선순위(Priority) 재정렬, 예상치 못한 병목(Bottleneck)과 마감 지연(Push back)을 신뢰를 잃지 않고 보고하는 실무 공식`,heroImage:`assets/scene_late_office.jpg`,secondaryImage:`assets/office_sitcom_scene.jpg`,estimatedSprintMin:8,estimatedLectureMin:45,keyExpression:`We're mostly on track, but we hit a bottleneck and may need to push back the deadline.`,keySentenceByTier:{a1:`The project is going well, but we need two more days.`,a2:`Most of our work is on track, but we have one problem and need to delay the deadline.`,b1:`We're mostly on track for Friday, though we ran into a small issue and may need to push the deadline back.`,b2:`We're largely on track, but we hit a bottleneck in QA and may need to push back the deadline by 48 hours.`,c1:`While our core deliverables remain ahead of schedule, an API blocker has created a bottleneck, so I'd recommend putting secondary tasks on the back burner and pushing launch back to Tuesday.`,c2:`Despite keeping most milestones on track, a third-party authentication bottleneck has constrained our bandwidth; unless we escalate this blocker today and deprioritize non-essential scope, we'll need to push back the release window.`},youtubeVideo:e[15],readingPassage:{titleEn:`Q3 Mobile Checkout Release — Weekly Risk & Priority Update`,titleKo:`[주간 프로젝트 보고서] 3분기 모바일 결제 출시 — 리스크 및 우선순위 조정안`,genreBadge:`주간 상태 보고서 · Lv.4`,estimatedMin:6,paragraphsEn:[`Team, here is a quick status update on the Q3 mobile checkout release. Overall, our front-end deliverables are ahead of schedule, and design QA is completely on track to wrap up by EOD Thursday. However, I want to flag an emerging bottleneck on the payment gateway integration before it puts next Monday's launch behind schedule.`,`Specifically, we hit a technical blocker waiting on sandbox credentials from our external vendor. Because our back-end engineers currently have limited bandwidth, trying to tackle both the checkout fix and the loyalty-points redesign this week would spread the team too thin. I have already escalated the credential request to the vendor's account lead for faster turnaround.`,`To protect our main launch date, I propose we prioritize checkout stability and put the loyalty-points redesign on the back burner until Sprint 14. If the vendor cannot clear the blocker by tomorrow noon, we may need to push back the external deadline by two business days. I will take ownership of the vendor follow-up and post updated action items in Slack by 5 PM.`],paragraphsSlash:[`Team, / here is a quick status update / on the Q3 mobile checkout release. / Overall, / our front-end deliverables are ahead of schedule, / and design QA is completely on track / to wrap up by EOD Thursday. / However, / I want to flag an emerging bottleneck / on the payment gateway integration / before it puts next Monday's launch behind schedule.`,`Specifically, / we hit a technical blocker / waiting on sandbox credentials / from our external vendor. / Because our back-end engineers / currently have limited bandwidth, / trying to tackle both the checkout fix / and the loyalty-points redesign this week / would spread the team too thin. / I have already escalated the credential request / to the vendor's account lead / for faster turnaround.`,`To protect our main launch date, / I propose we prioritize checkout stability / and put the loyalty-points redesign on the back burner / until Sprint 14. / If the vendor cannot clear the blocker / by tomorrow noon, / we may need to push back the external deadline / by two business days. / I will take ownership of the vendor follow-up / and post updated action items in Slack / by 5 PM.`],paragraphsKo:[`팀 여러분, 3분기 모바일 결제 출시에 대한 간략한 진행 현황 보고드립니다. 전반적으로 프론트엔드 산출물은 예정보다 앞서 진행 중이며, 디자인 QA도 목요일 업무 마감 전까지 완료되도록 순조롭게 진행되고 있습니다. 다만 다음 주 월요일 출시가 일정보다 뒤처지기 전에 결제 게이트웨이 연동 과정에서 생긴 병목 현상을 미리 공유하고자 합니다.`,`구체적으로 외부 벤더사로부터 테스트(샌드박스) 인증 키를 기다리는 과정에서 기술적 장애 요인에 부딪혔습니다. 현재 백엔드 엔지니어들의 업무 여력이 빠듯하기 때문에 이번 주에 결제 오류 수정과 포인트 개편 작업을 동시에 처리하려 하면 팀 전체에 무리가 갑니다. 신속한 처리를 위해 이미 벤더사 담당 책임자에게 인증 키 발급 요청을 상위 보고(에스컬레이션)해 두었습니다.`,`핵심 출시일을 지키기 위해 결제 안정화를 최우선 순위로 두고, 포인트 개편 작업은 스프린트 14까지 후순위로 미뤄둘 것을 제안합니다. 만약 내일 정오까지 벤더사가 장애 요인을 해소하지 못하면 외부 공개 마감일을 영업일 기준 이틀 정도 미뤄야 할 수도 있습니다. 벤더사 후속 대응은 제가 주도적으로 책임지고 맡겠으며, 오후 5시까지 업데이트된 실행 과제를 슬랙에 공유하겠습니다.`],keyExpressions:[`on track / ahead of schedule`,`flag a bottleneck`,`limited bandwidth`,`put ~ on the back burner`,`push back the deadline`,`take ownership of`],comprehensionQuiz:[{id:`d15-rq01`,questionKo:`보고서에서 언급된 현재 프로젝트의 병목 구간(bottleneck) 원인은 무엇인가요?`,options:[`프론트엔드 개발 일정이 일주일 이상 지연되었기 때문에`,`외부 벤더사의 결제 연동 테스트(샌드박스) 인증 키 발급이 지연되고 있어서`,`디자인 QA 담당자가 갑자기 휴가를 떠났기 때문에`,`경영진이 3분기 모바일 출시 자체를 취소했기 때문에`],answer:`외부 벤더사의 결제 연동 테스트(샌드박스) 인증 키 발급이 지연되고 있어서`,explanationKo:`둘째 문단 "we hit a technical blocker waiting on sandbox credentials from our external vendor"가 정확한 원인입니다.`},{id:`d15-rq02`,questionKo:`핵심 출시일을 지키기 위해 작성자가 제안한 우선순위 조정 방안은?`,options:[`결제 안정화를 최우선으로 두고 포인트 개편(loyalty-points redesign)은 후순위로 미룬다`,`프론트엔드와 백엔드 인력을 모두 포인트 개편에 투입한다`,`외부 벤더사와 계약을 즉시 해지한다`,`QA 검증 단계를 생략하고 월요일에 강행 출시한다`],answer:`결제 안정화를 최우선으로 두고 포인트 개편(loyalty-points redesign)은 후순위로 미룬다`,explanationKo:`셋째 문단 "prioritize checkout stability and put the loyalty-points redesign on the back burner until Sprint 14"가 근거입니다.`},{id:`d15-rq03`,questionKo:`본문에서 "문제를 상위 책임자에게 올려 신속 대응을 요청하다"라는 뜻으로 쓰인 비즈니스 동사는?`,options:[`prioritize`,`escalate`,`deliver`,`integrate`],answer:`escalate`,explanationKo:`둘째 문단 "I have already escalated the credential request to the vendor's account lead"에서 escalate가 상위 보고·긴급 격상의 뜻으로 쓰였습니다.`}]},vocabList:[{id:`d15-v01`,word:`on track`,phonetic:`/ɑːn træk/`,pos:`전치사구`,cefr:`b2`,meaningKo:`계획대로 순조롭게 진행 중인`,meaningEn:`progressing as planned toward a goal or deadline`,nuanceTipKo:`기차가 선로(track) 위를 정상 주행하는 이미지입니다. "We're on track to launch on Monday"처럼 to 부정사와 함께 마감 목표를 밝힙니다.`,exampleEn:`We're right on track to hit our Q3 revenue target.`,exampleKo:`3분기 매출 목표를 달성할 수 있도록 아주 순조롭게 진행 중입니다.`},{id:`d15-v02`,word:`behind schedule`,phonetic:`/bɪˈhaɪnd ˈskedʒuːl/`,pos:`전치사구`,cefr:`b1`,meaningKo:`예정 일정보다 뒤처진, 지연된`,meaningEn:`later than planned according to the project timeline`,nuanceTipKo:`fall behind schedule(일정이 밀리기 시작하다), be two days behind schedule(이틀 지연되다) 패턴으로 바로 쓰세요.`,exampleEn:`The QA phase is currently two days behind schedule due to server bugs.`,exampleKo:`서버 버그 때문에 현재 QA 단계가 예정보다 이틀 지연되었습니다.`},{id:`d15-v03`,word:`ahead of schedule`,phonetic:`/əˈhed əv ˈskedʒuːl/`,pos:`전치사구`,cefr:`b2`,meaningKo:`예정 일정보다 앞선, 조기 달성 중인`,meaningEn:`earlier or faster than originally planned`,nuanceTipKo:`behind schedule의 정반대! 좋은 소식을 먼저 보고할 때 "Design is ahead of schedule"로 시작하면 팀 사기가 올라갑니다.`,exampleEn:`Thanks to the new workflow, our design team finished ahead of schedule.`,exampleKo:`새 워크플로우 덕분에 디자인 팀이 예정 일정보다 일찍 마쳤습니다.`},{id:`d15-v04`,word:`bottleneck`,phonetic:`/ˈbɑːtlnek/`,pos:`명사`,cefr:`b2`,meaningKo:`(업무 흐름이 막히는) 병목 구간, 정체 요인`,meaningEn:`a point of congestion that slows down an entire workflow`,nuanceTipKo:`병목처럼 좁아져 전체 프로세스가 막히는 지점을 뜻합니다. "hit a bottleneck / clear a bottleneck" 연어로 익히세요.`,exampleEn:`Legal review has become the biggest bottleneck in our onboarding process.`,exampleKo:`법무 검토가 우리 온보딩 프로세스에서 가장 큰 병목 구간이 되었습니다.`},{id:`d15-v05`,word:`push back the deadline`,phonetic:`/pʊʃ bæk ðə ˈdedlaɪn/`,pos:`동사 구문`,cefr:`b2`,meaningKo:`마감 기한을 뒤로 미루다`,meaningEn:`postpone a due date to a later time`,nuanceTipKo:`delay보다 훨씬 실무적인 구어/이메일 표현이며, 지연 기간 앞에는 전치사 by(by two days), 새 날짜 앞에는 to(to Friday)를 씁니다.`,exampleEn:`We may need to push back the deadline by two business days.`,exampleKo:`마감일을 영업일 기준 이틀 정도 뒤로 미뤄야 할 수도 있습니다.`},{id:`d15-v06`,word:`bandwidth`,phonetic:`/ˈbændwɪdθ/`,pos:`명사`,cefr:`b2`,meaningKo:`(업무를 소화할) 시간·에너지·리소스 여력`,meaningEn:`the time, energy, or capacity available to take on work`,nuanceTipKo:`원래 통신 대역폭이지만 글로벌 오피스에서는 100% "업무 여력" 뜻으로 쓰입니다. "I don't have the bandwidth right now"는 최고의 프로 거절 표현!`,exampleEn:`Our front-end team doesn't have the bandwidth to take on another sprint task.`,exampleKo:`프론트엔드 팀은 추가 스프린트 업무를 맡을 여력이 지금 없습니다.`},{id:`d15-v07`,word:`prioritize`,phonetic:`/praɪˈɔːrətaɪz/`,pos:`동사`,cefr:`b2`,meaningKo:`우선순위를 정하다, 최우선으로 처리하다`,meaningEn:`treat a task as more important than others and handle it first`,nuanceTipKo:`명사 priority(우선순위)와 함께 "What should we prioritize this week?"로 상사와 방향을 정렬할 때 필수 동사입니다.`,exampleEn:`Let’s prioritize the checkout bug fix before working on minor UI tweaks.`,exampleKo:`사소한 UI 수정 전에 결제 버그 해결을 최우선으로 처리합시다.`},{id:`d15-v08`,word:`put ~ on the back burner`,phonetic:`/pʊt ɑːn ðə bæk ˈbɜːrnər/`,pos:`관용구`,cefr:`c1`,meaningKo:`~을 당장 급하지 않아 후순위로 미뤄두다`,meaningEn:`temporarily set aside a lower-priority project to focus on urgent work`,nuanceTipKo:`가스레인지 앞쪽 화구에는 급한 요리를, 뒤쪽 화구(back burner)에는 천천히 끓일 냄비를 올려두는 그림에서 나온 원어민 최애 비즈니스 관용구입니다.`,exampleEn:`We'll have to put the blog redesign on the back burner until next quarter.`,exampleKo:`블로그 개편은 다음 분기까지 잠시 후순위로 미뤄둬야 할 것 같습니다.`},{id:`d15-v09`,word:`deliverable`,phonetic:`/dɪˈlɪvərəbl/`,pos:`명사`,cefr:`b2`,meaningKo:`(프로젝트의 구체적인) 산출물, 납품 결과물`,meaningEn:`a tangible output or result expected to be completed for a project`,nuanceTipKo:`막연한 work 대신 "key deliverables(핵심 산출물)"라고 말하면 보고서와 스탠드업의 격이 확 올라갑니다.`,exampleEn:`All Phase 1 deliverables have been uploaded to the shared drive.`,exampleKo:`1단계 핵심 산출물은 모두 공유 드라이브에 업로드되었습니다.`},{id:`d15-v10`,word:`blocker`,phonetic:`/ˈblɑːkər/`,pos:`명사`,cefr:`b2`,meaningKo:`(업무 진행을 가로막는) 장애 요인, 블로커`,meaningEn:`an obstacle that prevents a task or team from moving forward`,nuanceTipKo:`데일리 스크럼/스탠드업에서 매일 듣는 질문이 바로 "Any blockers today?(오늘 진행 막히는 이슈 있나요?)"입니다.`,exampleEn:`Do you have any blockers that I can help clear this afternoon?`,exampleKo:`오늘 오후에 제가 해결을 도와드릴 만한 진행 장애 요인이 있나요?`},{id:`d15-v11`,word:`flag (an issue)`,phonetic:`/flæɡ/`,pos:`동사`,cefr:`b2`,meaningKo:`(리스크·문제를) 미리 깃발을 꽂듯 표시해 알리다`,meaningEn:`draw early attention to a potential risk or problem`,nuanceTipKo:`문제가 터진 뒤 변명하지 않고 조기에 공유할 때 "I wanted to flag this early"라고 말하면 신뢰받는 팀원이 됩니다.`,exampleEn:`I wanted to flag a potential delay in shipping before Friday’s review.`,exampleKo:`금요일 리뷰 전에 배송 지연 가능성을 미리 공유드리고 싶었습니다.`},{id:`d15-v12`,word:`take ownership of`,phonetic:`/teɪk ˈoʊnərʃɪp əv/`,pos:`동사 구문`,cefr:`b2`,meaningKo:`~에 대해 주도적으로 책임을 맡다`,meaningEn:`accept full responsibility for driving a task or resolving an issue`,nuanceTipKo:`"I'll be responsible for ~"보다 훨씬 능동적이고 리더십 있는 미국 실무 표현입니다.`,exampleEn:`I'll take ownership of the client onboarding doc and update it by Friday.`,exampleKo:`클라이언트 온보딩 문서는 제가 주도적으로 맡아 금요일까지 업데이트하겠습니다.`},{id:`d15-v13`,word:`action item`,phonetic:`/ˈækʃn ˈaɪtəm/`,pos:`명사구`,cefr:`b2`,meaningKo:`(회의 후 실행할) 구체적 실행 과제, 할 일`,meaningEn:`a specific, assigned follow-up task resulting from a meeting`,nuanceTipKo:`회의 끝에 "Let's recap our action items and owners(실행 과제와 담당자를 정리하죠)"로 닫으면 완벽합니다.`,exampleEn:`I just posted our key action items and due dates in the project channel.`,exampleKo:`핵심 실행 과제와 마감일을 프로젝트 채널에 방금 올려두었습니다.`},{id:`d15-v14`,word:`by EOD (end of day)`,phonetic:`/baɪ ˌiː oʊ ˈdiː/`,pos:`전치사구`,cefr:`b2`,meaningKo:`오늘 업무 마감 전까지`,meaningEn:`before the end of the standard working day`,nuanceTipKo:`until EOD가 아니라 완료 시점 전치사 by를 씁니다! 글로벌 협업에서는 혼선을 막기 위해 "by EOD Thursday KST"처럼 시간대를 붙이기도 합니다.`,exampleEn:`I'll share the revised forecast with you by EOD today.`,exampleKo:`수정된 예측치는 오늘 퇴근 전까지 공유드리겠습니다.`},{id:`d15-v15`,word:`escalate`,phonetic:`/ˈeskəleɪt/`,pos:`동사`,cefr:`b2`,meaningKo:`(해결이 지연된 이슈를) 상위 단계·책임자에게 올려 신속 대응을 요청하다`,meaningEn:`raise an urgent issue to a higher level of management for faster action`,nuanceTipKo:`실무자 선에서 풀리지 않는 블로커를 매니저·임원·벤더 리드에게 격상 보고할 때 쓰는 정확한 비즈니스 동사입니다.`,exampleEn:`If we don't hear back by noon, we'll escalate the ticket to their VP.`,exampleKo:`정오까지 회신이 없으면 이 티켓을 상대방 부사장급으로 상위 보고하겠습니다.`}],dialogue:[{id:`d15-t01`,speaker:`Rachel`,roleLabel:`프로덕트 디렉터`,voicePitch:1.04,sceneImage:`assets/scene_late_office.jpg`,cameraMotion:`zoom-in`,english:`Hey Taehyun, thanks for staying on a few extra minutes. Quick check—are we still on track for Monday's checkout launch?`,slashBroken:`Hey Taehyun, / thanks for staying on a few extra minutes. / Quick check— / are we still on track / for Monday's checkout launch?`,korean:`태현 님, 몇 분 더 남아줘서 고마워요. 짧게 확인할게요—월요일 결제 출시 일정 아직 순조롭게 진행 중인가요?`,keyHighlight:`still on track for Monday's checkout launch`,noteKo:`진행률 점검의 정석 질문은 "Are we still on track for [마감/출시]?"입니다.`},{id:`d15-t02`,speaker:`Taehyun`,roleLabel:`테크 리드`,voicePitch:.9,sceneImage:`assets/scene_late_office.jpg`,cameraMotion:`pan-right`,english:`Front-end deliverables are actually ahead of schedule, Rachel. However, I wanted to flag a bottleneck on the payment API.`,slashBroken:`Front-end deliverables are actually ahead of schedule, / Rachel. / However, / I wanted to flag a bottleneck / on the payment API.`,korean:`프론트엔드 산출물은 사실 예정보다 앞서 있어요, 레이첼. 하지만 결제 API 쪽에 생긴 병목 이슈를 미리 공유드리고 싶었습니다.`,keyHighlight:`flag a bottleneck on the payment API`,noteKo:`긍정적 현황(ahead of schedule)을 먼저 짚고 리스크(flag a bottleneck)를 조기 보고하는 교과서적 구조입니다.`},{id:`d15-t03`,speaker:`Rachel`,roleLabel:`프로덕트 디렉터`,voicePitch:1.04,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`pan-left`,english:`Appreciate you flagging it early. What's the exact blocker, and how far behind schedule could it put us?`,slashBroken:`Appreciate you flagging it early. / What's the exact blocker, / and how far behind schedule / could it put us?`,korean:`미리 알려줘서 고마워요. 정확한 장애 요인이 무엇이고, 일정이 얼마나 밀릴 수 있나요?`,keyHighlight:`What's the exact blocker`,noteKo:`원인과 영향 범위(how far behind schedule)를 짚는 실무 리더의 핵심 질문 패턴입니다.`},{id:`d15-t04`,speaker:`Taehyun`,roleLabel:`테크 리드`,voicePitch:.9,sceneImage:`assets/scene_late_office.jpg`,cameraMotion:`zoom-in`,english:`We're still waiting on test keys from the vendor. I've already escalated it to their lead, but we may need to push back the deadline by two days.`,slashBroken:`We're still waiting on test keys from the vendor. / I've already escalated it to their lead, / but we may need to push back the deadline / by two days.`,korean:`벤더사에서 테스트 키를 아직 기다리고 있어요. 상대 리드에게 이미 상위 보고해 두었지만, 마감일을 이틀 정도 미뤄야 할 수도 있습니다.`,keyHighlight:`push back the deadline by two days`,noteKo:`문제만 던지지 않고 이미 취한 조치(escalated it)와 구체적 지연 폭(by two days)을 함께 보고합니다.`},{id:`d15-t05`,speaker:`Rachel`,roleLabel:`프로덕트 디렉터`,voicePitch:1.04,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`pan-right`,english:`Got it. Do we have enough bandwidth to keep the loyalty redesign going, or should we reprioritize?`,slashBroken:`Got it. / Do we have enough bandwidth / to keep the loyalty redesign going, / or should we reprioritize?`,korean:`알겠어요. 포인트 개편 작업도 병행할 여력이 되나요, 아니면 우선순위를 재조정해야 할까요?`,keyHighlight:`have enough bandwidth`,noteKo:`리소스 여유를 물을 때 bandwidth와 reprioritize(우선순위 재정렬)가 세트로 자주 쓰입니다.`},{id:`d15-t06`,speaker:`Taehyun`,roleLabel:`테크 리드`,voicePitch:.9,sceneImage:`assets/scene_late_office.jpg`,cameraMotion:`pan-left`,english:`Honestly, our bandwidth is pretty tight. I'd recommend we prioritize checkout QA and put the loyalty redesign on the back burner until next sprint.`,slashBroken:`Honestly, / our bandwidth is pretty tight. / I'd recommend we prioritize checkout QA / and put the loyalty redesign on the back burner / until next sprint.`,korean:`솔직히 여력이 꽤 빠듯합니다. 결제 QA를 최우선으로 두고 포인트 개편은 다음 스프린트까지 후순위로 미뤄두길 권장합니다.`,keyHighlight:`put the loyalty redesign on the back burner`,noteKo:`무조건 다 하겠다고 하지 않고, 우선순위 조정안(prioritize A and put B on the back burner)을 제안하는 것이 시니어의 소통법입니다.`},{id:`d15-t07`,speaker:`Rachel`,roleLabel:`프로덕트 디렉터`,voicePitch:1.04,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`zoom-in`,english:`Makes total sense—let's do that. I'll take ownership of updating marketing, and could you share the revised action items by EOD tomorrow?`,slashBroken:`Makes total sense— / let's do that. / I'll take ownership of updating marketing, / and could you share the revised action items / by EOD tomorrow?`,korean:`완전히 일리 있네요, 그렇게 하죠. 마케팅팀 공유는 제가 책임지고 맡을 테니 내일 퇴근 전까지 수정된 실행 과제를 올려주실래요?`,keyHighlight:`share the revised action items by EOD tomorrow`,noteKo:`책임 분담(take ownership of)과 기한 명시(by EOD tomorrow)로 보고를 완벽히 마무리합니다.`}],grammarSections:[{title:`원리 01 · 리스크 보고의 황금 3단 구조: [현황] + [병목 원인] + [조치 & 대안]`,coreFormula:`[on track / ahead] + However, we hit a bottleneck / blocker + [escalated / push back by ~]`,wrongKonglish:`Sorry, we cannot finish until Monday because vendor is late. It is delayed.`,rightNative:`Most deliverables are on track, though we hit a vendor bottleneck. I've escalated it, and we may need to push back the deadline by two days.`,explanationKo:`일정 지연을 보고할 때 변명처럼 들리지 않으려면 반드시 3단 구조를 지키세요. ① 순조로운 부분(on track)을 먼저 짚어 안심시키고, ② 객관적 장애물(hit a bottleneck / blocker)을 제시한 뒤, ③ 이미 취한 액션(escalated)과 현실적 대안(push back by two days)으로 마무리하면 리더의 신뢰를 얻습니다.`,registerSpectrum:{casual:`Quick heads-up—we hit a snag with the vendor, so we might push launch back a couple days.`,standard:`We're mostly on track, but we hit a bottleneck in QA and may need to push back the deadline by two days.`,formal:`While core deliverables remain on track, an external dependency has created a bottleneck; we have escalated the issue and recommend adjusting the target date by 48 hours.`}},{title:`원리 02 · 업무 여력과 우선순위 영어: bandwidth & put ~ on the back burner`,coreFormula:`have limited bandwidth (여력이 빠듯하다) → prioritize A and put B on the back burner`,wrongKonglish:`We don't have enough energy space, so let's throw away task B to the back.`,rightNative:`We have limited bandwidth this week, so let's prioritize task A and put task B on the back burner.`,explanationKo:`직장에서 "시간·인력 여력이 부족하다"고 할 때 "no time"만 반복하면 아마추어처럼 들립니다. bandwidth(업무 소화 여력)라는 명사를 쓰고, 덜 급한 업무를 포기(cancel)가 아니라 잠시 보류할 때는 가스레인지 뒤쪽 화구에 둔다는 뜻의 put ~ on the back burner를 쓰세요.`,registerSpectrum:{casual:`I don't really have the bandwidth this week, so let's park that idea for now.`,standard:`Our team has limited bandwidth right now, so let's put the redesign on the back burner.`,formal:`Given current resource constraints, we recommend prioritizing core stability and deferring secondary enhancements to Q4.`}},{title:`원리 03 · 마감 전치사 함정 완전 차단: by EOD (완료 기한) vs. until Friday (상태 지속)`,coreFormula:`완료 동작(submit / share / wrap up) + by [시점] ↔ 지속 상태(wait / stay / work) + until [시점]`,wrongKonglish:`I will finish and send the deliverables until EOD Friday.`,rightNative:`I'll finalize and share the deliverables by EOD Friday.`,explanationKo:`한국어 "~까지"를 무조건 until로 옮기는 것이 비즈니스 영어 최다 오류입니다! 제출·완료·회신처럼 "그 시점 이전에 딱 끝나는 일"은 반드시 by(by EOD, by Friday noon)를 쓰고, 휴가·대기·작업처럼 "그 시점까지 계속 이어지는 상태"에만 until(until next sprint, until 5 PM)을 씁니다.`,registerSpectrum:{casual:`I'll get the action items over to you by EOD!`,standard:`I'll share the revised action items by EOD tomorrow.`,formal:`All finalized deliverables will be submitted by end of business on Friday.`}}],sprintDrills:[{id:`d15-s01`,drillType:`chunk-build`,promptKo:`3분기 출시 일정은 대체로 계획대로 순조롭게 진행 중입니다.`,promptEnHint:`mostly on track + for the Q3 launch 조합을 만드세요.`,targetEn:`We're mostly on track for the Q3 launch.`,chunks:[`We're`,`mostly on track`,`for the`,`Q3 launch.`],explanationKo:`계획대로 진행 중이라는 핵심 보고 표현은 be on track for [목표/일정]입니다.`},{id:`d15-s02`,drillType:`konglish-fix`,promptKo:`"수정된 산출물을 금요일 퇴근 전까지 공유드리겠습니다."`,promptEnHint:`완료 마감 시점 앞에 쓰는 전치사(by vs until)를 확인하세요.`,targetEn:`I'll share the revised deliverables by EOD Friday.`,wrongKonglishOption:`I'll share the revised deliverables until EOD Friday.`,explanationKo:`공유·제출처럼 완료 시점을 지정할 때는 until이 아니라 전치사 by를 씁니다.`},{id:`d15-s03`,drillType:`active-blank`,promptKo:`결제 API 연동 과정에서 병목 구간에 부딪혔습니다.`,promptEnHint:`업무 흐름이 막히는 병목 구간: b_________ (10글자)`,targetEn:`We hit a bottleneck on the payment API.`,blankData:{before:`We hit a`,answer:`bottleneck`,after:`on the payment API.`,firstLetterHint:`b_________ (10글자)`},explanationKo:`병목 현상을 만나다는 hit a bottleneck 연어로 통째로 익혀두세요.`},{id:`d15-s04`,drillType:`chunk-build`,promptKo:`마감일을 이틀 정도 뒤로 미뤄야 할 수도 있습니다.`,promptEnHint:`push back the deadline + by two days 청크를 조립하세요.`,targetEn:`We may need to push back the deadline by two days.`,chunks:[`We may need to`,`push back`,`the deadline`,`by two days.`],explanationKo:`지연 기간을 밝힐 때는 전치사 by(by two days)를 붙입니다.`},{id:`d15-s05`,drillType:`active-blank`,promptKo:`이번 주에는 추가 업무를 맡을 여력이 부족합니다.`,promptEnHint:`업무 소화 여력(대역폭): b________ (9글자)`,targetEn:`Our team has limited bandwidth this week.`,blankData:{before:`Our team has limited`,answer:`bandwidth`,after:`this week.`,firstLetterHint:`b________ (9글자)`},explanationKo:`시간·인력 여력을 나타내는 대표 오피스 명사는 bandwidth입니다.`},{id:`d15-s06`,drillType:`konglish-fix`,promptKo:`"블로그 개편은 다음 분기까지 후순위로 미뤄두죠."`,promptEnHint:`덜 급한 일을 후순위로 보류하는 원어민 관용구를 고르세요.`,targetEn:`Let's put the blog redesign on the back burner until next quarter.`,wrongKonglishOption:`Let's put the blog redesign on the rear chair until next quarter.`,explanationKo:`후순위로 잠시 미뤄두다는 put ~ on the back burner입니다.`},{id:`d15-s07`,drillType:`chunk-build`,promptKo:`그 이슈를 이미 벤더사 리드에게 상위 보고해 두었습니다.`,promptEnHint:`I've already escalated + to their lead 어순으로 조립하세요.`,targetEn:`I've already escalated the issue to their lead.`,chunks:[`I've already`,`escalated`,`the issue`,`to their lead.`],explanationKo:`escalate [문제] to [상위 담당자]는 장애 대응 보고의 필수 패턴입니다.`},{id:`d15-s08`,drillType:`active-blank`,promptKo:`벤더사 후속 대응은 제가 주도적으로 책임지고 맡겠습니다.`,promptEnHint:`주도적으로 책임을 맡다: take _________ of (9글자)`,targetEn:`I'll take ownership of the vendor follow-up.`,blankData:{before:`I'll take`,answer:`ownership`,after:`of the vendor follow-up.`,firstLetterHint:`o________ (9글자)`},explanationKo:`take ownership of ~ 는 프로페셔널한 책임감을 드러내는 핵심 표현입니다.`},{id:`d15-s09`,drillType:`konglish-fix`,promptKo:`"현재 QA 단계가 예정 일정보다 이틀 뒤처져 있습니다."`,promptEnHint:`"예정보다 뒤처진"의 정확한 전치사구를 고르세요.`,targetEn:`The QA phase is two days behind schedule.`,wrongKonglishOption:`The QA phase is two days back of schedule.`,explanationKo:`일정보다 뒤처짐은 behind schedule, 앞섬은 ahead of schedule입니다.`},{id:`d15-s10`,drillType:`chunk-build`,promptKo:`금요일 리뷰 전에 잠재적 지연을 미리 알리고 싶었습니다.`,promptEnHint:`wanted to flag + a potential delay 청크를 조립하세요.`,targetEn:`I wanted to flag a potential delay before Friday.`,chunks:[`I wanted to`,`flag`,`a potential delay`,`before Friday.`],explanationKo:`리스크를 조기에 알릴 때 동사 flag를 쓰면 매우 세련된 보고가 됩니다.`}],worksheetExam:[{id:`d15-e01`,number:1,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`정상 진행 on track`,questionKo:`빈칸에 전치사구(2단어)를 넣어 "다음 주 출시 일정에 맞춰 순조롭게 진행 중입니다"를 완성하세요.`,stimulusEn:`We're right __________ __________ for next week's release.`,answer:`on track`,explanationKo:`계획대로 정상 궤도 위에서 진행 중일 때 on track을 씁니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "디자인 팀은 예정보다 앞서 진행 중입니다" 빈칸(3단어)을 채우세요.`,stimulusEn:`The design team is __________ __________ __________.`,answer:`ahead of schedule`,explanationKo:`일정보다 앞선 상태는 ahead of schedule입니다.`}},{id:`d15-e02`,number:2,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`병목 구간 bottleneck`,questionKo:`빈칸에 명사(1단어)를 넣어 "법무 검토 단계에서 병목 현상에 부딪혔습니다"를 완성하세요.`,stimulusEn:`We hit a major __________ during legal review.`,answer:`bottleneck`,acceptableAlt:[`blocker`],explanationKo:`업무 흐름이 좁아져 정체되는 지점을 bottleneck(또는 진행 장애 요인 blocker)이라고 합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "진행을 막는 장애 요인이 있으신가요?" 빈칸 명사 복수형(1단어: b_______)을 쓰세요.`,stimulusEn:`Are there any __________ slowing down the sprint today?`,answer:`blockers`,explanationKo:`스탠드업 미팅에서 장애 요인은 blocker(복수 blockers)라고 부릅니다.`}},{id:`d15-e03`,number:3,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`업무 여력 bandwidth`,questionKo:`빈칸에 명사(1단어)를 넣어 "현재 두 프로젝트를 동시에 맡을 여력이 부족합니다"를 완성하세요.`,stimulusEn:`Our team doesn't have enough __________ to handle both projects at once.`,answer:`bandwidth`,explanationKo:`업무를 소화할 시간·인력 여력을 bandwidth라고 합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "이 문제를 이미 벤더사 책임자에게 상위 보고했습니다" 빈칸 동사 과거분사(1단어)를 쓰세요.`,stimulusEn:`I've already __________ this issue to the vendor's director.`,answer:`escalated`,explanationKo:`상위 단계로 격상 보고하다는 escalate(과거분사 escalated)입니다.`}},{id:`d15-e04`,number:4,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`후순위 보류 back burner`,questionKo:`빈칸에 명사구(2단어)를 넣어 "보조 기능은 다음 분기까지 후순위로 미뤄둡시다"를 완성하세요.`,stimulusEn:`Let's put the secondary feature on the __________ __________ until next quarter.`,answer:`back burner`,explanationKo:`put ~ on the back burner는 덜 급한 업무를 보류해 두는 필수 비즈니스 관용구입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "결제 안정화를 최우선 순위로 두어야 합니다" 빈칸 동사(1단어)를 쓰세요.`,stimulusEn:`We need to __________ checkout stability this week.`,answer:`prioritize`,explanationKo:`우선시하다는 동사 prioritize입니다.`}},{id:`d15-e05`,number:5,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`책임 주도 take ownership of`,questionKo:`빈칸에 3단어를 넣어 "마케팅팀 커뮤니케이션은 제가 주도적으로 책임지고 맡겠습니다"를 완성하세요.`,stimulusEn:`I'll __________ __________ __________ updating the marketing team.`,answer:`take ownership of`,explanationKo:`take ownership of + 명사/동명사 구조로 능동적 책임을 표현합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "수정된 실행 과제들을 슬랙에 공유했습니다" 빈칸 명사구(2단어 복수)를 쓰세요.`,stimulusEn:`I just posted our revised __________ __________ in Slack.`,answer:`action items`,explanationKo:`구체적 후속 실행 과제는 action items입니다.`}},{id:`d15-e06`,number:6,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`by vs until 마감 전치사`,questionKo:`다음 중 "금요일 퇴근 전까지 산출물을 제출하겠습니다"를 어법상 바르게 표현한 문장은?`,stimulusEn:`완료 시점(by)과 상태 지속(until)의 차이에 주의하세요.`,options:[`I'll submit the deliverables until EOD Friday.`,`I'll submit the deliverables by EOD Friday.`,`I'll submit the deliverables during EOD Friday.`,`I'll submit the deliverables since EOD Friday.`],answer:`I'll submit the deliverables by EOD Friday.`,explanationKo:`submit처럼 완료 동작의 마감 기한 앞에는 반드시 전치사 by를 써야 합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "다음 스프린트까지 그 작업을 보류해 두자" — 상태 지속 전치사(1단어)를 쓰세요.`,stimulusEn:`Let's put that redesign on the back burner __________ next sprint.`,answer:`until`,explanationKo:`보류 상태가 다음 스프린트까지 계속 이어지므로 until이 정확합니다.`}},{id:`d15-e07`,number:7,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`마감 연기 push back 전치사`,questionKo:`마감일을 "영업일 기준 이틀만큼" 뒤로 미뤄야 한다고 보고할 때 빈칸에 가장 알맞은 것은?`,stimulusEn:`We may need to push back the deadline ______ two business days.`,options:[`by`,`at`,`until`,`with`],answer:`by`,explanationKo:`지연·차이의 폭(two business days, 30 minutes) 앞에는 전치사 by를 사용합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 마감일을 "다음 주 수요일로(새 날짜)" 미룰 때 쓰는 전치사(1단어)는?`,stimulusEn:`We had to push back the deadline __________ next Wednesday.`,answer:`to`,explanationKo:`새로운 목표 시점을 가리킬 때는 전치사 to를 씁니다.`}},{id:`d15-e08`,number:8,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`조기 리스크 공유 flag 동사`,questionKo:`문제가 커지기 전에 상사에게 "잠재적인 배송 지연 리스크를 미리 공유드리고 싶었습니다"라고 말할 때 가장 세련된 문장은?`,stimulusEn:`비즈니스 실무에서 조기 경보·공유를 뜻하는 동사를 고르세요.`,options:[`I wanted to flag a potential shipping delay early.`,`I wanted to wave a red cloth about shipping late.`,`I wanted to complain a shipping accident early.`,`I wanted to alarm you a bad shipping problem.`],answer:`I wanted to flag a potential shipping delay early.`,explanationKo:`동사 flag는 이슈나 리스크를 객관적이고 선제적으로 표시해 알릴 때 쓰는 핵심 실무 어휘입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "프로젝트의 구체적 산출물"을 뜻하는 명사 복수형(1단어: d___________)을 쓰세요.`,stimulusEn:`All Phase 1 __________ are ready for client review.`,answer:`deliverables`,explanationKo:`프로젝트 결과물·산출물은 deliverables입니다.`}},{id:`d15-e09`,number:9,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`진행 상태 표현 대조`,questionKo:`원래 금요일 마감 예정이던 QA 작업이 아직 수요일에 다 끝나지 못해 "이틀 지연된 상태"일 때 알맞은 문장은?`,stimulusEn:`일정 지연(behind) vs 조기 달성(ahead)을 구분하세요.`,options:[`QA is currently two days ahead of schedule.`,`QA is currently two days behind schedule.`,`QA is currently two days on track.`,`QA is currently two days out of office.`],answer:`QA is currently two days behind schedule.`,explanationKo:`예정 일정보다 늦어진 상태는 behind schedule입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 일정이 뒤처지기 시작할 때 쓰는 동명사 구문(3단어: f______ b_____ s_______)을 쓰세요.`,stimulusEn:`Without vendor keys, we risk __________ __________ __________.`,answer:`falling behind schedule`,explanationKo:`동사 risk 뒤에는 동명사가 오므로 falling behind schedule이 정확합니다.`}},{id:`d15-e10`,number:10,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`우선순위 조율 시니어 톤`,questionKo:`업무가 과도하게 몰렸을 때 매니저에게 우선순위 재조정을 요청하는 가장 프로페셔널한 표현은?`,stimulusEn:`변명 없이 객관적 여력과 대안을 제시하는 문장을 고르세요.`,options:[`This is too much work and I refuse to do both.`,`Given our tight bandwidth, which deliverable should we prioritize first?`,`My brain is full so please cancel everything today.`,`You gave me too many tasks without asking me.`],answer:`Given our tight bandwidth, which deliverable should we prioritize first?`,explanationKo:`여력의 한계(tight bandwidth)를 객관적으로 밝히고 의사결정권자에게 우선순위(prioritize)를 묻는 것이 최고의 소통법입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "이 이슈를 벤더사 리드에게 이미 상위 보고해 두었습니다" 빈칸 동사(1단어)를 쓰세요.`,stimulusEn:`We decided to __________ the outage to senior management.`,answer:`escalate`,explanationKo:`to부정사 뒤이므로 동사원형 escalate를 씁니다.`}},{id:`d15-e11`,number:11,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`현황 + 병목 보고 배열`,questionKo:`주어진 청크를 올바른 순서로 배열하여 진행 현황 및 병목 보고 문장을 완성하세요.`,stimulusEn:`[ hit a bottleneck / in QA. / mostly on track, / We're / but we ]`,answer:`We're mostly on track, but we hit a bottleneck in QA.`,explanationKo:`긍정적 현황(mostly on track) 뒤에 접속사 but으로 병목(hit a bottleneck)을 매끄럽게 연결합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "월요일 출시 일정은 아직 순조롭게 진행 중인가요?" (Are we still / on track / for Monday’s launch?)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`Are we still on track for Monday's launch?`,explanationKo:`Are we still on track for [일정]? 의문문 패턴입니다.`}},{id:`d15-e12`,number:12,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`우선순위 조정 배열`,questionKo:`주어진 청크를 배열하여 우선순위 조정 제안 문장을 완성하세요.`,stimulusEn:`[ the redesign / on the back burner / Let's / until next sprint. / put ]`,answer:`Let's put the redesign on the back burner until next sprint.`,explanationKo:`Let's put [업무] on the back burner until [시점] 어순입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "이번 주에는 결제 안정화를 최우선으로 둡시다." (Let’s prioritize / checkout stability / this week.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`Let's prioritize checkout stability this week.`,explanationKo:`Let's prioritize [핵심 과제] + [기간] 패턴입니다.`}},{id:`d15-e13`,number:13,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`마감 연기 보고 영작`,questionKo:`우리말 뜻에 맞게 주어진 단어를 활용해 자연스러운 지연 대응 문장을 완성하세요.`,stimulusEn:`우리말: 마감일을 이틀 뒤로 미뤄야 할 수도 있습니다. (We may need to / push back / the deadline / by two days.)`,answer:`We may need to push back the deadline by two days.`,acceptableAlt:[`We may need to push the deadline back by two days.`],explanationKo:`may need to로 완충을 깔고 push back the deadline by two days로 명확히 전달합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "오늘 퇴근 전까지 수정된 실행 과제를 공유드릴게요." (I’ll share / the revised action items / by EOD today.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`I'll share the revised action items by EOD today.`,explanationKo:`share + 목적어 + by EOD today 어순입니다.`}},{id:`d15-e14`,number:14,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`콩글리시 교정 서술형`,questionKo:`다음 콩글리시 문장을 오늘 배운 표현(bandwidth, by EOD)으로 바르게 고쳐 쓰세요.`,stimulusEn:`오류 문장: I don't have enough energy space to finish both until EOD.`,answer:`I don't have enough bandwidth to finish both by EOD.`,acceptableAlt:[`I don't have the bandwidth to finish both by EOD.`],explanationKo:`energy space → bandwidth, 완료 기한 until EOD → by EOD로 교정합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 오류 교정: I will be responsible for the vendor follow-up. → take ownership of를 써서 고치세요.`,stimulusEn:`힌트: I'll ~ the vendor follow-up.`,answer:`I'll take ownership of the vendor follow-up.`,explanationKo:`take ownership of는 훨씬 주도적이고 전문적인 표현입니다.`}},{id:`d15-e15`,number:15,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`실전 통문장 영작`,questionKo:`다음 우리말을 영어로 자연스럽게 작성하세요.`,stimulusEn:`우리말: 벤더사 리드에게 이미 이 장애 요인을 상위 보고해 두었습니다. (힌트: I’ve already / escalated / this blocker / to the vendor lead.)`,answer:`I've already escalated this blocker to the vendor lead.`,acceptableAlt:[`I have already escalated this blocker to the vendor lead.`],explanationKo:`escalate [장애 요인] to [상위 담당자]는 글로벌 IT·오피스 실무 핵심 문장입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "디자인 리뷰 전에 잠재적 지연을 미리 알리고 싶었습니다." (I wanted to flag / a potential delay / before the design review.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`I wanted to flag a potential delay before the design review.`,explanationKo:`flag a potential delay로 선제적 리스크 관리 태도를 보여줍니다.`}}],tutorScenario:{openingQuestionEn:`Hey, quick standup check! Are we still on track to ship the new onboarding flow by Friday, or are you running into any blockers?`,openingQuestionKo:`안녕하세요, 짧은 스탠드업 체크예요! 금요일까지 새 온보딩 플로우 배포 일정 순조롭게 가고 있나요, 아니면 막히는 장애 요인이 있나요? (대체로 순조롭지만 QA 병목이 생겨 마감 연기나 우선순위 조정이 필요하다고 프로답게 보고해 보세요!)`,followUpQuestionEn:`Thanks for flagging that early! Between the core onboarding flow and the extra analytics dashboard, which one should we put on the back burner so your team has enough bandwidth?`,followUpQuestionKo:`미리 공유해 줘서 고마워요! 핵심 온보딩 플로우와 추가 애널리틱스 대시보드 중 어떤 것을 후순위로 미뤄야 팀 여력이 확보될까요?`,recommendedChunks:[`mostly on track`,`hit a bottleneck in QA`,`escalated the blocker`,`push back the deadline by ~`,`put ~ on the back burner`,`take ownership of`],modelAnswerEn:`Most front-end deliverables are on track, though I wanted to flag a bottleneck in QA integration. I've already escalated the blocker, and if we put the analytics dashboard on the back burner this week, we'll have the bandwidth to ship core onboarding—or at worst push back the deadline by one day.`}},{dayNumber:16,weekNumber:3,cefrLevel:`b2`,dayBadge:`DAY 16 · 회의 끼어들기·동의·완곡한 반론`,categoryLabel:`Week 3 오피스 실무 · 영어 회의 발언권 & 설득력 있는 반론`,title:`말씀하신 내용에 한 가지 덧붙여도 될까요?`,subtitle:`영어 회의에서 눈치만 보다 침묵하지 않고, 타이밍 좋게 끼어들어 의견을 얹고(Build on) 기분 상하지 않게 완곡한 반론을 펼치는 고급 토론 기술`,heroImage:`assets/scene_boardroom_pitch.jpg`,secondaryImage:`assets/office_sitcom_scene.jpg`,estimatedSprintMin:8,estimatedLectureMin:45,keyExpression:`I see where you're coming from, and to build on that, I'd suggest another angle.`,keySentenceByTier:{a1:`Excuse me, I have an idea too. I agree with you, but I think we need another plan.`,a2:`May I say something here? I understand your point, but I worry about the cost.`,b1:`Sorry to jump in, but I see where you're coming from—could we also look at this from another angle?`,b2:`To build on David's point, I see where you're coming from on speed, though I have a few reservations about cutting our margin.`,c1:`If I may chime in here, Hannah's analysis is spot on; to play devil's advocate for a moment, we should anticipate pushback from enterprise clients before reaching a consensus.`,c2:`While I fully echo your point regarding rapid adoption, I'd like to piggyback on that with a slight caveat—unless we model churn sensitivity first, we risk triggering avoidable pushback during renewals.`},youtubeVideo:e[16],readingPassage:{titleEn:`Inside a High-Trust Product Debate: How to Disagree Without Friction`,titleKo:`[임원실 회의록 분석] 신뢰를 지키며 반론하는 고품격 영어 토론의 기술`,genreBadge:`임원실 회의록 · Lv.4`,estimatedMin:6,paragraphsEn:[`Many non-native professionals stay silent during fast-paced English meetings, not because they lack insights, but because they wait for a long pause that never arrives. In Western boardrooms, politely jumping in with a brief bridge phrase—such as "May I chime in here?" or "To build on what Sarah just mentioned"—signals active engagement rather than rudeness.`,`Even trickier is voicing disagreement when senior colleagues favor a different direction. Direct statements like "I disagree" or "That won't work" often trigger defensive pushback. Instead, skilled communicators validate the other person's logic first by saying "You make a valid point" or "I see where you're coming from," and then introduce an alternative from another angle using softeners like "that said" or "I have a few reservations about..."`,`When a debate gets heated over a minor detail, strong facilitators know how to play devil's advocate constructively without making it personal. If one sub-topic threatens to derail the whole meeting, proposing to table that item for a separate session helps the group stay focused and reach a consensus on the core decision before time runs out.`],paragraphsSlash:[`Many non-native professionals stay silent / during fast-paced English meetings, / not because they lack insights, / but because they wait for a long pause / that never arrives. / In Western boardrooms, / politely jumping in with a brief bridge phrase— / such as "May I chime in here?" / or "To build on what Sarah just mentioned"— / signals active engagement / rather than rudeness.`,`Even trickier is voicing disagreement / when senior colleagues favor a different direction. / Direct statements like "I disagree" or "That won't work" / often trigger defensive pushback. / Instead, / skilled communicators validate the other person's logic first / by saying "You make a valid point" / or "I see where you're coming from," / and then introduce an alternative from another angle / using softeners like "that said" / or "I have a few reservations about..."`,`When a debate gets heated over a minor detail, / strong facilitators know how to play devil's advocate constructively / without making it personal. / If one sub-topic threatens to derail the whole meeting, / proposing to table that item / for a separate session / helps the group stay focused / and reach a consensus on the core decision / before time runs out.`],paragraphsKo:[`많은 비원어민 직장인들이 빠르게 흘러가는 영어 회의에서 침묵하는 이유는 통찰이 부족해서가 아니라, 결코 오지 않는 긴 정적을 기다리기 때문입니다. 서구권 회의실에서는 "여기서 한마디 보태도 될까요?" 또는 "사라가 방금 말한 내용에 덧붙이자면" 같은 짧은 연결 문구로 정중하게 끼어드는 것이 무례함이 아니라 적극적인 참여의 신호로 받아들여집니다.`,`더 까다로운 상황은 시니어 동료가 다른 방향을 선호할 때 반론을 제기하는 것입니다. "동의하지 않습니다"나 "그건 안 될 겁니다" 같은 직설적 표현은 종종 방어적인 반발을 불러옵니다. 대신 노련한 커뮤니케이터는 먼저 "타당한 지적입니다" 또는 "어떤 관점에서 말씀하시는지 충분히 이해합니다"로 상대의 논리를 인정한 뒤, "그렇긴 하지만"이나 "약간의 우려가 있습니다" 같은 완충어로 다른 시각의 대안을 제시합니다.`,`사소한 세부 사항으로 토론이 과열될 때, 뛰어난 진행자는 감정 싸움으로 번지지 않게 건설적으로 일부러 반대 입장을 취해(devil's advocate) 논리를 검증할 줄 압니다. 만약 한 가지 부수 안건이 회의 전체의 흐름을 깰 조짐이 보이면, 그 안건은 별도 세션을 위해 잠시 보류(table)하자고 제안함으로써 시간이 끝나기 전에 핵심 결정에 대한 합의에 도달하도록 이끕니다.`],keyExpressions:[`jump in / chime in`,`build on what ~ mentioned`,`see where you're coming from`,`have reservations about`,`play devil's advocate`,`reach a consensus`],comprehensionQuiz:[{id:`d16-rq01`,questionKo:`본문에 따르면 비원어민 직장인이 영어 회의에서 침묵하게 되는 주된 이유는 무엇인가요?`,options:[`회의 주제에 대한 전문 지식과 통찰이 부족해서`,`결코 오지 않는 긴 정적(pause)을 기다리다가 발언 타이밍을 놓쳐서`,`회의실에 마이크와 오디오 장비가 부족해서`,`서구권 회의 문화에서는 신입의 발언을 금지하기 때문에`],answer:`결코 오지 않는 긴 정적(pause)을 기다리다가 발언 타이밍을 놓쳐서`,explanationKo:`첫째 문단 "not because they lack insights, but because they wait for a long pause that never arrives"가 근거입니다.`},{id:`d16-rq02`,questionKo:`노련한 커뮤니케이터가 방어적 반발(pushback)을 피하며 반론하는 올바른 순서는?`,options:[`"I disagree"로 단호하게 자른 뒤 데이터 표를 띄운다`,`회의가 끝날 때까지 침묵하다가 이메일로만 반대 의견을 보낸다`,`상대의 논리를 먼저 인정(validate)한 뒤 완충어를 써서 다른 각도의 대안을 제시한다`,`다른 부서 매니저에게 대신 반대해 달라고 부탁한다`],answer:`상대의 논리를 먼저 인정(validate)한 뒤 완충어를 써서 다른 각도의 대안을 제시한다`,explanationKo:`둘째 문단 "validate the other person's logic first ... and then introduce an alternative from another angle using softeners"를 확인하세요.`},{id:`d16-rq03`,questionKo:`미국 비즈니스 영어에서 부수 안건을 "나중에 논의하기로 잠시 보류하다"라는 뜻으로 본문에 쓰인 동사는?`,options:[`echo`,`table`,`chime`,`derail`],answer:`table`,explanationKo:`셋째 문단 "proposing to table that item for a separate session"에서 미국식 비즈니스 동사 table(보류하다)이 쓰였습니다.`}]},vocabList:[{id:`d16-v01`,word:`jump in`,phonetic:`/dʒʌmp ɪn/`,pos:`구동사`,cefr:`b1`,meaningKo:`(회의·대화 흐름에) 정중히 끼어들어 발언하다`,meaningEn:`enter an ongoing conversation or discussion to add a remark`,nuanceTipKo:`interrupt(방해하다) 대신 "Sorry to jump in" 또는 "May I jump in real quick?"을 쓰면 무례함 없이 자연스럽게 발언권을 얻습니다.`,exampleEn:`Sorry to jump in here, but I have a quick question about the Q4 numbers.`,exampleKo:`잠깐 끼어들어 죄송하지만, 4분기 수치에 대해 짧은 질문이 있습니다.`},{id:`d16-v02`,word:`build on (that)`,phonetic:`/bɪld ɑːn/`,pos:`구동사`,cefr:`b2`,meaningKo:`(앞사람의 의견에) 살을 붙여 발전시키다`,meaningEn:`expand on or strengthen an idea someone else just shared`,nuanceTipKo:`내 의견만 툭 던지는 것보다 "To build on what Hannah just said..."로 연결하면 경청하는 협업형 리더로 보입니다.`,exampleEn:`To build on David's point, we could also offer an annual billing discount.`,exampleKo:`데이비드 님 말씀에 덧붙이자면, 연간 결제 할인도 함께 제공할 수 있을 것 같습니다.`},{id:`d16-v03`,word:`see where you're coming from`,phonetic:`/siː wer jʊr ˈkʌmɪŋ frʌm/`,pos:`관용 구문`,cefr:`b2`,meaningKo:`어떤 입장·맥락에서 그렇게 말씀하시는지 충분히 이해하다`,meaningEn:`understand the reasoning or perspective behind someone’s opinion`,nuanceTipKo:`반론을 꺼내기 직전에 깔아주는 최고의 공감 쿠션! "I totally see where you're coming from, that said..." 구조를 통째로 외우세요.`,exampleEn:`I completely see where you're coming from; however, our support team is already stretched thin.`,exampleKo:`어떤 관점에서 말씀하시는지 충분히 이해합니다. 다만 고객지원팀 여력이 이미 많이 빠듯합니다.`},{id:`d16-v04`,word:`make a valid point`,phonetic:`/meɪk ə ˈvælɪd pɔɪnt/`,pos:`연어(Collocation)`,cefr:`b2`,meaningKo:`타당하고 일리 있는 지적을 하다`,meaningEn:`raise a logical, well-founded argument worth considering`,nuanceTipKo:`상대방 의견에 100% 동의하지 않더라도 논리적 타당성을 인정해 줄 때 "You make a very valid point"가 완벽합니다.`,exampleEn:`Soojin makes a valid point about enterprise renewal rates.`,exampleKo:`수진 님이 기업 고객 갱신율에 대해 아주 타당한 지적을 해 주셨습니다.`},{id:`d16-v05`,word:`spot on`,phonetic:`/spɑːt ɑːn/`,pos:`형용사구`,cefr:`b2`,meaningKo:`정확히 핵심을 찌른, 딱 맞는`,meaningEn:`completely accurate or right on target`,nuanceTipKo:`"You are right"보다 훨씬 생생하고 프로페셔널한 찬사입니다. "That analysis is spot on!"처럼 쓰세요.`,exampleEn:`Hannah's revenue forecast turned out to be spot on.`,exampleKo:`한나 님의 매출 예측이 정확히 들어맞았습니다.`},{id:`d16-v06`,word:`play devil's advocate`,phonetic:`/pleɪ ˈdevlz ˈædvəkət/`,pos:`관용구`,cefr:`c1`,meaningKo:`(논리 검증을 위해) 일부러 반대 입장을 취해 보다`,meaningEn:`intentionally argue the opposite view to test the strength of an idea`,nuanceTipKo:`감정적 반대가 아니라 팀의 결정을 단단하게 만들기 위한 검증임을 밝힐 때 "Just to play devil's advocate for a second..."를 씁니다.`,exampleEn:`Just to play devil's advocate, what happens if customers downgrade after the promo ends?`,exampleKo:`논리 검증 차원에서 일부러 반대 입장을 취해 보자면, 프로모션 종료 후 고객이 하위 요금제로 바꾸면 어떡하죠?`},{id:`d16-v07`,word:`pushback`,phonetic:`/ˈpʊʃbæk/`,pos:`명사`,cefr:`b2`,meaningKo:`(제안·변화에 대한) 반발, 이견, 저항`,meaningEn:`resistance, criticism, or strong disagreement in response to a proposal`,nuanceTipKo:`구동사 push back(미루다)과 달리 붙여 쓴 명사 pushback은 "반발·이견"을 뜻합니다! "expect some pushback" 연어로 익히세요.`,exampleEn:`We should expect some pushback from enterprise clients if we raise prices abruptly.`,exampleKo:`가격을 갑작스럽게 올리면 기업 고객들로부터 어느 정도 반발이 있을 걸로 예상해야 합니다.`},{id:`d16-v08`,word:`have reservations about`,phonetic:`/hæv ˌrezərˈveɪʃnz əˈbaʊt/`,pos:`동사 구문`,cefr:`c1`,meaningKo:`~에 대해 약간의 우려·유보적인 태도를 갖다`,meaningEn:`feel hesitant or have doubts about a plan or proposal`,nuanceTipKo:`식당 예약(reservation)이 아니라 복수형으로 "우려·의구심"을 뜻합니다! "I disagree"를 고급 B2/C1 어조로 바꾸는 치트키입니다.`,exampleEn:`I have a few reservations about offering a 30% discount across all tiers.`,exampleKo:`모든 요금제에 일괄 30% 할인을 적용하는 데 대해서는 몇 가지 우려가 있습니다.`},{id:`d16-v09`,word:`chime in`,phonetic:`/tʃaɪm ɪn/`,pos:`구동사`,cefr:`b2`,meaningKo:`(자연스럽게 대화에) 한마디 거들다, 의견을 보태다`,meaningEn:`contribute a helpful comment during a group discussion`,nuanceTipKo:`종소리가 맑게 어우러지듯(chime) 회의 흐름을 깨지 않고 부드럽게 발언을 보탤 때 jump in과 번갈아 쓰면 표현력이 풍부해집니다.`,exampleEn:`Feel free to chime in anytime if you spot any gaps in the data.`,exampleKo:`데이터에서 빠진 부분이 보이시면 언제든 편하게 한마디 보태 주세요.`},{id:`d16-v10`,word:`piggyback on`,phonetic:`/ˈpɪɡibæk ɑːn/`,pos:`구동사`,cefr:`c1`,meaningKo:`(앞사람 아이디어를) 그대로 이어받아 덧붙이다`,meaningEn:`add your own point directly onto someone else’s idea`,nuanceTipKo:`어부바(piggyback)에서 유래한 미국 오피스 단골 표현! "To piggyback on what David said..."는 build on의 생생한 동의어입니다.`,exampleEn:`Just to piggyback on what Soojin mentioned, customer interviews showed the exact same trend.`,exampleKo:`수진 님 말씀에 덧붙이자면, 고객 인터뷰에서도 똑같은 추세가 나타났습니다.`},{id:`d16-v11`,word:`bring up`,phonetic:`/brɪŋ ʌp/`,pos:`구동사`,cefr:`b1`,meaningKo:`(회의 중 안건·질문을) 꺼내다, 제기하다`,meaningEn:`introduce a subject or question for discussion`,nuanceTipKo:`"Thank you for bringing that up(그 점을 짚어 주셔서 감사합니다)"는 회의에서 상대 발언을 존중하는 1순위 리액션입니다.`,exampleEn:`I'm really glad you brought up the onboarding cost—we almost overlooked it.`,exampleKo:`온보딩 비용 이야기를 꺼내 주셔서 정말 다행이에요, 하마터면 놓칠 뻔했네요.`},{id:`d16-v12`,word:`echo (someone's) point`,phonetic:`/ˈekoʊ pɔɪnt/`,pos:`동사 구문`,cefr:`b2`,meaningKo:`(~의 의견에) 전적으로 동감하며 힘을 싣다`,meaningEn:`express strong agreement by repeating or reinforcing someone else’s view`,nuanceTipKo:`Day 13의 "마이크 울림(echo)"과 달리 회의 토론에서는 "누구의 의견에 메아리처럼 동조하다"라는 고급 동사로 쓰입니다.`,exampleEn:`I'd like to echo Hannah's point about protecting our gross margin.`,exampleKo:`매출 총이익률을 지켜야 한다는 한나 님 의견에 전적으로 동감합니다.`},{id:`d16-v13`,word:`reach a consensus`,phonetic:`/riːtʃ ə kənˈsensəs/`,pos:`연어(Collocation)`,cefr:`b2`,meaningKo:`합의에 도달하다`,meaningEn:`arrive at a general agreement shared by the group`,nuanceTipKo:`토론을 결론으로 수렴시킬 때 "Let's see if we can reach a consensus before 4 PM"처럼 씁니다.`,exampleEn:`After thirty minutes of healthy debate, the team finally reached a consensus.`,exampleKo:`30분간의 건강한 토론 끝에 팀은 마침내 합의에 도달했습니다.`},{id:`d16-v14`,word:`table (a topic)`,phonetic:`/ˈteɪbl/`,pos:`동사`,cefr:`c1`,meaningKo:`(미국 영어) 안건을 잠시 접어 두고 나중으로 보류하다`,meaningEn:`postpone discussion of a topic until a later meeting (US usage)`,nuanceTipKo:`주의! 미국 비즈니스에서는 "안건을 보류하다(put aside)", 영국에서는 "안건을 상정하다"로 정반대 의미가 될 수 있어 문맥(for now / until next week)을 함께 씁니다.`,exampleEn:`Since we're short on time, let's table the logo refresh for now.`,exampleKo:`시간이 부족하니 로고 리뉴얼 건은 일단 보류해 두죠.`},{id:`d16-v15`,word:`from another angle`,phonetic:`/frʌm əˈnʌðər ˈæŋɡl/`,pos:`전치사구`,cefr:`b2`,meaningKo:`다른 관점에서, 또 다른 시각으로`,meaningEn:`from a different perspective or way of viewing an issue`,nuanceTipKo:`반대 의견을 "틀렸다"가 아니라 "또 다른 각도에서 보자(look at this from another angle)"로 프레이밍하면 거부감이 사라집니다.`,exampleEn:`Could we look at the pricing structure from another angle for a moment?`,exampleKo:`가격 정책을 잠시 다른 관점에서 바라볼 수 있을까요?`}],dialogue:[{id:`d16-t01`,speaker:`David`,roleLabel:`세일즈 부사장 (VP)`,voicePitch:.9,sceneImage:`assets/scene_boardroom_pitch.jpg`,cameraMotion:`zoom-in`,english:`To hit our Q4 acquisition goal quickly, I propose we launch a flat 30% discount across all subscription tiers next month.`,slashBroken:`To hit our Q4 acquisition goal quickly, / I propose we launch a flat 30% discount / across all subscription tiers / next month.`,korean:`4분기 신규 고객 확보 목표를 빠르게 달성하기 위해, 다음 달 전 요금제에 일괄 30% 할인을 도입하자고 제안합니다.`,keyHighlight:`propose we launch a flat 30% discount`,noteKo:`propose (that) we + 동사원형(가정법 현재)은 회의에서 안건을 공식 제안할 때 쓰는 고급 구조입니다.`},{id:`d16-t02`,speaker:`Hannah`,roleLabel:`재무 애널리스트`,voicePitch:1.09,sceneImage:`assets/scene_boardroom_pitch.jpg`,cameraMotion:`pan-right`,english:`May I jump in real quick, David? I totally see where you're coming from on growth, but I have a few reservations about cutting our margin that deeply.`,slashBroken:`May I jump in real quick, David? / I totally see where you're coming from on growth, / but I have a few reservations / about cutting our margin that deeply.`,korean:`잠깐 끼어들어도 될까요, 데이비드? 성장 측면에서 어떤 취지로 말씀하시는지 충분히 이해하지만, 마진을 그렇게 크게 낮추는 건 몇 가지 우려가 됩니다.`,keyHighlight:`see where you're coming from`,noteKo:`[발언권 요청] → [공감 쿠션] → [완곡한 우려(have reservations)]의 완벽한 3단 반론 공식입니다.`},{id:`d16-t03`,speaker:`Soojin`,roleLabel:`프로덕트 전략 리드`,voicePitch:1.04,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`pan-left`,english:`I'd like to echo Hannah's point and build on that. Just to play devil's advocate, wouldn't existing annual customers push back if they see a huge public discount?`,slashBroken:`I'd like to echo Hannah's point / and build on that. / Just to play devil's advocate, / wouldn't existing annual customers push back / if they see a huge public discount?`,korean:`한나 님 의견에 동감하며 한 가지 덧붙이고 싶습니다. 검증 차원에서 반대 입장을 취해 보자면, 기존 연간 결제 고객들이 대규모 공개 할인을 보면 반발하지 않을까요?`,keyHighlight:`echo Hannah's point and build on that`,noteKo:`앞사람 의견에 힘을 싣고(echo) 살을 붙이며(build on), play devil's advocate로 리스크를 객관적으로 던집니다.`},{id:`d16-t04`,speaker:`David`,roleLabel:`세일즈 부사장 (VP)`,voicePitch:.9,sceneImage:`assets/scene_boardroom_pitch.jpg`,cameraMotion:`zoom-in`,english:`That's a very valid point, Soojin—I'm glad you brought that up. Your concern about renewal pushback is spot on.`,slashBroken:`That's a very valid point, Soojin— / I'm glad you brought that up. / Your concern about renewal pushback / is spot on.`,korean:`아주 타당한 지적이에요, 수진 님. 그 점을 꺼내 주셔서 다행입니다. 갱신 시 반발에 대한 우려가 정확히 핵심을 찔렀네요.`,keyHighlight:`spot on`,noteKo:`반론을 들었을 때 방어적으로 나오지 않고 "valid point / glad you brought that up / spot on"으로 수용하는 리더의 품격입니다.`},{id:`d16-t05`,speaker:`Soojin`,roleLabel:`프로덕트 전략 리드`,voicePitch:1.04,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`pan-right`,english:`What if we look at this from another angle? Instead of a flat discount, we could offer two free onboarding workshops for annual sign-ups.`,slashBroken:`What if we look at this / from another angle? / Instead of a flat discount, / we could offer two free onboarding workshops / for annual sign-ups.`,korean:`이 문제를 다른 관점에서 보면 어떨까요? 일괄 할인 대신 연간 가입 고객에게 무료 온보딩 워크숍 2회를 제공하는 거죠.`,keyHighlight:`look at this from another angle`,noteKo:`단순 반대에서 멈추지 않고 "What if we look at this from another angle?"로 건설적 대안을 제시합니다.`},{id:`d16-t06`,speaker:`Hannah`,roleLabel:`재무 애널리스트`,voicePitch:1.09,sceneImage:`assets/scene_boardroom_pitch.jpg`,cameraMotion:`pan-left`,english:`To piggyback on that, workshops protect our headline pricing while keeping acquisition cost well within budget.`,slashBroken:`To piggyback on that, / workshops protect our headline pricing / while keeping acquisition cost / well within budget.`,korean:`거기에 한마디 덧붙이자면, 워크숍 제공은 정가 정책을 지키면서도 고객 획득 비용을 예산 범위 안으로 충분히 묶어둘 수 있어요.`,keyHighlight:`To piggyback on that`,noteKo:`To piggyback on that으로 동료의 대안에 재무적 근거를 얹어 설득력을 완성합니다.`},{id:`d16-t07`,speaker:`David`,roleLabel:`세일즈 부사장 (VP)`,voicePitch:.9,sceneImage:`assets/scene_boardroom_pitch.jpg`,cameraMotion:`zoom-in`,english:`I'm sold! Looks like we've reached a consensus on the workshop bundle—let's table the enterprise add-on pricing for Thursday's sync.`,slashBroken:`I'm sold! / Looks like we've reached a consensus / on the workshop bundle— / let's table the enterprise add-on pricing / for Thursday's sync.`,korean:`완전히 설득됐습니다! 워크숍 번들 안으로 합의에 도달한 것 같네요. 엔터프라이즈 추가 옵션 가격은 목요일 회의로 보류해 두죠.`,keyHighlight:`reached a consensus`,noteKo:`"I'm sold!"는 "완전히 납득했어/동의해!"라는 생생한 원어민 표현이며, 부수 안건은 table로 정리합니다.`}],grammarSections:[{title:`원리 01 · 무례하지 않은 반론의 3단 쿠션: [공감] + [전환] + [다른 관점]`,coreFormula:`I see where you're coming from / You make a valid point + (however / that said) + I have some reservations about ~`,wrongKonglish:`I disagree with your opinion. Your discount idea is wrong and dangerous.`,rightNative:`I see where you're coming from; that said, I have a few reservations about offering a flat 30% discount.`,explanationKo:`영어 회의에서 "I disagree"나 "You're wrong"을 바로 던지면 아이디어가 아니라 "상대방 인격"을 공격하는 것처럼 들려 방어벽(pushback)이 생깁니다. 먼저 상대 논리를 인정(see where you're coming from)하고, 부드러운 전환어(that said / however) 뒤에 개인적 우려(I have a few reservations about)나 대안(from another angle)을 제시하세요.`,registerSpectrum:{casual:`I totally get your point, though I wonder if a flat discount might hurt renewals.`,standard:`I see where you're coming from, however I have a few reservations about cutting our margin.`,formal:`While I appreciate the rationale behind rapid acquisition, I have certain reservations regarding its long-term impact on margin integrity.`}},{title:`원리 02 · 침묵 깨기 공식: 발언권 얻기(jump in / chime in) & 이어받기(build on / piggyback on)`,coreFormula:`May I jump in real quick? / To build on what [이름] just said, ... / To echo [이름]'s point, ...`,wrongKonglish:`Wait, stop talking. I also want to speak my different idea.`,rightNative:`Sorry to jump in—to build on what Hannah just mentioned, I'd like to add one data point.`,explanationKo:`글로벌 회의에서는 앞사람이 숨을 고르는 0.5초 사이에 "Sorry to jump in"이나 "Can I chime in real quick?"으로 신호를 주어야 발언권이 열립니다. 특히 앞사람 이름을 부르며 "To build on what [이름] said"로 연결하면 흐름을 끊는 게 아니라 대화를 확장하는 최고의 화법이 됩니다.`,registerSpectrum:{casual:`Mind if I chime in real quick? Just to piggyback on Sarah's idea...`,standard:`May I jump in here? To build on what Sarah mentioned, we could try a bundle.`,formal:`If I may interject briefly, I'd like to echo Sarah's observation and build upon it with Q3 data.`}},{title:`원리 03 · 반론의 날을 둥글게 만드는 Hedging(완화) 전략 & devil's advocate`,coreFormula:`Just to play devil's advocate, ... / What if we look at this from another angle? / Wouldn't [대상] push back if ~?`,wrongKonglish:`Customers will hate this and complain a lot. We must change it.`,rightNative:`Just to play devil's advocate, wouldn't existing customers push back if they saw a 30% public discount?`,explanationKo:`단정적인 미래 시제("will hate / must change") 대신 부정의문문("Wouldn't ~?")이나 가정 질문("What if we ~?")을 쓰면 상대방이 스스로 리스크를 깨닫게 유도할 수 있습니다. 여기에 "Just to play devil's advocate"를 붙이면 "개인적 반대가 아니라 팀을 위한 스트레스 테스트"라는 안전장치가 생깁니다.`,registerSpectrum:{casual:`Playing devil's advocate here—what if existing users get mad?`,standard:`Just to play devil's advocate, wouldn't existing clients push back on a public discount?`,formal:`Purely to stress-test our assumptions, might we anticipate pushback from legacy accounts upon renewal?`}}],sprintDrills:[{id:`d16-s01`,drillType:`chunk-build`,promptKo:`잠깐 끼어들어서 한마디 보태도 될까요?`,promptEnHint:`May I + jump in + real quick 조합을 만드세요.`,targetEn:`May I jump in real quick here?`,chunks:[`May I`,`jump in`,`real quick`,`here?`],explanationKo:`회의 흐름을 깨지 않고 자연스럽게 발언권을 요청하는 1순위 표현입니다.`},{id:`d16-s02`,drillType:`konglish-fix`,promptKo:`"어떤 관점에서 말씀하시는지 충분히 이해합니다."`,promptEnHint:`상대 입장을 이해한다는 원어민 핵심 관용구를 고르세요.`,targetEn:`I totally see where you're coming from.`,wrongKonglishOption:`I totally see where your mind is walking from.`,explanationKo:`see where you're coming from은 반론 전 최고의 공감 쿠션 표현입니다.`},{id:`d16-s03`,drillType:`active-blank`,promptKo:`일괄 할인을 제공하는 데 대해서는 몇 가지 우려가 있습니다.`,promptEnHint:`우려·유보적 태도(복수형): r___________ (12글자)`,targetEn:`I have a few reservations about the discount.`,blankData:{before:`I have a few`,answer:`reservations`,after:`about the discount.`,firstLetterHint:`r___________ (12글자)`},explanationKo:`have reservations about ~ 은 정중하고 고급스러운 반론 표현입니다.`},{id:`d16-s04`,drillType:`chunk-build`,promptKo:`한나 님이 방금 말씀하신 내용에 덧붙이자면, 우리도 데이터가 있습니다.`,promptEnHint:`To build on + what Hannah just said 청크를 연결하세요.`,targetEn:`To build on what Hannah just said, we have data too.`,chunks:[`To build on`,`what Hannah just said,`,`we have`,`data too.`],explanationKo:`앞사람의 발언을 이어받아 발전시킬 때 To build on what ~ just said가 최고입니다.`},{id:`d16-s05`,drillType:`active-blank`,promptKo:`검증 차원에서 일부러 반대 입장을 취해 보자면, 비용이 너무 높지 않을까요?`,promptEnHint:`play devil's ________ (8글자)`,targetEn:`Just to play devil's advocate, isn't the cost too high?`,blankData:{before:`Just to play devil's`,answer:`advocate`,after:`, isn't the cost too high?`,firstLetterHint:`a_______ (8글자)`},explanationKo:`play devil's advocate는 논리 검증을 위해 의도적으로 반대 시각을 제시하는 고급 관용구입니다.`},{id:`d16-s06`,drillType:`konglish-fix`,promptKo:`"한나 님의 매출 예측이 정확히 핵심을 찔렀어요(딱 맞았어요)."`,promptEnHint:`"정확히 딱 맞는"을 뜻하는 원어민 형용사구를 고르세요.`,targetEn:`Hannah's revenue forecast was spot on.`,wrongKonglishOption:`Hannah's revenue forecast was point shoot.`,explanationKo:`정확히 핵심을 찌르거나 예측이 딱 맞을 때 spot on을 씁니다.`},{id:`d16-s07`,drillType:`chunk-build`,promptKo:`이 문제를 잠시 다른 관점에서 바라보면 어떨까요?`,promptEnHint:`What if we look at this + from another angle 패턴을 조립하세요.`,targetEn:`What if we look at this from another angle?`,chunks:[`What if we`,`look at this`,`from another`,`angle?`],explanationKo:`대안을 제시할 때 from another angle로 프레이밍하면 거부감이 크게 줄어듭니다.`},{id:`d16-s08`,drillType:`active-blank`,promptKo:`긴 토론 끝에 마침내 합의에 도달했습니다.`,promptEnHint:`합의(동의): reach a _________ (9글자)`,targetEn:`We finally reached a consensus on the plan.`,blankData:{before:`We finally reached a`,answer:`consensus`,after:`on the plan.`,firstLetterHint:`c________ (9글자)`},explanationKo:`reach a consensus는 회의 결론 도출을 표현하는 필수 연어입니다.`},{id:`d16-s09`,drillType:`konglish-fix`,promptKo:`"시간이 부족하니 그 안건은 일단 보류해 두죠."`,promptEnHint:`미국 비즈니스 영어에서 안건을 보류하는 동사를 고르세요.`,targetEn:`Since we're short on time, let's table that topic for now.`,wrongKonglishOption:`Since we're short on time, let's chair that topic for now.`,explanationKo:`미국 실무 영어에서 안건을 나중으로 보류하다는 동사 table을 씁니다.`},{id:`d16-s10`,drillType:`chunk-build`,promptKo:`온보딩 비용 이야기를 꺼내 주셔서 정말 다행이에요.`,promptEnHint:`I'm glad you + brought up 패턴을 조립하세요.`,targetEn:`I'm glad you brought up the onboarding cost.`,chunks:[`I'm glad`,`you brought up`,`the onboarding`,`cost.`],explanationKo:`중요한 논점을 제기한 동료를 인정하는 최고의 회의 리액션입니다.`}],worksheetExam:[{id:`d16-e01`,number:1,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`의견 발전시키기 build on`,questionKo:`빈칸에 구동사(2단어)를 넣어 "데이비드 님 의견에 한 가지 덧붙이자면..."을 완성하세요.`,stimulusEn:`To __________ __________ David's point, we could bundle free training.`,answer:`build on`,acceptableAlt:[`piggyback on`],explanationKo:`앞사람의 의견을 토대로 살을 붙일 때 build on(또는 piggyback on)을 씁니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "한나 님 의견에 전적으로 동감합니다" 빈칸 동사(1단어)를 쓰세요.`,stimulusEn:`I'd like to __________ Hannah's point about protecting margin.`,answer:`echo`,explanationKo:`앞사람 의견에 메아리처럼 힘을 실어 동의할 때 동사 echo를 씁니다.`}},{id:`d16-e02`,number:2,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`공감 쿠션 coming from`,questionKo:`빈칸에 2단어를 넣어 "어떤 입장에서 말씀하시는지 충분히 이해합니다"를 완성하세요.`,stimulusEn:`I totally see where you're __________ __________.`,answer:`coming from`,explanationKo:`see where you're coming from은 반론 전 필수 공감 표현입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "아주 타당하고 일리 있는 지적을 하셨어요" 빈칸 형용사(1단어: v____)를 쓰세요.`,stimulusEn:`You make a very __________ point about customer retention.`,answer:`valid`,explanationKo:`타당한 지적은 make a valid point라고 합니다.`}},{id:`d16-e03`,number:3,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`완곡한 우려 reservations`,questionKo:`빈칸에 복수형 명사(1단어)를 넣어 "가격 정책 변경에 몇 가지 우려가 있습니다"를 완성하세요.`,stimulusEn:`I have a few __________ about changing the pricing model so suddenly.`,answer:`reservations`,explanationKo:`have reservations about ~ 은 완곡하고 격식 있는 반대·우려 표현입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "고객들의 반발·이견이 예상됩니다" 빈칸 명사(1단어: p_______)를 쓰세요.`,stimulusEn:`We might face some __________ from existing annual clients.`,answer:`pushback`,explanationKo:`제안·변화에 대한 반발과 이견은 붙여 쓴 명사 pushback입니다.`}},{id:`d16-e04`,number:4,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`회의 발언권 chime in / jump in`,questionKo:`빈칸에 구동사(2단어)를 넣어 "데이터에 빠진 부분이 보이면 언제든 편하게 한마디 보태 주세요"를 완성하세요.`,stimulusEn:`Feel free to __________ __________ anytime if you notice any gaps.`,answer:`chime in`,acceptableAlt:[`jump in`],explanationKo:`회의 중 자연스럽게 의견을 보태는 구동사는 chime in 또는 jump in입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "그 중요한 이슈를 꺼내 주셔서 감사합니다" 빈칸 구동사 과거형(2단어)을 쓰세요.`,stimulusEn:`I'm glad you __________ __________ that security issue.`,answer:`brought up`,explanationKo:`안건을 제기하다는 bring up(과거형 brought up)입니다.`}},{id:`d16-e05`,number:5,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`합의 도출 consensus`,questionKo:`빈칸에 명사(1단어)를 넣어 "워크숍 번들 안으로 합의에 도달한 것 같네요"를 완성하세요.`,stimulusEn:`It looks like we've reached a __________ on the workshop bundle.`,answer:`consensus`,explanationKo:`합의에 도달하다는 reach a consensus입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "정확히 핵심을 찔렀어요!" 빈칸 형용사구(2단어: s___ o_)를 쓰세요.`,stimulusEn:`Your analysis of Q4 churn was __________ __________.`,answer:`spot on`,explanationKo:`정확히 들어맞거나 핵심을 찌를 때 spot on을 씁니다.`}},{id:`d16-e06`,number:6,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`완곡한 반론 톤 선택`,questionKo:`임원 회의에서 동료의 가격 할인 제안에 반대 의견을 제시할 때, 방어적 반발을 최소화하는 가장 세련된 문장은?`,stimulusEn:`공감 + 완충어 + 대안 관점 구조를 찾으세요.`,options:[`You are completely wrong because discounts destroy profit.`,`I see where you're coming from; however, I have a few reservations about cutting our margin.`,`I disagree with your idea and I refuse to support it.`,`Stop suggesting discounts because finance hates them.`],answer:`I see where you're coming from; however, I have a few reservations about cutting our margin.`,explanationKo:`상대의 의도를 인정한 뒤 however와 have reservations about으로 완곡하게 우려를 전하는 것이 프로페셔널합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "다른 관점에서 바라보다" 빈칸(3단어: f___ a______ a____)을 채우세요.`,stimulusEn:`Could we look at this proposal __________ __________ __________?`,answer:`from another angle`,explanationKo:`다른 시각으로 보자는 표현은 from another angle입니다.`}},{id:`d16-e07`,number:7,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`devil's advocate 의미 이해`,questionKo:`회의 중 동료가 "Just to play devil's advocate, what if the vendor misses launch?"라고 말했을 때의 정확한 의도는?`,stimulusEn:`관용구의 비즈니스 토론 맥락을 파악하세요.`,options:[`팀 프로젝트를 의도적으로 방해하고 실패시키려 한다`,`감정적으로 상대를 비난하기 위해 시비를 건다`,`의사결정의 허점을 검증하기 위해 일부러 반대 시각의 리스크를 질문한다`,`변호사를 선임해 벤더사를 고소하자고 제안한다`],answer:`의사결정의 허점을 검증하기 위해 일부러 반대 시각의 리스크를 질문한다`,explanationKo:`play devil's advocate는 팀의 의사결정을 더 탄탄하게 만들기 위해 의도적으로 반대 입장에서 검증 질문을 던지는 건설적 화법입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "일부러 반대 입장을 취해 보다" 빈칸 동사(1단어)를 쓰세요.`,stimulusEn:`Let me __________ devil's advocate for just a second.`,answer:`play`,explanationKo:`동사 play와 결합해 play devil's advocate로 씁니다.`}},{id:`d16-e08`,number:8,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`pushback vs push back 구분`,questionKo:`다음 문장의 빈칸에 들어갈 형태와 의미가 가장 알맞은 것은?`,stimulusEn:`We anticipated strong ______ from enterprise clients when we announced the price hike.`,options:[`pushback (명사 · 반발/이견)`,`push back (동사 · 일정을 미루다)`,`pushed back (과거분사 · 연기된)`,`pushing back (동명사 · 뒤로 밀기)`],answer:`pushback (명사 · 반발/이견)`,explanationKo:`형용사 strong의 수식을 받는 목적어 자리이므로 "반발·이견"을 뜻하는 명사 pushback이 정답입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 앞사람 아이디어를 이어받아 덧붙이다: _________ on (1단어, p로 시작)`,stimulusEn:`To __________ on Soojin's suggestion, we could run a two-week pilot.`,answer:`piggyback`,explanationKo:`piggyback on은 build on과 함께 쓰이는 생생한 미국 오피스 구동사입니다.`}},{id:`d16-e09`,number:9,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`미국 비즈니스 동사 table`,questionKo:`미국 본사와의 회의에서 진행자가 "Let's table the logo refresh until next Tuesday"라고 했을 때의 정확한 의미는?`,stimulusEn:`미국 비즈니스 회의에서의 table 용법을 확인하세요.`,options:[`지금 당장 로고 리뉴얼을 끝낼 때까지 회의를 연장하자`,`로고 리뉴얼 안건은 다음 주 화요일로 잠시 보류해 두자`,`로고 디자인을 표(table) 형태로 엑셀에 정리하자`,`로고 리뉴얼 프로젝트를 영구 폐기하자`],answer:`로고 리뉴얼 안건은 다음 주 화요일로 잠시 보류해 두자`,explanationKo:`미국 비즈니스에서 table [안건]은 논의를 나중으로 보류하다(postpone / park)는 뜻입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "완전히 설득됐습니다! 동의해요!"를 뜻하는 2단어 원어민 표현(I'm ____!)을 쓰세요.`,stimulusEn:`Great pitch—__________ __________, let's move forward with the bundle!`,answer:`I'm sold`,explanationKo:`I'm sold는 상대 제안에 완전히 설득되어 찬성한다는 자연스러운 회화 표현입니다.`}},{id:`d16-e10`,number:10,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`정중한 발언권 요청 표현`,questionKo:`동료들이 열띤 토론을 이어가고 있을 때 무례해 보이지 않게 발언권을 요청하는 가장 자연스러운 문장은?`,stimulusEn:`서구권 회의 에티켓에 맞는 발언권 요청을 고르세요.`,options:[`Be quiet now, it is my turn to speak.`,`May I jump in real quick to build on what Maya just said?`,`Stop your sentence because I have better opinion.`,`Wait everybody, I must interrupt your talking.`],answer:`May I jump in real quick to build on what Maya just said?`,explanationKo:`May I jump in real quick + to build on what ~ just said 조합은 예의와 주도성을 모두 갖춘 최고의 발언 시작법입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "이 제안은 타당한 근거가 있습니다" 빈칸 동사(1단어)를 쓰세요.`,stimulusEn:`I think David __________ a very valid point about Q4 growth.`,answer:`makes`,explanationKo:`3인칭 단수 David에 맞춰 makes a valid point로 씁니다.`}},{id:`d16-e11`,number:11,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`발언 이어받기 배열`,questionKo:`주어진 청크를 올바른 순서로 배열하여 앞사람 의견을 발전시키는 문장을 완성하세요.`,stimulusEn:`[ build on / Hannah's point, / we could / To / offer a free trial. ]`,answer:`To build on Hannah's point, we could offer a free trial.`,explanationKo:`To build on [이름]'s point, + [내 제안] 구조는 회의 참여도를 극대화합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "잠깐 끼어들어도 될까요?" (May I / jump in / real quick?)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`May I jump in real quick?`,explanationKo:`짧고 정중한 발언권 요청 의문문입니다.`}},{id:`d16-e12`,number:12,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`공감 + 반론 배열`,questionKo:`주어진 청크를 배열하여 완곡한 반론 문장을 완성하세요.`,stimulusEn:`[ coming from, / I see / about the timeline. / where you're / but I have reservations ]`,answer:`I see where you're coming from, but I have reservations about the timeline.`,explanationKo:`공감 절 뒤에 but I have reservations about [대상]을 연결한 B2 표준 반론 문장입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "다른 관점에서 이것을 보면 어떨까요?" (What if we / look at this / from another angle?)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`What if we look at this from another angle?`,explanationKo:`What if we ~ ?로 부드럽게 대안을 제시합니다.`}},{id:`d16-e13`,number:13,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`동감 & 보류 영작`,questionKo:`우리말 뜻에 맞게 주어진 단어를 활용해 자연스러운 회의 발언을 완성하세요.`,stimulusEn:`우리말: 마진을 지켜야 한다는 한나 님 의견에 동감합니다. (I’d like to / echo Hannah’s point / about protecting our margin.)`,answer:`I'd like to echo Hannah's point about protecting our margin.`,explanationKo:`echo [사람]'s point about ~ 구문으로 동료의 논리에 힘을 실어 줍니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "그 안건은 목요일 회의로 잠시 보류해 두죠." (Let’s table / that topic / until Thursday’s meeting.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`Let's table that topic until Thursday's meeting.`,explanationKo:`동사 table + 안건 + until [시점] 어순입니다.`}},{id:`d16-e14`,number:14,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`콩글리시 교정 서술형`,questionKo:`다음 직설적 문장을 오늘 배운 완곡 반론 표현(valid point, reservations about)으로 고쳐 쓰세요.`,stimulusEn:`오류 문장: Your point is okay, but I disagree with the 30% discount.`,answer:`You make a valid point, but I have reservations about the 30% discount.`,acceptableAlt:[`That is a valid point, but I have a few reservations about the 30% discount.`,`That's a valid point, but I have reservations about the 30% discount.`],explanationKo:`단순 disagree를 have reservations about으로 바꾸면 품격 있는 비즈니스 반론이 됩니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 오류 교정: Your analysis is completely right! → spot on을 써서 5단어로 고치세요.`,stimulusEn:`힌트: Your analysis ~.`,answer:`Your analysis is spot on!`,explanationKo:`spot on은 원어민이 회의에서 가장 자주 쓰는 찬사입니다.`}},{id:`d16-e15`,number:15,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`실전 통문장 영작`,questionKo:`다음 우리말을 영어로 자연스럽게 작성하세요.`,stimulusEn:`우리말: 긴 토론 끝에 마침내 합의에 도달한 것 같네요. (힌트: It looks like / we’ve reached a consensus / after a long debate.)`,answer:`It looks like we've reached a consensus after a long debate.`,acceptableAlt:[`Looks like we reached a consensus after a long debate.`],explanationKo:`reach a consensus로 회의를 깔끔하게 정리하는 실전 표현입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "그 리스크를 꺼내 주셔서 정말 다행이에요." (I’m really glad / you brought up / that risk.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`I'm really glad you brought up that risk.`,explanationKo:`bring up의 과거형 brought up을 활용한 긍정적 리액션입니다.`}}],tutorScenario:{openingQuestionEn:`So here's my pitch: to boost sign-ups next month, let's cut our subscription price by 40% across every plan! Everyone onboard with moving ahead on this?`,openingQuestionKo:`제 제안은 이렇습니다: 다음 달 가입자를 늘리기 위해 모든 요금제 가격을 40% 인하합시다! 다들 이대로 진행하는 데 찬성하시죠? (정중히 끼어들어 상대 의도를 인정한 뒤, 마진이나 기존 고객 반발에 대한 우려와 대안을 완곡하게 제시해 보세요!)`,followUpQuestionEn:`You make a really valid point—I hadn't factored in pushback from our annual clients. What alternative would you propose instead of a flat discount?`,followUpQuestionKo:`아주 타당한 지적이네요—기존 연간 고객 반발까지는 미처 계산 못 했어요. 일괄 할인 대신 어떤 대안을 제안하시겠어요?`,recommendedChunks:[`May I jump in real quick?`,`I see where you're coming from`,`have a few reservations about`,`play devil's advocate`,`pushback from existing clients`,`look at this from another angle`],modelAnswerEn:`May I jump in real quick? I totally see where you're coming from on boosting sign-ups, and you make a valid point about urgency. That said, I have a few reservations about a flat 40% cut—just to play devil's advocate, wouldn't existing annual clients push back? What if we look at this from another angle and offer free onboarding workshops instead?`}},{dayNumber:17,weekNumber:3,cefrLevel:`b2`,dayBadge:`DAY 17 · 건설적 피드백 & 예의 바른 거절`,categoryLabel:`Week 3 오피스 실무 · 피드백 화법 & 업무 경계 설정`,title:`솔직한 피드백 감사해요, 다만 지금은 여력이 꽉 찼습니다`,subtitle:`감정을 상하지 않게 건설적 피드백(Constructive Feedback)을 주고받고, 업무 과부하(At capacity) 상황에서 프로답게 경계를 지키는 거절 기술`,heroImage:`assets/office_sitcom_scene.jpg`,secondaryImage:`assets/scene_boardroom_pitch.jpg`,estimatedSprintMin:8,estimatedLectureMin:45,keyExpression:`I really appreciate the heads-up, though I'm currently at capacity this week.`,keySentenceByTier:{a1:`Thank you for your feedback. Sorry, I am too busy this week.`,a2:`Thanks for telling me early, but I have too much work on my desk right now.`,b1:`I really appreciate your constructive feedback, though I have a lot on my plate this week.`,b2:`I really appreciate the heads-up and actionable feedback, though I'm currently at capacity—could we meet halfway on the timeline?`,c1:`Thank you for sharing such constructive feedback without sugarcoating it; that said, I'm stretched a bit thin right now and would hate to overcommit, so I'll have to pass on the extra deck this week.`,c2:`I genuinely appreciate you flagging those areas with room for improvement; however, given that I'm at full capacity through Thursday, I'd rather decline the rush request transparently than overcommit and compromise quality.`},youtubeVideo:e[17],readingPassage:{titleEn:`Giving Honest Feedback and Saying No Without Burning Bridges`,titleKo:`[1:1 피드백 가이드] 관계를 지키며 솔직히 피드백하고 정중하게 거절하는 법`,genreBadge:`1:1 피드백 노트 · Lv.4`,estimatedMin:6,paragraphsEn:[`In high-performing global teams, honest feedback is treated as a gift rather than a personal attack. Still, wording matters tremendously. Instead of telling a colleague "Your deck is confusing," experienced managers frame observations around the work itself: "The narrative is strong overall, though there is room for improvement on slide four—have you considered simplifying the chart so executives can scan it faster?"`,`Receiving feedback gracefully builds just as much credibility as giving it. Rather than taking criticism personally or jumping straight into excuses, strong professionals respond with curiosity: "I really appreciate the heads-up—that feedback is super actionable, and I will revise the layout whenever I get a chance this afternoon."`,`Equally vital is knowing how to decline extra requests when you already have too much on your plate. Saying yes to everything eventually leaves you stretched thin and forces you to overcommit. A respectful refusal never burns bridges: acknowledge the request, state clearly that you are at capacity, and offer to meet halfway—for instance, passing on a rush slide deck today while offering a quick review early next week, with no rush on their end.`],paragraphsSlash:[`In high-performing global teams, / honest feedback is treated as a gift / rather than a personal attack. / Still, wording matters tremendously. / Instead of telling a colleague "Your deck is confusing," / experienced managers frame observations / around the work itself: / "The narrative is strong overall, / though there is room for improvement on slide four— / have you considered simplifying the chart / so executives can scan it faster?"`,`Receiving feedback gracefully / builds just as much credibility as giving it. / Rather than taking criticism personally / or jumping straight into excuses, / strong professionals respond with curiosity: / "I really appreciate the heads-up— / that feedback is super actionable, / and I will revise the layout / whenever I get a chance this afternoon."`,`Equally vital is knowing how to decline extra requests / when you already have too much on your plate. / Saying yes to everything / eventually leaves you stretched thin / and forces you to overcommit. / A respectful refusal never burns bridges: / acknowledge the request, / state clearly that you are at capacity, / and offer to meet halfway— / for instance, passing on a rush slide deck today / while offering a quick review early next week, / with no rush on their end.`],paragraphsKo:[`고성과 글로벌 팀에서 솔직한 피드백은 개인에 대한 공격이 아니라 성장의 선물로 여겨집니다. 그럼에도 말의 표현 방식은 엄청나게 중요합니다. 동료에게 "자료가 너무 헷갈려요"라고 말하는 대신, 노련한 매니저는 사람이 아닌 결과물 자체에 초점을 맞춥니다. "전반적인 스토리라인은 탄탄한데 4번 슬라이드는 개선의 여지가 있어 보여요. 임원들이 더 빨리 훑어볼 수 있도록 차트를 단순화해 보는 건 고려해 보셨나요?"처럼요.`,`피드백을 의연하게 받아들이는 태도 역시 피드백을 주는 것만큼이나 큰 신뢰를 쌓아줍니다. 지적을 감정적으로 받아들이거나 곧장 변명으로 넘어가기보다, 프로들은 호기심 어린 태도로 응답합니다. "미리 귀띔해 주셔서 정말 감사해요. 바로 실행에 옮길 수 있는 구체적인 피드백이네요. 오늘 오후 짬이 날 때 레이아웃을 수정하겠습니다."`,`이미 해야 할 일이 산더미처럼 쌓여 있을 때 추가 업무 요청을 거절할 줄 아는 것도 똑같이 중요합니다. 모든 요청에 무조건 예스라고 답하다 보면 결국 여력이 한계까지 흩어지고 무리하게 약속을 떠안게 됩니다. 예의 바른 거절은 결코 관계를 망치지 않습니다. 요청을 존중하되 현재 업무량이 최대치임을 명확히 밝히고, 오늘 급한 발표 자료 제작은 정중히 사양하는 대신 다음 주 초에 빠른 리뷰를 도와주는 식으로 타협점을 제안해 보세요.`],keyExpressions:[`room for improvement`,`have you considered ~?`,`appreciate the heads-up`,`take ~ personally`,`at capacity / on my plate`,`meet halfway / burn bridges`],comprehensionQuiz:[{id:`d17-rq01`,questionKo:`노련한 매니저가 "Your deck is confusing" 대신 사용하는 건설적 피드백 전략은 무엇인가요?`,options:[`동료가 상처받지 않도록 단점은 아예 언급하지 않는다`,`사람이 아닌 결과물에 초점을 맞추고 "Have you considered ~?" 같은 제안 질문으로 풀어낸다`,`팀 전체가 보는 공개 채널에서 잘못된 슬라이드를 지적한다`,`동료 대신 매니저가 직접 모든 슬라이드를 다시 제작한다`],answer:`사람이 아닌 결과물에 초점을 맞추고 "Have you considered ~?" 같은 제안 질문으로 풀어낸다`,explanationKo:`첫째 문단 "frame observations around the work itself ... have you considered simplifying the chart"가 핵심 전략입니다.`},{id:`d17-rq02`,questionKo:`모든 업무 요청에 무조건 승낙(yes)할 때 생기는 부작용으로 본문이 지적한 것은?`,options:[`동료들과의 관계가 영구적으로 단절된다`,`여력이 한계까지 분산되고(stretched thin) 감당 못 할 약속을 떠안게(overcommit) 된다`,`승진 심사에 즉시 불이익이 발생한다`,`피드백을 받을 기회를 영원히 잃게 된다`],answer:`여력이 한계까지 분산되고(stretched thin) 감당 못 할 약속을 떠안게(overcommit) 된다`,explanationKo:`셋째 문단 "Saying yes to everything eventually leaves you stretched thin and forces you to overcommit"을 확인하세요.`},{id:`d17-rq03`,questionKo:`본문에서 "서로 한 발씩 양보해 타협점을 찾다"를 뜻하는 원어민 표현은?`,options:[`burn bridges`,`pass on`,`meet halfway`,`take personally`],answer:`meet halfway`,explanationKo:`meet (someone) halfway는 양측이 조금씩 양보하여 현실적 타협점을 찾는다는 핵심 비즈니스 표현입니다.`}]},vocabList:[{id:`d17-v01`,word:`constructive feedback`,phonetic:`/kənˈstrʌktɪv ˈfiːdbæk/`,pos:`명사구`,cefr:`b2`,meaningKo:`발전을 돕는 건설적인 피드백`,meaningEn:`helpful, specific advice aimed at improving future performance`,nuanceTipKo:`단순 비난(criticism)과 구분되는 표현! "I'm always open to constructive feedback"이라고 말하면 성장 마인드셋을 보여줄 수 있습니다.`,exampleEn:`Thank you for giving me such clear, constructive feedback after the demo.`,exampleKo:`데모 발표 후 이렇게 명확하고 건설적인 피드백을 주셔서 감사합니다.`},{id:`d17-v02`,word:`appreciate the heads-up`,phonetic:`/əˈpriːʃieɪt ðə ˈhedz ʌp/`,pos:`동사 구문`,cefr:`b2`,meaningKo:`미리 알려줘서(귀띔해 줘서) 고맙다`,meaningEn:`be grateful for an advance warning or early notice`,nuanceTipKo:`주의! "I appreciate you"보다 "I appreciate + [사물/행동(the heads-up / your feedback)]" 형태가 훨씬 자연스럽고 정중합니다.`,exampleEn:`I really appreciate the heads-up—I will adjust the slides before tomorrow.`,exampleKo:`미리 귀띔해 주셔서 정말 감사합니다. 내일 전까지 슬라이드를 수정하겠습니다.`},{id:`d17-v03`,word:`at capacity`,phonetic:`/æt kəˈpæsəti/`,pos:`전치사구`,cefr:`b2`,meaningKo:`(업무량이) 최대치에 달한, 더 맡을 여력이 없는`,meaningEn:`operating at maximum workload with no room to take on additional tasks`,nuanceTipKo:`"I'm too busy"는 감정적이고 막연하게 들립니다. "I'm currently at capacity this week"라고 하면 객관적이고 프로페셔널한 거절이 됩니다.`,exampleEn:`I'd love to help, but I'm completely at capacity through Thursday.`,exampleKo:`도와드리고 싶지만 목요일까지는 현재 업무량이 완전히 꽉 찬 상태입니다.`},{id:`d17-v04`,word:`have a lot on one's plate`,phonetic:`/hæv ə lɑːt ɑːn wʌnz pleɪt/`,pos:`관용구`,cefr:`b2`,meaningKo:`해야 할 일이 접시에 산더미처럼 쌓여 있다`,meaningEn:`have many demanding tasks or responsibilities to manage at once`,nuanceTipKo:`뷔페 접시(plate)에 음식이 넘칠 듯 담긴 이미지! "I have a lot on my plate right now"는 동료 간 공감대를 끌어내는 만능 표현입니다.`,exampleEn:`With the launch and hiring interviews, I have a lot on my plate this sprint.`,exampleKo:`출시 준비에 채용 면접까지 겹쳐서 이번 스프린트에 할 일이 산더미처럼 쌓여 있어요.`},{id:`d17-v05`,word:`room for improvement`,phonetic:`/ruːm fɔːr ɪmˈpruːvmənt/`,pos:`명사구`,cefr:`b2`,meaningKo:`개선의 여지, 더 나아질 수 있는 부분`,meaningEn:`areas where something can be made better`,nuanceTipKo:`부족함을 "bad / weak"라고 직격하지 않고 "There's still some room for improvement in ~"으로 감싸면 반감 없이 피드백을 전할 수 있습니다.`,exampleEn:`Your presentation delivery was great, though there is room for improvement on pacing.`,exampleKo:`발표 전달력은 훌륭했지만, 속도 조절 면에서는 조금 개선의 여지가 있습니다.`},{id:`d17-v06`,word:`actionable`,phonetic:`/ˈækʃənəbl/`,pos:`형용사`,cefr:`b2`,meaningKo:`구체적으로 바로 실행에 옮길 수 있는`,meaningEn:`specific and practical enough to act on right away`,nuanceTipKo:`좋은 피드백을 칭찬할 때 "That feedback is super actionable!"이라고 쓰면 미국 오피스 원어민 감성이 그대로 살아납니다.`,exampleEn:`Claire always shares specific, actionable takeaways during our 1-on-1s.`,exampleKo:`클레어는 1:1 미팅 때 늘 구체적이고 바로 실행 가능한 시사점을 공유해 줍니다.`},{id:`d17-v07`,word:`take ~ personally`,phonetic:`/teɪk ˈpɜːrsənəli/`,pos:`동사 구문`,cefr:`b1`,meaningKo:`(지적·거절을) 개인적 공격으로 감정적으로 받아들이다`,meaningEn:`react emotionally to criticism as if it were an attack on you as a person`,nuanceTipKo:`피드백할 때 "Please don't take this personally" 또는 받을 때 "I won't take it personally—be honest!"로 심리적 안전감을 만듭니다.`,exampleEn:`Please don't take this personally—the edits are purely to match client guidelines.`,exampleKo:`개인적인 지적으로 받아들이지 마세요, 수정 사항은 순전히 클라이언트 가이드라인에 맞추기 위한 거예요.`},{id:`d17-v08`,word:`stretched thin`,phonetic:`/stretʃt θɪn/`,pos:`형용사구`,cefr:`c1`,meaningKo:`(시간·인력이) 너무 여러 곳에 분산되어 한계에 다다른`,meaningEn:`spread across too many tasks or projects to perform comfortably`,nuanceTipKo:`버터를 넓은 빵에 너무 얇게 펴 바른 이미지에서 온 표현! "Our team is stretched pretty thin right now"처럼 씁니다.`,exampleEn:`With two teammates on leave, our design team is stretched really thin this month.`,exampleKo:`팀원 두 명이 휴가 중이라 이번 달 우리 디자인 팀 여력이 정말 한계에 다다랐습니다.`},{id:`d17-v09`,word:`overcommit`,phonetic:`/ˌoʊvərkəˈmɪt/`,pos:`동사`,cefr:`b2`,meaningKo:`감당할 수 없을 만큼 무리하게 약속·업무를 떠안다`,meaningEn:`promise to take on more work than you can realistically deliver`,nuanceTipKo:`거절의 명분을 "품질 보호"로 프레이밍할 때 "I don't want to overcommit and miss the deadline"이 최고의 설득 문장입니다.`,exampleEn:`I'd rather be upfront now than overcommit and deliver rushed work.`,exampleKo:`무리하게 떠안았다가 완성도 낮은 결과물을 내느니 지금 솔직히 말씀드리는 게 낫겠습니다.`},{id:`d17-v10`,word:`meet (someone) halfway`,phonetic:`/miːt ˈhæfweɪ/`,pos:`관용구`,cefr:`b2`,meaningKo:`서로 한 발씩 양보해 중간 타협점을 찾다`,meaningEn:`reach a compromise where both sides adjust their expectations`,nuanceTipKo:`전부 거절하기 어려울 때 "I can't write the whole deck, but let me meet you halfway and review your draft"처럼 쓰면 협업 점수가 만점이 됩니다.`,exampleEn:`I can't lead the full audit this week, but I can meet you halfway by reviewing the key metrics.`,exampleKo:`이번 주 전체 감사를 주도하긴 어렵지만, 핵심 지표 검토를 맡는 선에서 타협점을 맞춰볼 수 있어요.`},{id:`d17-v11`,word:`have you considered ~?`,phonetic:`/hæv juː kənˈsɪdərd/`,pos:`의문 구문`,cefr:`b2`,meaningKo:`~하는 방안도 고려해 보셨나요? (부드러운 피드백 제안)`,meaningEn:`a polite, non-directive way to suggest an improvement or alternative`,nuanceTipKo:`상대방의 자존심을 지켜주며 개선점을 제안하는 최고의 피드백 공식! 뒤에는 반드시 동명사(V-ing)나 명사가 옵니다.`,exampleEn:`Have you considered opening the presentation with the customer quote instead?`,exampleKo:`발표를 고객 인용구로 시작하는 방안도 고려해 보셨나요?`},{id:`d17-v12`,word:`no rush`,phonetic:`/noʊ rʌʃ/`,pos:`관용구`,cefr:`b1`,meaningKo:`급하지 않으니 천천히 하세요`,meaningEn:`there is no urgency; take your time responding`,nuanceTipKo:`동료에게 부탁할 때 "No rush at all!"을 덧붙이면 상대방의 심리적 부담을 확 낮춰 줍니다.`,exampleEn:`Could you share the updated slides by Friday? No rush at all!`,exampleKo:`금요일까지 수정된 슬라이드 공유해 주실 수 있을까요? 전혀 급하지 않아요!`},{id:`d17-v13`,word:`whenever you get a chance`,phonetic:`/wenˈevər juː ɡet ə tʃæns/`,pos:`부사절`,cefr:`b1`,meaningKo:`시간 나실 때 편하게 (부담 없는 요청)`,meaningEn:`at any convenient moment when you have a free minute`,nuanceTipKo:`no rush와 단짝으로 쓰이는 미국 오피스 배려 표현! 슬랙 요청 끝에 붙이면 톤이 한결 부드러워집니다.`,exampleEn:`Feel free to drop your comments in the doc whenever you get a chance.`,exampleKo:`시간 나실 때 편하게 문서에 코멘트 남겨 주세요.`},{id:`d17-v14`,word:`pass on (a request)`,phonetic:`/pæs ɑːn/`,pos:`구동사`,cefr:`b2`,meaningKo:`(제안·추가 업무를) 정중히 사양하다, 이번엔 건너뛰다`,meaningEn:`politely decline an invitation, offer, or extra assignment`,nuanceTipKo:`"I reject your request"는 절대 금물! "I'll have to pass on this one"으로 담백하고 매너 있게 거절하세요.`,exampleEn:`Unfortunately, I'll have to pass on joining the side committee this quarter.`,exampleKo:`아쉽게도 이번 분기에는 별도 위원회 참여는 정중히 사양해야 할 것 같습니다.`},{id:`d17-v15`,word:`burn bridges`,phonetic:`/bɜːrn ˈbrɪdʒɪz/`,pos:`관용구`,cefr:`c1`,meaningKo:`관계를 완전히 망쳐 되돌릴 수 없게 만들다`,meaningEn:`permanently damage a professional relationship through harsh words or actions`,nuanceTipKo:`건너온 다리를 불태워 다시 못 돌아가게 만든다는 비유! 퇴사·거절·갈등 상황에서 "without burning bridges"로 자주 씁니다.`,exampleEn:`Learning to say no clearly without burning bridges is a key leadership skill.`,exampleKo:`관계를 망치지 않으면서도 명확하게 거절하는 법을 익히는 것은 핵심 리더십 역량입니다.`}],dialogue:[{id:`d17-t01`,speaker:`Claire`,roleLabel:`디자인 매니저`,voicePitch:1.05,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`zoom-in`,english:`Hey Eunji, thanks for walking through the usability deck earlier. Overall the insights were super clear—do you have a minute for some quick feedback?`,slashBroken:`Hey Eunji, / thanks for walking through the usability deck earlier. / Overall the insights were super clear— / do you have a minute / for some quick feedback?`,korean:`은지 님, 아까 사용성 조사 자료 설명해 줘서 고마워요. 전반적으로 인사이트가 아주 명확했어요. 짧은 피드백 나눌 시간 잠깐 괜찮을까요?`,keyHighlight:`do you have a minute for some quick feedback?`,noteKo:`긍정적 강점을 먼저 짚고 피드백을 나눌 준비가 됐는지 묻는 것이 신뢰 기반 1:1 화법의 시작입니다.`},{id:`d17-t02`,speaker:`Eunji`,roleLabel:`시니어 UX 리서처`,voicePitch:1.1,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`pan-right`,english:`Of course! I'm always open to constructive feedback—please be completely honest, I won't take it personally.`,slashBroken:`Of course! / I'm always open to constructive feedback— / please be completely honest, / I won't take it personally.`,korean:`물론이죠! 건설적인 피드백은 언제든 환영이에요. 개인적으로 받아들이지 않을 테니 완전히 솔직하게 말씀해 주세요.`,keyHighlight:`I'm always open to constructive feedback`,noteKo:`"won't take it personally" 한마디로 피드백하는 상대방의 심리적 부담을 확 내려줍니다.`},{id:`d17-t03`,speaker:`Claire`,roleLabel:`디자인 매니저`,voicePitch:1.05,sceneImage:`assets/scene_boardroom_pitch.jpg`,cameraMotion:`pan-left`,english:`Awesome. There is a bit of room for improvement on the data slides—have you considered trimming the bullet points so executives can scan them faster?`,slashBroken:`Awesome. / There is a bit of room for improvement / on the data slides— / have you considered trimming the bullet points / so executives can scan them faster?`,korean:`좋아요. 데이터 슬라이드 쪽에 조금 개선의 여지가 있어 보이는데요, 임원들이 더 빨리 훑어볼 수 있게 불릿 항목을 줄여보는 건 고려해 보셨나요?`,keyHighlight:`have you considered trimming the bullet points`,noteKo:`"room for improvement" + "have you considered + V-ing?"은 명령조 없는 완벽한 건설적 피드백 공식입니다.`},{id:`d17-t04`,speaker:`Eunji`,roleLabel:`시니어 UX 리서처`,voicePitch:1.1,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`zoom-in`,english:`Ooh, I really appreciate the heads-up! That's super actionable—I'll tighten slides five and six whenever I get a chance this afternoon.`,slashBroken:`Ooh, I really appreciate the heads-up! / That's super actionable— / I'll tighten slides five and six / whenever I get a chance this afternoon.`,korean:`오, 미리 귀띔해 주셔서 정말 감사해요! 바로 실행할 수 있는 구체적인 피드백이네요. 오늘 오후 짬이 날 때 5·6번 슬라이드를 압축해 둘게요.`,keyHighlight:`I really appreciate the heads-up`,noteKo:`감사(appreciate the heads-up) + 인정(super actionable) + 실행 계획(I'll tighten ~)의 프로다운 피드백 수용 3단계입니다.`},{id:`d17-t05`,speaker:`Claire`,roleLabel:`디자인 매니저`,voicePitch:1.05,sceneImage:`assets/scene_boardroom_pitch.jpg`,cameraMotion:`pan-right`,english:`No rush at all—tomorrow morning works too. Oh, by the way, sales asked if someone could also put together an extra competitor deck by Thursday. Could you take that on?`,slashBroken:`No rush at all— / tomorrow morning works too. / Oh, by the way, / sales asked if someone could also put together / an extra competitor deck by Thursday. / Could you take that on?`,korean:`전혀 급하지 않아요, 내일 오전도 괜찮아요. 아 참, 세일즈 팀에서 목요일까지 경쟁사 분석 자료를 추가로 만들어 줄 사람이 있는지 묻던데, 혹시 맡아주실 수 있을까요?`,keyHighlight:`No rush at all`,noteKo:`take ~ on은 새로운 프로젝트나 업무를 떠맡다는 필수 오피스 구동사입니다.`},{id:`d17-t06`,speaker:`Eunji`,roleLabel:`시니어 UX 리서처`,voicePitch:1.1,sceneImage:`assets/office_sitcom_scene.jpg`,cameraMotion:`pan-left`,english:`I'd love to support sales, Claire, but I'm currently at capacity with user interviews and have a lot on my plate. I don't want to overcommit, so I'll have to pass on building the deck this week.`,slashBroken:`I'd love to support sales, Claire, / but I'm currently at capacity / with user interviews / and have a lot on my plate. / I don't want to overcommit, / so I'll have to pass on building the deck / this week.`,korean:`세일즈 팀을 도와드리고 싶지만 클레어, 지금 사용자 인터뷰로 업무량이 최대치이고 할 일이 정말 많아요. 무리하게 떠안고 싶지 않아서 이번 주 자료 제작은 정중히 사양해야 할 것 같아요.`,keyHighlight:`I'm currently at capacity`,noteKo:`협업 의지 표명(I'd love to ~) → 객관적 한계(at capacity) → 품질 보호 명분(don't want to overcommit) → 정중한 거절(pass on) 순서를 기억하세요.`},{id:`d17-t07`,speaker:`Eunji`,roleLabel:`시니어 UX 리서처`,voicePitch:1.1,sceneImage:`assets/scene_boardroom_pitch.jpg`,cameraMotion:`zoom-in`,english:`That said, I can meet them halfway—if they draft the outline, I can review the UX section early next week.`,slashBroken:`That said, / I can meet them halfway— / if they draft the outline, / I can review the UX section / early next week.`,korean:`그렇긴 하지만 중간 타협점은 맞출 수 있어요. 그쪽에서 개요 초안을 잡아주면 제가 다음 주 초에 UX 파트를 검토해 드릴 수 있습니다.`,keyHighlight:`meet them halfway`,noteKo:`거절 뒤에 현실적인 타협안(meet them halfway)을 붙이면 경계를 지키면서도 팀워크 신뢰도가 올라갑니다.`}],grammarSections:[{title:`원리 01 · 상처 주지 않는 건설적 피드백 공식: "You should fix" → "Have you considered + V-ing?"`,coreFormula:`There is room for improvement on [결과물] + Have you considered + [동명사 V-ing]?`,wrongKonglish:`Your slides are messy. You must reduce the text immediately.`,rightNative:`There is a bit of room for improvement on the data slides—have you considered trimming the bullet points?`,explanationKo:`피드백할 때 "You are / You must"로 사람에게 화살을 돌리면 방어 심리가 발동합니다. 대신 ① 결과물(the slides)을 주어로 "room for improvement"라고 부드럽게 짚고, ② 동사 consider 뒤에 동명사(V-ing)를 붙여 "Have you considered trimming ~?"으로 질문형 제안을 건네면 상대가 주도적으로 개선안을 수용합니다.`,registerSpectrum:{casual:`Love the story here—maybe we could trim slide four a bit so it pops more?`,standard:`There is room for improvement on the data slides—have you considered trimming the bullet points?`,formal:`While the analysis is compelling, we might strengthen executive readability by streamlining the key takeaways on slide four.`}},{title:`원리 02 · 관계를 지키는 업무 거절 3단 방패: [공감] + [객관적 한계] + [타협안]`,coreFormula:`I'd love to help, but I'm at capacity / have a lot on my plate → I don't want to overcommit → I can meet you halfway by ~`,wrongKonglish:`No, I'm too busy so I can't do your extra work. Ask another person.`,rightNative:`I'd love to help, but I'm currently at capacity this week and don't want to overcommit—I can meet you halfway by reviewing your draft next Monday.`,explanationKo:`단순히 "I'm too busy"라고 하면 협조하기 싫다는 느낌을 줄 수 있습니다. 현재 업무 최대치(at capacity / stretched thin)라는 객관적 사실을 알리고, "품질 저하를 막기 위해 무리하게 약속하지 않겠다(don't want to overcommit)"는 프로의 원칙을 밝힌 뒤 작은 타협안(meet you halfway)을 제시하면 결코 관계를 망치지(burn bridges) 않습니다.`,registerSpectrum:{casual:`I'd love to jump in, but my plate is totally full this week—could I review it Monday instead?`,standard:`I'm currently at capacity and will have to pass on building the deck, though I can meet you halfway by reviewing the draft next week.`,formal:`While I appreciate you thinking of me for this initiative, my current workload is at full capacity; to avoid overcommitting, I must respectfully pass this week, though I would be glad to advise early next week.`}},{title:`원리 03 · appreciate 문법 함정 & 배려 완충어(no rush / whenever you get a chance)`,coreFormula:`appreciate + [명사 / 소유격·목적격 + V-ing] (X: appreciate you to V / appreciate to V)`,wrongKonglish:`I really appreciate you to tell me early about this problem.`,rightNative:`I really appreciate you giving me a heads-up early about this issue.`,explanationKo:`한국인이 이메일과 회의에서 가장 자주 저지르는 동사 오류 중 하나가 appreciate 뒤에 to부정사를 쓰는 것입니다! appreciate는 반드시 명사("appreciate the heads-up / your feedback")나 동명사("appreciate you flagging this / your helping out")만 목적어로 취합니다.`,registerSpectrum:{casual:`Really appreciate the heads-up—no rush on the edits!`,standard:`I really appreciate you giving me a heads-up; feel free to share updates whenever you get a chance.`,formal:`I sincerely appreciate your timely heads-up and constructive feedback on this matter.`}}],sprintDrills:[{id:`d17-s01`,drillType:`chunk-build`,promptKo:`미리 귀띔해 주셔서 정말 감사해요.`,promptEnHint:`really appreciate + the heads-up 조합을 만드세요.`,targetEn:`I really appreciate the heads-up.`,chunks:[`I`,`really appreciate`,`the heads-up.`],explanationKo:`상대방의 사전 안내나 조기 피드백에 고마움을 전하는 최빈출 표현입니다.`},{id:`d17-s02`,drillType:`konglish-fix`,promptKo:`"일찍 알려주셔서 정말 감사합니다."`,promptEnHint:`동사 appreciate 뒤에 올 수 있는 올바른 목적어 형태를 고르세요.`,targetEn:`I really appreciate you telling me early.`,wrongKonglishOption:`I really appreciate you to tell me early.`,explanationKo:`appreciate는 to부정사가 아니라 명사 또는 동명사(telling)를 목적어로 취합니다.`},{id:`d17-s03`,drillType:`active-blank`,promptKo:`이번 주에는 업무량이 최대치라 더 맡기 어렵습니다.`,promptEnHint:`업무량이 꽉 찬 상태: at ________ (8글자)`,targetEn:`I'm currently at capacity this week.`,blankData:{before:`I'm currently at`,answer:`capacity`,after:`this week.`,firstLetterHint:`c_______ (8글자)`},explanationKo:`too busy 대신 객관적으로 업무 한계를 알리는 전문 표현은 at capacity입니다.`},{id:`d17-s04`,drillType:`chunk-build`,promptKo:`차트를 단순화해 보는 방안도 고려해 보셨나요?`,promptEnHint:`Have you considered + V-ing 피드백 공식을 조립하세요.`,targetEn:`Have you considered simplifying the chart?`,chunks:[`Have you`,`considered`,`simplifying`,`the chart?`],explanationKo:`consider 뒤에는 반드시 동명사(simplifying)가 와야 하며, 부드러운 제안 질문이 됩니다.`},{id:`d17-s05`,drillType:`active-blank`,promptKo:`개인적인 지적으로 받아들이지 않으셨으면 해요.`,promptEnHint:`감정적·개인적으로 받아들이다: take this __________ (10글자)`,targetEn:`Please don't take this personally.`,blankData:{before:`Please don't take this`,answer:`personally`,after:`.`,firstLetterHint:`p_________ (10글자)`},explanationKo:`take ~ personally는 피드백을 인신공격으로 받아들인다는 핵심 표현입니다.`},{id:`d17-s06`,drillType:`konglish-fix`,promptKo:`"이번 주에 해야 할 일이 산더미처럼 쌓여 있어요."`,promptEnHint:`업무가 가득 쌓였음을 뜻하는 원어민 접시 비유 관용구를 고르세요.`,targetEn:`I have a lot on my plate this week.`,wrongKonglishOption:`I have a lot on my bowl this week.`,explanationKo:`할 일이 산더미처럼 많다는 관용구는 have a lot on my plate입니다.`},{id:`d17-s07`,drillType:`chunk-build`,promptKo:`데이터 슬라이드 쪽에 조금 개선의 여지가 있어요.`,promptEnHint:`room for improvement + on the data slides를 연결하세요.`,targetEn:`There is room for improvement on the data slides.`,chunks:[`There is`,`room for improvement`,`on the`,`data slides.`],explanationKo:`직설적 비판 대신 room for improvement로 성장 가능성에 초점을 맞춥니다.`},{id:`d17-s08`,drillType:`active-blank`,promptKo:`무리하게 떠안았다가 마감을 놓치고 싶지는 않아요.`,promptEnHint:`감당 못 할 만큼 무리하게 약속하다: o_________ (10글자)`,targetEn:`I don't want to overcommit and miss the deadline.`,blankData:{before:`I don't want to`,answer:`overcommit`,after:`and miss the deadline.`,firstLetterHint:`o_________ (10글자)`},explanationKo:`overcommit은 책임감 있는 거절의 명분으로 최고의 동사입니다.`},{id:`d17-s09`,drillType:`konglish-fix`,promptKo:`"초안을 잡아주시면 제가 검토하는 선에서 타협점을 맞춰볼게요."`,promptEnHint:`"서로 한 발씩 양보해 타협하다"의 정확한 관용구를 고르세요.`,targetEn:`I can meet you halfway by reviewing your draft.`,wrongKonglishOption:`I can meet you half-road by reviewing your draft.`,explanationKo:`타협점을 찾다는 meet (someone) halfway입니다.`},{id:`d17-s10`,drillType:`chunk-build`,promptKo:`전혀 급하지 않으니 시간 나실 때 편하게 공유해 주세요.`,promptEnHint:`No rush + whenever you get a chance를 조립하세요.`,targetEn:`No rush, share it whenever you get a chance.`,chunks:[`No rush,`,`share it`,`whenever you`,`get a chance.`],explanationKo:`상대방의 부담을 낮추는 배려 표현 2종 세트입니다.`}],worksheetExam:[{id:`d17-e01`,number:1,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`업무 포화 at capacity`,questionKo:`빈칸에 전치사구(2단어)를 넣어 "목요일까지는 현재 업무량이 최대치입니다"를 완성하세요.`,stimulusEn:`I'd love to help, but I'm completely __________ __________ through Thursday.`,answer:`at capacity`,explanationKo:`업무량이 꽉 차 더 맡을 여유가 없는 상태를 at capacity라고 합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "이번 스프린트에 해야 할 일이 산더미처럼 많아요" 빈칸(3단어: o_ m_ p____)을 채우세요.`,stimulusEn:`I already have a lot __________ __________ __________ this sprint.`,answer:`on my plate`,explanationKo:`have a lot on my plate는 업무 과부하를 전하는 대표 관용구입니다.`}},{id:`d17-e02`,number:2,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`건설적 피드백 constructive / actionable`,questionKo:`빈칸에 형용사(1단어)를 넣어 "건설적인 피드백은 언제든 환영입니다"를 완성하세요.`,stimulusEn:`I'm always open to __________ feedback.`,answer:`constructive`,explanationKo:`발전을 돕는 건설적 피드백은 constructive feedback입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "바로 실행에 옮길 수 있는 구체적인 피드백이에요" 빈칸 형용사(1단어: a_________)를 쓰세요.`,stimulusEn:`Thanks—that feedback is super __________!`,answer:`actionable`,explanationKo:`구체적으로 바로 실행 가능하다는 뜻의 형용사는 actionable입니다.`}},{id:`d17-e03`,number:3,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`개선의 여지 room for improvement`,questionKo:`빈칸에 3단어를 넣어 "속도 조절 면에서 아직 개선의 여지가 있습니다"를 완성하세요.`,stimulusEn:`There is still some __________ __________ __________ in pacing.`,answer:`room for improvement`,explanationKo:`비난 대신 성장 가능성을 짚는 완곡한 피드백 표현은 room for improvement입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "개인적 공격으로 받아들이지 마세요" 빈칸 부사(1단어)를 쓰세요.`,stimulusEn:`Please don't take this __________—it's just about the layout.`,answer:`personally`,explanationKo:`take ~ personally는 감정적으로 받아들이다는 뜻입니다.`}},{id:`d17-e04`,number:4,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`타협점 찾기 meet halfway`,questionKo:`빈칸에 2단어를 넣어 "초안을 검토해 드리는 선에서 타협점을 맞춰볼 수 있어요"를 완성하세요.`,stimulusEn:`I can __________ you __________ by reviewing the outline next Monday.`,answer:`meet halfway`,explanationKo:`서로 한 발씩 양보해 타협하다는 meet [사람] halfway입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "이번 주 자료 제작은 정중히 사양해야 할 것 같아요" 빈칸 구동사(2단어)를 쓰세요.`,stimulusEn:`I'll have to __________ __________ building the extra deck this week.`,answer:`pass on`,explanationKo:`제안이나 업무를 정중히 사양하다는 pass on입니다.`}},{id:`d17-e05`,number:5,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`인력 분산 stretched thin / overcommit`,questionKo:`빈칸에 2단어를 넣어 "팀원 두 명이 휴가 중이라 우리 팀 여력이 한계에 다다랐습니다"를 완성하세요.`,stimulusEn:`With two teammates away, our team is __________ __________ this month.`,answer:`stretched thin`,explanationKo:`인력이나 시간이 너무 여러 곳에 분산되어 한계에 다다른 상태를 stretched thin이라고 합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "관계를 완전히 망치지 않으면서 거절하는 법" 빈칸(2단어: b______ b______)을 채우세요.`,stimulusEn:`It is important to say no clearly without __________ __________.`,answer:`burning bridges`,explanationKo:`전치사 without 뒤이므로 동명사 형태인 burning bridges가 정확합니다.`}},{id:`d17-e06`,number:6,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`appreciate 동사 목적어 어법`,questionKo:`다음 중 동사 appreciate의 어법이 100% 올바른 문장은?`,stimulusEn:`appreciate 뒤에 올 수 있는 형태(명사/동명사)를 확인하세요.`,options:[`I really appreciate you to give me a heads-up.`,`I really appreciate to receive your constructive feedback.`,`I really appreciate you giving me a heads-up early.`,`I appreciate that you to review my draft.`],answer:`I really appreciate you giving me a heads-up early.`,explanationKo:`appreciate는 to부정사를 목적어로 받지 않으며, 명사 또는 동명사(you giving me ~)를 취합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "미리 귀띔해 주셔서 정말 감사합니다" 빈칸(2단어)을 채우세요.`,stimulusEn:`I really appreciate __________ __________.`,answer:`the heads-up`,explanationKo:`appreciate the heads-up은 가장 빈도 높은 감사 표현입니다.`}},{id:`d17-e07`,number:7,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`Have you considered + V-ing`,questionKo:`동료의 발표 자료를 더 간결하게 바꾸도록 부드럽게 제안할 때 어법과 뉘앙스가 모두 완벽한 문장은?`,stimulusEn:`동사 consider의 목적어 형태에 주의하세요.`,options:[`Have you considered to trim the bullet points?`,`Have you considered trimming the bullet points?`,`You must trim your messy bullet points right now.`,`Did you consider that trim the bullet points?`],answer:`Have you considered trimming the bullet points?`,explanationKo:`동사 consider는 동명사(V-ing)를 목적어로 취하며, "Have you considered + V-ing?"는 최고의 완곡 피드백 공식입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "차트를 단순화해 보는 건 고려해 보셨나요?" 빈칸 동명사(1단어)를 쓰세요.`,stimulusEn:`Have you considered __________ the chart on slide four?`,answer:`simplifying`,explanationKo:`simplify의 동명사형 simplifying을 씁니다.`}},{id:`d17-e08`,number:8,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`관계 손상 없는 업무 거절`,questionKo:`업무가 꽉 찬 상태에서 타 부서의 급한 자료 요청을 정중하고 프로답게 거절하는 최고의 문장은?`,stimulusEn:`공감 + 객관적 한계 + 타협안 구조를 찾으세요.`,options:[`No, I am too busy and your request is not my job.`,`I'd love to help, but I'm at capacity this week and don't want to overcommit—I can review a draft on Monday.`,`Stop sending me extra decks because I hate overtime.`,`Maybe I will do it, even though I know I will miss the deadline.`],answer:`I'd love to help, but I'm at capacity this week and don't want to overcommit—I can review a draft on Monday.`,explanationKo:`감정적 거절이나 무리한 승낙 대신, 현재 한계(at capacity)와 품질 보호(overcommit 방지), 현실적 대안을 함께 제시합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "무리하게 약속을 떠안다"를 뜻하는 동사(1단어: o_________)를 쓰세요.`,stimulusEn:`I'd rather be transparent than __________ and deliver rushed work.`,answer:`overcommit`,explanationKo:`과도하게 업무를 떠안다는 overcommit입니다.`}},{id:`d17-e09`,number:9,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`배려 완충어 no rush / whenever`,questionKo:`바쁜 동료에게 문서 검토를 부탁하면서 "전혀 급하지 않으니 시간 나실 때 편하게 봐주세요"라고 덧붙일 때 가장 자연스러운 것은?`,stimulusEn:`상대방의 압박감을 낮추는 원어민 매너 표현을 고르세요.`,options:[`No rush at all—feel free to take a look whenever you get a chance.`,`Do not run fast—look whenever your time is empty.`,`Slowly check it when you are boring.`,`I expect your feedback ASAP with no excuse.`],answer:`No rush at all—feel free to take a look whenever you get a chance.`,explanationKo:`No rush at all과 whenever you get a chance는 미국 직장인들이 슬랙과 이메일에서 매일 쓰는 배려 표현입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "시간 나실 때 편하게" 빈칸 3단어(g__ a c_____)를 완성하세요.`,stimulusEn:`Drop your comments in the doc whenever you __________ __________ __________.`,answer:`get a chance`,explanationKo:`whenever you get a chance(3단어: get a chance)로 통째로 기억하세요.`}},{id:`d17-e10`,number:10,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`관용구 burn bridges 이해`,questionKo:`커리어 조언 중 "Make sure you decline the offer gracefully without burning bridges"가 뜻하는 바는?`,stimulusEn:`burn bridges의 비유적 의미를 파악하세요.`,options:[`회사 출근길의 교통 체증을 피해서 이동하라`,`상대방과의 향후 관계를 완전히 망치지 않도록 정중하게 제안을 거절하라`,`기존 팀원들과 모든 연락을 즉시 끊고 새로 시작하라`,`예산 절감을 위해 외부 파트너 계약을 모두 해지하라`],answer:`상대방과의 향후 관계를 완전히 망치지 않도록 정중하게 제안을 거절하라`,explanationKo:`without burning bridges는 앞으로 다시 만날 수 있는 인연·신뢰 관계를 손상시키지 않으면서 행동하라는 뜻입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "전혀 급하지 않아요!"를 뜻하는 4단어 표현(N_ r___ a_ a__!)을 쓰세요.`,stimulusEn:`Tomorrow afternoon works fine too—__________ __________ __________ __________!`,answer:`no rush at all`,explanationKo:`No rush at all!은 일상과 비즈니스 모두에서 사랑받는 배려 표현입니다.`}},{id:`d17-e11`,number:11,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`피드백 제안문 배열`,questionKo:`주어진 청크를 올바른 순서로 배열하여 부드러운 피드백 제안 문장을 완성하세요.`,stimulusEn:`[ trimming / Have you / the bullet points / on slide four? / considered ]`,answer:`Have you considered trimming the bullet points on slide four?`,explanationKo:`Have you considered + V-ing + 목적어 어순입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "발표를 고객 사례로 시작하는 방안도 고려해 보셨나요?" (Have you considered / opening the deck / with a customer story?)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`Have you considered opening the deck with a customer story?`,explanationKo:`consider + opening(동명사) 어순을 유지합니다.`}},{id:`d17-e12`,number:12,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`업무 한계 거절문 배열`,questionKo:`주어진 청크를 배열하여 프로페셔널한 업무 거절 문장을 완성하세요.`,stimulusEn:`[ this week, / I'd love to / currently at capacity / help, but I'm / so I'll have to pass. ]`,answer:`I'd love to help, but I'm currently at capacity this week, so I'll have to pass.`,explanationKo:`협업 의지 + 현재 업무 포화 상태 + 정중한 거절의 3단 연결입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "이번 주에 해야 할 일이 정말 많아요." (I have a lot / on my plate / this week.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`I have a lot on my plate this week.`,explanationKo:`have a lot on my plate + 기간 어순입니다.`}},{id:`d17-e13`,number:13,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`피드백 수용 감사 영작`,questionKo:`우리말 뜻에 맞게 주어진 단어를 활용해 자연스러운 피드백 수용 문장을 완성하세요.`,stimulusEn:`우리말: 미리 귀띔해 주셔서 정말 감사합니다—바로 실행 가능한 피드백이네요. (I really appreciate / the heads-up— / that feedback is / super actionable.)`,answer:`I really appreciate the heads-up—that feedback is super actionable.`,acceptableAlt:[`I really appreciate the heads-up — that feedback is super actionable.`,`I really appreciate the heads-up, that feedback is super actionable.`],explanationKo:`appreciate the heads-up으로 감사하고 super actionable로 피드백의 가치를 인정합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "건설적인 피드백은 언제든 환영이에요." (I’m always open to / constructive feedback.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`I'm always open to constructive feedback.`,explanationKo:`I'm always open to ~ 는 열린 태도를 보여주는 핵심 표현입니다.`}},{id:`d17-e14`,number:14,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`콩글리시 교정 서술형`,questionKo:`다음 콩글리시 문장을 올바른 동명사 어법(appreciate you giving)으로 고쳐 쓰세요.`,stimulusEn:`오류 문장: I really appreciate you to give me a heads-up early.`,answer:`I really appreciate you giving me a heads-up early.`,acceptableAlt:[`I really appreciate your giving me a heads-up early.`],explanationKo:`appreciate는 to부정사(to give)가 아니라 동명사(giving)를 취합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 오류 교정: Don’t take it to your heart. → personally를 써서 5단어로 고치세요.`,stimulusEn:`힌트: Please don't take ~.`,answer:`Please don't take it personally.`,explanationKo:`개인적으로 받아들이지 마세요는 Please don't take it personally.입니다.`}},{id:`d17-e15`,number:15,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`실전 통문장 영작`,questionKo:`다음 우리말을 영어로 자연스럽게 작성하세요.`,stimulusEn:`우리말: 다음 주 월요일에 초안을 검토해 드리는 선에서 타협점을 맞춰볼 수 있어요. (힌트: I can meet you halfway / by reviewing the draft / next Monday.)`,answer:`I can meet you halfway by reviewing the draft next Monday.`,explanationKo:`meet [사람] halfway by + V-ing은 실무 협상과 거절 모두에서 빛나는 고급 패턴입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "전혀 급하지 않으니 시간 나실 때 편하게 코멘트 남겨 주세요." (No rush at all— / drop your comments / whenever you get a chance.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`No rush at all—drop your comments whenever you get a chance.`,explanationKo:`배려 완충어를 앞뒤로 배치해 따뜻한 협업 톤을 완성합니다.`}}],tutorScenario:{openingQuestionEn:`Hey! First, loved your Q3 user research summary—one tiny thought: slide four felt a bit dense for executives. Also, could you possibly build an extra competitor analysis deck for sales by tomorrow afternoon?`,openingQuestionKo:`안녕하세요! 우선 3분기 리서치 요약 정말 좋았어요. 한 가지 작은 의견은 4번 슬라이드가 임원들이 보기에 살짝 빽빽하더라고요. 그리고 혹시 내일 오후까지 세일즈 팀용 경쟁사 분석 자료도 추가로 만들어 주실 수 있나요? (피드백은 감사히 수용하고, 추가 자료 제작은 현재 업무 포화 상태로 정중히 거절하며 타협안을 제시해 보세요!)`,followUpQuestionEn:`Totally fair—I appreciate you being upfront so you don't overcommit! Reviewing our rough outline early next week would be a huge help. No rush at all!`,followUpQuestionKo:`완전히 이해해요—무리하게 떠안지 않고 솔직히 말씀해 주셔서 감사해요! 다음 주 초에 저희 개요 초안을 검토해 주시면 정말 큰 도움이 될 거예요. 전혀 급하지 않아요!`,recommendedChunks:[`really appreciate the heads-up`,`super actionable feedback`,`currently at capacity`,`a lot on my plate`,`don't want to overcommit`,`meet you halfway by ~`],modelAnswerEn:`I really appreciate the heads-up—that feedback on slide four is super actionable, and I'll tighten it up this afternoon. As for the competitor deck, I'd love to support sales, but I'm currently at capacity with a lot on my plate this week and don't want to overcommit. I'll have to pass on building it from scratch, though I can meet you halfway by reviewing an outline early next week!`}},{dayNumber:18,weekNumber:3,cefrLevel:`b2`,isWeeklyReview:!0,dayBadge:`DAY 18 · WEEK 3 오피스 실무 종합 성취도 평가`,categoryLabel:`Week 3 총정리 리허설 & 20문항 오피스 종합평가`,title:`Week 3 실전 통합 리허설 & 3주차 오피스 종합평가`,subtitle:`Day 13~17의 화상회의·이메일·진행 보고·회의 반론·피드백 거절과 글로벌 오피스 핵심 이디엄을 1개의 실전 스토리와 20문항 종합평가로 완전 체화`,heroImage:`assets/scene_boardroom_pitch.jpg`,secondaryImage:`assets/scene_video_call.jpg`,estimatedSprintMin:10,estimatedLectureMin:50,keyExpression:`Week 3 Office Mastery: Remote Calls × Emails × Reports × Debates × Feedback`,keySentenceByTier:{a1:`I will share my screen, send the file, and finish our main task on time.`,a2:`Let me share my screen so we are on the same page about the launch schedule and budget.`,b1:`Thanks for hopping on—I've attached the deck so we can get on the same page and iron out our final bottleneck.`,b2:`I see where you're coming from on speed, but since our team is at capacity, let's get the green light on low-hanging fruit first and circle back with a ballpark figure by EOD.`,c1:`At the end of the day, cutting corners won't move the needle; let's table the side scope that's off the table, iron out the QA blocker, and align on clear deliverables before we wrap up.`,c2:`Having shared the revised roadmap ahead of this sync to ensure full cross-functional alignment, I'd recommend we fast-track high-leverage fixes that genuinely move the needle rather than overcommitting our bandwidth on peripheral scope.`},youtubeVideo:e[18],readingPassage:{titleEn:`One High-Stakes Friday at a Global Tech Team`,titleKo:`[3주차 종합 케이스] 글로벌 테크 팀의 금요일 론칭 최종 점검 브리핑`,genreBadge:`주간 통합 케이스 브리프 · Lv.4`,estimatedMin:6,paragraphsEn:[`At 9:00 AM sharp, Jiwon kicked off the Seoul–San Francisco launch readiness sync. After thanking everyone for hopping on and confirming that nobody was on mute, she shared her screen to get the ball rolling. When Liam briefly started breaking up on Wi-Fi, she stayed calm, asked him to switch off video, and walked the cross-functional team through the attached status memo so everyone was on the same page.`,`Halfway through the call, the discussion turned to a payment API bottleneck that threatened Monday's deadline. Finance asked for a ballpark figure on potential overtime costs, while Sales suggested skipping a round of QA tests to keep the date. Jiwon validated Sales's urgency—saying she saw where they were coming from—but firmly noted that cutting corners was off the table because, at the end of the day, checkout reliability is what truly moves the needle for customer trust.`,`Instead of overcommitting a team that was already at capacity, Jiwon proposed thinking outside the box: fast-tracking the low-hanging fruit fixes while putting the loyalty-points redesign on the back burner. Her director gave the plan an immediate green light. Within ten minutes, they ironed out the remaining action items, agreed to circle back by EOD with final sign-off, and wrapped up right on schedule.`],paragraphsSlash:[`At 9:00 AM sharp, / Jiwon kicked off the Seoul–San Francisco launch readiness sync. / After thanking everyone for hopping on / and confirming that nobody was on mute, / she shared her screen to get the ball rolling. / When Liam briefly started breaking up on Wi-Fi, / she stayed calm, / asked him to switch off video, / and walked the cross-functional team / through the attached status memo / so everyone was on the same page.`,`Halfway through the call, / the discussion turned to a payment API bottleneck / that threatened Monday's deadline. / Finance asked for a ballpark figure / on potential overtime costs, / while Sales suggested skipping a round of QA tests / to keep the date. / Jiwon validated Sales's urgency— / saying she saw where they were coming from— / but firmly noted that cutting corners was off the table / because, at the end of the day, / checkout reliability is what truly moves the needle / for customer trust.`,`Instead of overcommitting a team / that was already at capacity, / Jiwon proposed thinking outside the box: / fast-tracking the low-hanging fruit fixes / while putting the loyalty-points redesign on the back burner. / Her director gave the plan an immediate green light. / Within ten minutes, / they ironed out the remaining action items, / agreed to circle back by EOD with final sign-off, / and wrapped up right on schedule.`],paragraphsKo:[`오전 9시 정각, 지원은 서울과 샌프란시스코를 잇는 론칭 최종 점검 회의를 시작했습니다. 참석해 준 모두에게 감사 인사를 건네고 아무도 음소거 상태가 아님을 확인한 뒤, 본격적인 논의를 시작하기 위해 화면을 공유했습니다. 리암의 와이파이 연결이 잠시 끊기기 시작하자 침착하게 카메라를 꺼달라고 요청했고, 모든 부서가 같은 이해를 공유할 수 있도록 첨부한 현황 보고서를 단계별로 차근차근 설명했습니다.`,`회의 중반, 논의는 월요일 마감일을 위협하는 결제 API 병목 구간으로 넘어갔습니다. 재무팀은 예상 초과근무 비용의 대략적인 추정치를 요청했고, 세일즈 팀은 출시일을 지키기 위해 QA 테스트를 한 차례 건너뛰자고 제안했습니다. 지원은 세일즈 팀의 긴박함에 충분히 공감한다고 인정하면서도, 결국 고객 신뢰에 실질적인 변화를 만드는 것은 결제 안정성이므로 품질을 대충 타협하는 편법은 결코 고려 대상이 될 수 없다고 단호히 선을 그었습니다.`,`이미 업무량이 최대치에 달한 팀에 무리한 약속을 떠안기는 대신, 지원은 틀에서 벗어난 해결책을 제안했습니다. 빠르게 성과를 낼 수 있는 쉬운 수정 과제들을 패스트트랙으로 신속 처리하되 포인트 개편은 후순위로 미뤄두는 것이었습니다. 디렉터는 그 계획에 즉시 최종 진행 승인을 내렸습니다. 10분 만에 남은 실행 과제들을 매끄럽게 조율하고 오늘 업무 마감 전까지 최종 승인으로 회신하기로 합의한 뒤, 정각에 맞춰 회의를 완벽하게 마무리했습니다.`],keyExpressions:[`on the same page`,`ballpark figure`,`cut corners / off the table`,`at the end of the day / move the needle`,`low-hanging fruit / green light`,`iron out`],comprehensionQuiz:[{id:`d18-rq01`,questionKo:`세일즈 팀이 제안한 "QA 테스트 생략"을 지원이 단호히 배제(off the table)한 핵심 이유는 무엇인가요?`,options:[`재무팀이 초과근무 예산을 전액 삭감했기 때문에`,`결국 고객 신뢰에 실질적 성과(move the needle)를 만드는 것은 결제 안정성이기 때문에`,`리암의 화상회의 연결이 완전히 끊겼기 때문에`,`디렉터가 출시 자체를 다음 분기로 연기했기 때문에`],answer:`결국 고객 신뢰에 실질적 성과(move the needle)를 만드는 것은 결제 안정성이기 때문에`,explanationKo:`둘째 문단 "cutting corners was off the table because, at the end of the day, checkout reliability is what truly moves the needle for customer trust"가 정확한 근거입니다.`},{id:`d18-rq02`,questionKo:`지원이 업무 포화(at capacity) 상태의 팀을 보호하면서 디렉터의 승인(green light)을 이끌어낸 해결책은?`,options:[`쉬운 고효율 수정 과제(low-hanging fruit)를 신속 처리하고 포인트 개편은 후순위로 미뤘다`,`모든 팀원에게 주말 야근을 강제 배정했다`,`외부 에이전시에 결제 시스템 전체를 넘겼다`,`월요일 출시를 아무 대안 없이 한 달 연기했다`],answer:`쉬운 고효율 수정 과제(low-hanging fruit)를 신속 처리하고 포인트 개편은 후순위로 미뤘다`,explanationKo:`셋째 문단 "fast-tracking the low-hanging fruit fixes while putting the loyalty-points redesign on the back burner"를 확인하세요.`},{id:`d18-rq03`,questionKo:`본문에서 재무팀이 초과근무 비용에 대해 요청한 "대략적인 추정치"를 뜻하는 오피스 이디엄은?`,options:[`a green light`,`a ballpark figure`,`low-hanging fruit`,`the bottom line`],answer:`a ballpark figure`,explanationKo:`ballpark figure는 정확한 계산 전 어림잡은 대략적인 수치를 뜻하는 미국 비즈니스 필수 이디엄입니다.`}]},vocabList:[{id:`d18-v01`,word:`on the same page`,phonetic:`/ɑːn ðə seɪm peɪdʒ/`,pos:`관용구`,cefr:`b2`,meaningKo:`같은 이해·방향을 공유하고 있는`,meaningEn:`having a shared understanding or agreement about a plan`,nuanceTipKo:`회의 시작과 끝에 "Let's make sure we're all on the same page(모두 같은 그림을 보고 있는지 확인하죠)"를 쓰면 싱크의 격이 달라집니다.`,exampleEn:`Before we wrap up, let's recap our deadlines so everyone is on the same page.`,exampleKo:`마무리하기 전에 모두가 같은 방향을 공유하도록 마감일을 한 번 정리하죠.`},{id:`d18-v02`,word:`ballpark figure`,phonetic:`/ˈbɔːlpɑːrk ˈfɪɡjər/`,pos:`명사구`,cefr:`b2`,meaningKo:`대략적인 추정치, 어림잡은 숫자`,meaningEn:`a rough numerical estimate rather than an exact calculation`,nuanceTipKo:`야구장(ballpark) 안에 공이 떨어질 대략의 범위에서 나온 표현! 견적·예산·일정 추정을 가볍게 물을 때 "Could you give me a ballpark figure?"라고 씁니다.`,exampleEn:`I don't need the exact quote yet—just a ballpark figure for the Q4 campaign.`,exampleKo:`정확한 견적까지는 아직 필요 없고, 4분기 캠페인의 대략적인 추정치만 알려주세요.`},{id:`d18-v03`,word:`get the green light`,phonetic:`/ɡet ðə ɡriːn laɪt/`,pos:`관용구`,cefr:`b2`,meaningKo:`(프로젝트·예산의) 최종 진행 승인을 받다`,meaningEn:`receive official permission to proceed with a project or plan`,nuanceTipKo:`신호등 초록불처럼 Go 사인을 받는 이미지! 승인해 주다는 "give ~ the green light"로 씁니다.`,exampleEn:`Once we get the green light from finance, we can kick off hiring immediately.`,exampleKo:`재무팀에서 최종 진행 승인을 받으면 바로 채용을 시작할 수 있습니다.`},{id:`d18-v04`,word:`move the needle`,phonetic:`/muːv ðə ˈniːdl/`,pos:`관용구`,cefr:`c1`,meaningKo:`눈에 띄는 실질적인 변화·성과를 만들어 내다`,meaningEn:`make a noticeable, measurable impact on key results`,nuanceTipKo:`계기판 바늘(needle)이 실제로 확 움직이는 모습! 우선순위를 따질 때 "Will this actually move the needle?"은 실리콘밸리 임원들의 최애 질문입니다.`,exampleEn:`Let’s focus our limited bandwidth on features that actually move the needle on retention.`,exampleKo:`제한된 여력을 고객 유지율에 실질적인 변화를 만드는 기능에 집중합시다.`},{id:`d18-v05`,word:`think outside the box`,phonetic:`/θɪŋk ˌaʊtˈsaɪd ðə bɑːks/`,pos:`관용구`,cefr:`b2`,meaningKo:`고정관념에서 벗어나 창의적으로 생각하다`,meaningEn:`approach a problem creatively from an unconventional perspective`,nuanceTipKo:`예산이나 인력이 빠듯한 병목 상황에서 새로운 돌파구를 찾을 때 브레인스토밍에서 자주 쓰입니다.`,exampleEn:`With a flat marketing budget, we need to think outside the box for Q4 growth.`,exampleKo:`마케팅 예산이 동결된 만큼 4분기 성장을 위해 고정관념을 깬 아이디어가 필요합니다.`},{id:`d18-v06`,word:`off the table`,phonetic:`/ɔːf ðə ˈteɪbl/`,pos:`전치사구`,cefr:`b2`,meaningKo:`(협상·논의에서) 더 이상 고려 대상이 아닌, 제외된`,meaningEn:`no longer available as an option or open for negotiation`,nuanceTipKo:`반대말은 on the table(고려 중인/협상 테이블 위의). 절대 양보할 수 없는 원칙을 밝힐 때 "Cutting QA is off the table"처럼 씁니다.`,exampleEn:`Skipping security checks is completely off the table, even with a tight deadline.`,exampleKo:`마감이 빠듯하더라도 보안 점검을 생략하는 건 전혀 고려 대상이 아닙니다.`},{id:`d18-v07`,word:`at the end of the day`,phonetic:`/æt ði end əv ðə deɪ/`,pos:`관용구`,cefr:`b2`,meaningKo:`결국에 가서는, 본질적으로 가장 중요한 것은`,meaningEn:`ultimately, when considering what matters most overall`,nuanceTipKo:`긴 회의 토론을 핵심 본질로 수렴시킬 때 쓰는 최고의 정리 연결어! (주의: "오늘 퇴근 전까지"는 by EOD이고, "결국/본질적으로"가 at the end of the day입니다!)`,exampleEn:`At the end of the day, customer trust matters far more than shipping two days early.`,exampleKo:`결국 가장 중요한 것은 이틀 빨리 출시하는 것보다 고객의 신뢰입니다.`},{id:`d18-v08`,word:`low-hanging fruit`,phonetic:`/ˌloʊ ˈhæŋɪŋ fruːt/`,pos:`명사구`,cefr:`c1`,meaningKo:`적은 노력으로 빠르게 성과를 낼 수 있는 쉬운 과제`,meaningEn:`easily achievable tasks that deliver quick, high-value wins`,nuanceTipKo:`손만 뻗으면 바로 딸 수 있는 낮은 가지의 열매 비유! 리소스가 부족할 때 빠른 성과(quick wins)를 먼저 챙기자고 제안할 때 최고입니다.`,exampleEn:`Let's tackle the low-hanging fruit this week to build momentum before the big launch.`,exampleKo:`대규모 출시 전에 추진력을 얻도록 이번 주엔 빠르게 성과를 낼 수 있는 쉬운 과제부터 처리하죠.`},{id:`d18-v09`,word:`get the ball rolling`,phonetic:`/ɡet ðə bɔːl ˈroʊlɪŋ/`,pos:`관용구`,cefr:`b2`,meaningKo:`(프로젝트·회의를) 본격적으로 시작하다, 물꼬를 트다`,meaningEn:`initiate a process, discussion, or project so momentum starts`,nuanceTipKo:`회의 오프닝이나 새 프로젝트 킥오프에서 "Let's get the ball rolling!"이라고 외치면 에너지가 확 살아납니다.`,exampleEn:`I'll send out the kickoff agenda today to get the ball rolling on Q4 planning.`,exampleKo:`4분기 기획의 물꼬를 트기 위해 오늘 킥오프 아젠다를 발송하겠습니다.`},{id:`d18-v10`,word:`alignment`,phonetic:`/əˈlaɪnmənt/`,pos:`명사`,cefr:`b2`,meaningKo:`(팀·부서 간 목표·방향의) 정렬, 의견 일치`,meaningEn:`shared agreement on goals, priorities, and next steps across teams`,nuanceTipKo:`동사 align과 함께 "get alignment across teams(부서 간 방향을 맞추다)"는 글로벌 기업 임원 보고 단골 어휘입니다.`,exampleEn:`We need clear alignment between product and sales before announcing the new tiers.`,exampleKo:`새 요금제를 발표하기 전에 프로덕트 팀과 세일즈 팀 간의 명확한 방향 정렬이 필요합니다.`},{id:`d18-v11`,word:`bottom line`,phonetic:`/ˈbɑːtəm laɪn/`,pos:`명사구`,cefr:`b2`,meaningKo:`핵심 요점, 결론 (재무상으로는 최종 순이익)`,meaningEn:`the most fundamental point or final financial net profit`,nuanceTipKo:`장황한 설명을 한 줄로 압축할 때 "The bottom line is that ~"으로 시작하면 임원 보고의 설득력이 폭발합니다.`,exampleEn:`The bottom line is that we can't launch reliably without completing payment QA.`,exampleKo:`결론은 결제 QA를 완료하지 않고서는 안정적으로 출시할 수 없다는 것입니다.`},{id:`d18-v12`,word:`fast-track`,phonetic:`/ˈfæst træk/`,pos:`동사/명사`,cefr:`c1`,meaningKo:`(중요 과제를) 패스트트랙으로 신속 처리하다`,meaningEn:`accelerate the progress of a high-priority task or approval`,nuanceTipKo:`급한 승인이나 핵심 버그 수정을 우선 트랙으로 당겨 처리할 때 "fast-track the approval"처럼 동사로 씁니다.`,exampleEn:`Legal agreed to fast-track the vendor agreement so we stay on track.`,exampleKo:`일정을 지킬 수 있도록 법무팀이 벤더 계약서 검토를 신속 처리해 주기로 했습니다.`},{id:`d18-v13`,word:`iron out`,phonetic:`/ˈaɪərn aʊt/`,pos:`구동사`,cefr:`b2`,meaningKo:`(구겨진 옷을 다리듯) 세부 문제·이견을 매끄럽게 조율해 해결하다`,meaningEn:`resolve minor remaining details, bugs, or disagreements smoothly`,nuanceTipKo:`큰 틀은 합의되었고 자잘한 세부 사항만 다듬으면 될 때 "iron out the remaining details"가 완벽한 원어민 구동사입니다.`,exampleEn:`We just need a 15-minute sync to iron out the last few details before launch.`,exampleKo:`출시 전에 남은 자잘한 세부 사항 몇 가지만 조율하려면 15분 싱크만 있으면 됩니다.`},{id:`d18-v14`,word:`wrap one's head around`,phonetic:`/ræp wʌnz hed əˈraʊnd/`,pos:`관용구`,cefr:`c1`,meaningKo:`(복잡한 개념·상황을) 제대로 이해하고 소화하다`,meaningEn:`fully understand or come to terms with a complex idea or change`,nuanceTipKo:`복잡한 리포트나 갑작스러운 스펙 변경을 소화할 시간이 필요할 때 "Give me a moment to wrap my head around these numbers"라고 씁니다.`,exampleEn:`Let me spend an hour wrapping my head around the revised forecast before I circle back.`,exampleKo:`회신드리기 전에 수정된 예측치를 제대로 소화할 시간 한 시간만 주세요.`},{id:`d18-v15`,word:`cut corners`,phonetic:`/kʌt ˈkɔːrnərz/`,pos:`관용구`,cefr:`b2`,meaningKo:`(시간·비용을 아끼려고) 절차를 생략하다, 편법을 쓰다`,meaningEn:`do something hastily or cheaply at the expense of quality or safety`,nuanceTipKo:`코너를 제대로 돌지 않고 가로질러 대충 넘기는 모습! 품질 타협을 거부할 때 "We refuse to cut corners on security"처럼 씁니다.`,exampleEn:`We'd rather push the deadline back two days than cut corners on quality.`,exampleKo:`품질을 대충 타협하느니 차라리 마감일을 이틀 미루겠습니다.`}],dialogue:[{id:`d18-t01`,speaker:`Jiwon`,roleLabel:`프로덕트 매니저 · 서울`,voicePitch:1.06,sceneImage:`assets/scene_video_call.jpg`,cameraMotion:`zoom-in`,english:`Thanks for hopping on, everyone! Let me share my screen to get the ball rolling—can everyone see the attached launch brief?`,slashBroken:`Thanks for hopping on, everyone! / Let me share my screen / to get the ball rolling— / can everyone see / the attached launch brief?`,korean:`모두 접속해 주셔서 감사합니다! 본격적으로 시작하기 위해 화면 공유할게요—첨부해 드린 론칭 브리프 다들 잘 보이시나요?`,keyHighlight:`share my screen to get the ball rolling`,noteKo:`Day 13(화상회의 오프닝·화면 공유) + Day 14(attached) + Day 18(get the ball rolling)을 한 문장에 자연스럽게 결합했습니다.`},{id:`d18-t02`,speaker:`Liam`,roleLabel:`엔지니어링 리드 · 샌프란시스코`,voicePitch:.91,sceneImage:`assets/scene_boardroom_pitch.jpg`,cameraMotion:`pan-right`,english:`Loud and clear! Quick status update: front-end is ahead of schedule, but we hit a bottleneck in payment QA and may need to push back launch by 48 hours.`,slashBroken:`Loud and clear! / Quick status update: / front-end is ahead of schedule, / but we hit a bottleneck in payment QA / and may need to push back launch / by 48 hours.`,korean:`선명하게 잘 보이고 들려요! 간단히 현황 보고드리면, 프론트엔드는 일정보다 앞서 있지만 결제 QA에서 병목이 생겨 출시를 48시간 미뤄야 할 수도 있습니다.`,keyHighlight:`hit a bottleneck in payment QA`,noteKo:`Day 15의 3단 리스크 보고 공식(ahead of schedule → hit a bottleneck → push back by 48 hours) 복습입니다.`},{id:`d18-t03`,speaker:`Rachel`,roleLabel:`프로덕트 디렉터`,voicePitch:1.03,sceneImage:`assets/scene_boardroom_pitch.jpg`,cameraMotion:`pan-left`,english:`Appreciate the heads-up, Liam. Before we decide, can you give me a ballpark figure on the risk if we trim one QA cycle to hold Monday's date?`,slashBroken:`Appreciate the heads-up, Liam. / Before we decide, / can you give me a ballpark figure on the risk / if we trim one QA cycle / to hold Monday's date?`,korean:`미리 알려줘서 고마워요, 리암. 결정하기 전에, 월요일 일정을 지키려고 QA 사이클을 하나 줄이면 리스크가 대략 어느 정도일지 어림잡아 말씀해 주실 수 있나요?`,keyHighlight:`give me a ballpark figure`,noteKo:`Day 17(appreciate the heads-up)과 Day 18 핵심 이디엄(ballpark figure)이 자연스럽게 이어집니다.`},{id:`d18-t04`,speaker:`Jiwon`,roleLabel:`프로덕트 매니저 · 서울`,voicePitch:1.06,sceneImage:`assets/scene_video_call.jpg`,cameraMotion:`zoom-in`,english:`May I jump in here? I totally see where you're coming from on keeping momentum, Rachel, but cutting corners on payment QA has to be off the table.`,slashBroken:`May I jump in here? / I totally see where you're coming from / on keeping momentum, Rachel, / but cutting corners on payment QA / has to be off the table.`,korean:`잠깐 끼어들어도 될까요? 추진력을 유지하려는 취지는 충분히 이해하지만 레이첼, 결제 QA에서 편법을 쓰는 건 결코 고려 대상이 될 수 없습니다.`,keyHighlight:`cutting corners on payment QA has to be off the table`,noteKo:`Day 16의 정중한 끼어들기·공감 반론(jump in / see where you're coming from)과 Day 18 이디엄(cut corners / off the table)의 완벽한 조화입니다.`},{id:`d18-t05`,speaker:`Jiwon`,roleLabel:`프로덕트 매니저 · 서울`,voicePitch:1.06,sceneImage:`assets/scene_boardroom_pitch.jpg`,cameraMotion:`pan-right`,english:`At the end of the day, checkout reliability is what really moves the needle. Since our team is at capacity, what if we fast-track the low-hanging fruit fixes and put the loyalty redesign on the back burner?`,slashBroken:`At the end of the day, / checkout reliability is what really moves the needle. / Since our team is at capacity, / what if we fast-track the low-hanging fruit fixes / and put the loyalty redesign on the back burner?`,korean:`결국 실질적 성과를 만드는 건 결제 안정성입니다. 팀 여력이 최대치인 만큼, 빠르게 성과가 나는 핵심 수정만 패스트트랙 처리하고 포인트 개편은 후순위로 미루면 어떨까요?`,keyHighlight:`what really moves the needle`,noteKo:`at the end of the day(본질) + move the needle(실질 성과) + at capacity(Day 17) + back burner(Day 15)가 한 번에 녹아든 시니어 설득 화법입니다.`},{id:`d18-t06`,speaker:`Rachel`,roleLabel:`프로덕트 디렉터`,voicePitch:1.03,sceneImage:`assets/scene_boardroom_pitch.jpg`,cameraMotion:`pan-left`,english:`That's spot on—you have my green light! Let's iron out the revised action items right now so product, finance, and sales stay in full alignment.`,slashBroken:`That's spot on— / you have my green light! / Let's iron out the revised action items right now / so product, finance, and sales / stay in full alignment.`,korean:`정확히 핵심을 찔렀네요—최종 승인합니다! 프로덕트, 재무, 세일즈 팀이 완벽하게 방향을 맞추도록 지금 바로 수정된 실행 과제를 조율하죠.`,keyHighlight:`you have my green light`,noteKo:`spot on(Day 16) + green light + iron out + alignment로 실행 결정을 확정합니다.`},{id:`d18-t07`,speaker:`Liam`,roleLabel:`엔지니어링 리드 · 샌프란시스코`,voicePitch:.91,sceneImage:`assets/scene_video_call.jpg`,cameraMotion:`zoom-in`,english:`Sounds like we're all on the same page! I'll take ownership of the QA tracker and circle back by EOD—let's wrap up two minutes early.`,slashBroken:`Sounds like we're all on the same page! / I'll take ownership of the QA tracker / and circle back by EOD— / let's wrap up two minutes early.`,korean:`모두 같은 이해를 공유한 것 같네요! QA 트래커는 제가 주도적으로 맡아서 오늘 마감 전까지 회신드리겠습니다. 2분 일찍 마무리하시죠.`,keyHighlight:`we're all on the same page`,noteKo:`on the same page(합의 확인) + take ownership of(Day 15) + circle back by EOD(Day 14/15) + wrap up(Day 13)으로 Week 3 전체를 완벽하게 닫습니다.`}],grammarSections:[{title:`원리 01 · Week 3 오피스 5대 상황별 핵심 동사·표현 전환 매트릭스`,coreFormula:`화상(hop on/break up) · 이메일(attach/circle back) · 보고(on track/bottleneck) · 회의(build on/reservations) · 거절(at capacity/meet halfway)`,wrongKonglish:`You are mute! Please reply my attach ASAP because our work is delayed and I disagree you.`,rightNative:`Sorry, you're on mute! Per our call, I've attached the update—we hit a QA bottleneck, and while I see where you're coming from, cutting corners is off the table.`,explanationKo:`3주차에 배운 5개 직무 상황은 실무에서 따로 떨어져 나오지 않고 하나의 프로젝트 안에서 연속으로 이어집니다. 화상회의에서 화면을 공유하고(Day 13), 회의 후 첨부 이메일로 팔로업하며(Day 14), 병목과 우선순위를 보고하고(Day 15), 이견을 완곡히 조율하고(Day 16), 과부하 업무는 타협점으로 방어하는(Day 17) 전체 흐름을 한 덩어리로 연결해 발화하세요.`,registerSpectrum:{casual:`Quick sync recap—we're on the same page, skipping QA is off the table, and I'll circle back by EOD!`,standard:`Thanks for hopping on—I've attached the revised action items so we stay on the same page, and I'll circle back by EOD.`,formal:`Following our alignment session, please find the finalized deliverables attached; we have received the green light to fast-track core fixes while keeping quality standards intact.`}},{title:`원리 02 · 오피스 핵심 이디엄의 그림 해석법: 의미 혼동 주의 쌍 비교`,coreFormula:`at the end of the day (결국/본질적으로) ≠ by EOD (오늘 퇴근 전까지) | pushback (반발) ≠ push back (미루다)`,wrongKonglish:`I'll send the ballpark figure at the end of the day (= 6 PM today).`,rightNative:`I'll send a ballpark figure by EOD today—at the end of the day, accuracy matters most.`,explanationKo:`한국 학습자들이 3주차에서 가장 많이 헷갈리는 두 쌍입니다! ① "오늘 업무 마감 전까지"는 반드시 by EOD(end of day)이며, at the end of the day는 시간 표현이 아니라 "결국에 가서는/본질적으로"라는 뜻의 이디엄입니다. ② 띄어 쓴 구동사 push back은 "일정을 미루다", 붙여 쓴 명사 pushback은 "반발·이견"을 뜻합니다.`,registerSpectrum:{casual:`I'll ping you a ballpark number by EOD—at the end of the day, we just need to move the needle.`,standard:`I'll share a ballpark figure by EOD today; at the end of the day, customer trust is what moves the needle.`,formal:`We will submit preliminary estimates by end of business today; ultimately, long-term reliability remains our primary bottom line.`}},{title:`원리 03 · 3주차 최다 오답 콩글리시 TOP 4 최종 방어 체크리스트`,coreFormula:`① on mute (X: are mute) ② appreciate + V-ing/명사 (X: to V) ③ by EOD (X: until EOD) ④ walk [사람] through [자료] (X: explain [사람] [자료])`,wrongKonglish:`I appreciate you to explain me the file until EOD while I am mute.`,rightNative:`I really appreciate you walking me through the deck by EOD—oops, I was on mute!`,explanationKo:`실제 글로벌 오피스에서 한국인의 영어 신뢰도를 가장 크게 깎는 4가지 어법 함정입니다. ① 마이크 상태는 전치사 on(on mute), ② appreciate와 consider 뒤에는 반드시 동명사(V-ing), ③ 완료 마감 시점은 until이 아닌 by(by EOD), ④ 사람을 바로 목적어로 쓸 때는 explain 대신 walk [사람] through [자료]를 쓰는 원칙을 완벽히 체화하세요.`,registerSpectrum:{casual:`Thanks for walking me through the deck by EOD—appreciate you jumping in!`,standard:`I really appreciate you walking us through the revised slides and sharing the notes by EOD.`,formal:`We sincerely appreciate your walking the leadership team through the updated roadmap prior to end of business.`}}],sprintDrills:[{id:`d18-s01`,drillType:`chunk-build`,promptKo:`모두가 같은 방향을 공유하고 있는지 마무리 전에 확인하죠.`,promptEnHint:`make sure + on the same page 조합을 만드세요.`,targetEn:`Let's make sure we're all on the same page.`,chunks:[`Let's make sure`,`we're all`,`on the`,`same page.`],explanationKo:`회의 오프닝·마무리에서 합의를 점검하는 대표 오피스 이디엄입니다.`},{id:`d18-s02`,drillType:`konglish-fix`,promptKo:`"오늘 퇴근 전까지 대략적인 추정치를 공유드리겠습니다."`,promptEnHint:`"오늘 퇴근 전까지(by EOD)"와 "결국(at the end of the day)"을 구분하세요!`,targetEn:`I'll share a ballpark figure by EOD today.`,wrongKonglishOption:`I'll share a ballpark figure at the end of the day today.`,explanationKo:`시간 마감 기한은 by EOD이며, at the end of the day는 "결국/본질적으로"라는 뜻입니다.`},{id:`d18-s03`,drillType:`active-blank`,promptKo:`결제 QA에서 편법을 쓰는 것은 전혀 고려 대상이 아닙니다.`,promptEnHint:`고려 대상에서 제외된: ___ the table (3글자)`,targetEn:`Cutting corners on QA is off the table.`,blankData:{before:`Cutting corners on QA is`,answer:`off`,after:`the table.`,firstLetterHint:`o__ (3글자)`},explanationKo:`협상·논의에서 완전히 배제된 선택지를 off the table이라고 합니다.`},{id:`d18-s04`,drillType:`chunk-build`,promptKo:`결국 고객 유지율에 실질적인 변화를 만드는 기능에 집중해야 합니다.`,promptEnHint:`At the end of the day + move the needle을 연결하세요.`,targetEn:`At the end of the day, this will move the needle.`,chunks:[`At the end`,`of the day,`,`this will`,`move the needle.`],explanationKo:`at the end of the day(본질)와 move the needle(실질 성과)의 조합입니다.`},{id:`d18-s05`,drillType:`active-blank`,promptKo:`재무팀에서 최종 진행 승인을 받으면 바로 시작할 수 있습니다.`,promptEnHint:`최종 진행 승인: get the _____ light (5글자)`,targetEn:`Once we get the green light, we can launch.`,blankData:{before:`Once we get the`,answer:`green`,after:`light, we can launch.`,firstLetterHint:`g____ (5글자)`},explanationKo:`프로젝트 최종 진행 허가를 get the green light라고 표현합니다.`},{id:`d18-s06`,drillType:`konglish-fix`,promptKo:`"죄송해요, 목소리가 끊기고 아직 음소거 상태이신 것 같아요."`,promptEnHint:`Day 13 핵심 표현: on mute와 breaking up을 확인하세요.`,targetEn:`Sorry, you're breaking up and were just on mute.`,wrongKonglishOption:`Sorry, you're cutting and were just mute.`,explanationKo:`음성 끊김은 breaking up, 마이크 꺼짐 상태는 반드시 on mute입니다.`},{id:`d18-s07`,drillType:`chunk-build`,promptKo:`출시 전에 남은 세부 사항 몇 가지만 매끄럽게 조율하죠.`,promptEnHint:`iron out + the remaining details 청크를 조립하세요.`,targetEn:`Let's iron out the remaining details before launch.`,chunks:[`Let's`,`iron out`,`the remaining details`,`before launch.`],explanationKo:`세부적인 문제나 이견을 매끄럽게 다듬어 해결하다는 iron out입니다.`},{id:`d18-s08`,drillType:`active-blank`,promptKo:`빠르게 성과를 낼 수 있는 쉬운 과제들부터 패스트트랙 처리합시다.`,promptEnHint:`손쉽게 성과를 내는 과제: low-hanging _____ (5글자)`,targetEn:`Let's fast-track the low-hanging fruit first.`,blankData:{before:`Let's fast-track the low-hanging`,answer:`fruit`,after:`first.`,firstLetterHint:`f____ (5글자)`},explanationKo:`적은 노력으로 즉각적 성과를 얻는 과제를 low-hanging fruit이라고 부릅니다.`},{id:`d18-s09`,drillType:`konglish-fix`,promptKo:`"일찍 귀띔해 주셔서 정말 감사해요—다만 이번 주는 업무량이 꽉 찼습니다."`,promptEnHint:`Day 17 핵심: appreciate + 동명사/명사 & at capacity를 확인하세요.`,targetEn:`I really appreciate the heads-up, though I'm at capacity this week.`,wrongKonglishOption:`I really appreciate to tell me early, though I'm full busy this week.`,explanationKo:`appreciate the heads-up과 at capacity로 정중하고 객관적인 경계를 표현합니다.`},{id:`d18-s10`,drillType:`chunk-build`,promptKo:`본격적으로 논의를 시작하기 위해 제 화면을 공유할게요.`,promptEnHint:`share my screen + to get the ball rolling을 연결하세요.`,targetEn:`Let me share my screen to get the ball rolling.`,chunks:[`Let me`,`share my screen`,`to get`,`the ball rolling.`],explanationKo:`회의 시작의 물꼬를 틀 때 get the ball rolling이 탁월합니다.`}],worksheetExam:[{id:`d18-e01`,number:1,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`Day 13 복습 · 화상회의 연결`,questionKo:`빈칸에 구동사(2단어, 진행형)를 넣어 "리암, 와이파이 때문에 목소리가 좀 끊기고 있어요"를 완성하세요.`,stimulusEn:`Liam, you're __________ __________ a bit on Wi-Fi—could you turn off video?`,answer:`breaking up`,explanationKo:`신호 불안정으로 음성이 뚝뚝 끊길 때는 진행형 breaking up을 씁니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "잠시만 기다려 주세요, 슬라이드를 띄울게요" 빈칸(3단어)을 채우세요.`,stimulusEn:`__________ __________ __________ for a second while I share my screen.`,answer:`Bear with me`,explanationKo:`기술 준비 중 정중한 대기 요청은 Bear with me입니다.`}},{id:`d18-e02`,number:2,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`Day 14 복습 · 이메일 팔로업`,questionKo:`빈칸에 구동사(2단어)를 넣어 "법무팀 확인 후 오늘 마감 전까지 다시 회신드리겠습니다"를 완성하세요.`,stimulusEn:`I'll confirm with legal and __________ __________ to you by EOD.`,answer:`circle back`,acceptableAlt:[`get back`],explanationKo:`확인 후 재회신 약속은 circle back(또는 get back)입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "어제 나눈 대화에 따라 최종 브리프를 첨부해 드립니다" 빈칸 과거분사(1단어)를 쓰세요.`,stimulusEn:`Per our conversation, please find the launch brief __________.`,answer:`attached`,explanationKo:`Please find [문서] attached가 격식 첨부 공식입니다.`}},{id:`d18-e03`,number:3,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`Day 15 복습 · 병목 & 마감 보고`,questionKo:`빈칸에 명사(1단어)를 넣어 "결제 QA 단계에서 병목 현상에 부딪혔습니다"를 완성하세요.`,stimulusEn:`We hit an unexpected __________ in payment QA this morning.`,answer:`bottleneck`,acceptableAlt:[`blocker`],explanationKo:`업무 흐름을 정체시키는 병목 구간은 bottleneck(장애 요인은 blocker)입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "마감일을 48시간 뒤로 미뤄야 할 수도 있어요" 빈칸 구동사(2단어)를 채우세요.`,stimulusEn:`We may need to __________ __________ the deadline by 48 hours.`,answer:`push back`,explanationKo:`마감일 연기는 push back the deadline입니다.`}},{id:`d18-e04`,number:4,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`Day 16 복습 · 회의 반론 쿠션`,questionKo:`빈칸에 2단어를 넣어 "추진력을 지키려는 취지는 충분히 이해하지만, 우려가 있습니다"를 완성하세요.`,stimulusEn:`I totally see where you're __________ __________, though I have a few reservations.`,answer:`coming from`,explanationKo:`I see where you're coming from은 반론 전 최고의 공감 표현입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "앞사람 의견에 한 가지 덧붙이자면..." 빈칸 구동사(2단어)를 쓰세요.`,stimulusEn:`To __________ __________ Rachel's point, we should check retention data too.`,answer:`build on`,explanationKo:`앞사람의 논리에 살을 붙여 발전시킬 때 build on을 씁니다.`}},{id:`d18-e05`,number:5,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`Day 17 복습 · 업무 포화 & 타협`,questionKo:`빈칸에 전치사구(2단어)를 넣어 "이번 주엔 업무량이 최대치라 추가 자료 제작은 어렵습니다"를 완성하세요.`,stimulusEn:`I'd love to help, but our team is completely __________ __________ this week.`,answer:`at capacity`,explanationKo:`업무량이 꽉 찬 객관적 한계 상태는 at capacity입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "초안을 검토해 드리는 선에서 타협점을 맞춰볼게요" 빈칸(2단어: m___ h______)을 쓰세요.`,stimulusEn:`I can __________ you __________ by reviewing the outline Monday.`,answer:`meet halfway`,explanationKo:`서로 한 발씩 양보하는 타협은 meet ~ halfway입니다.`}},{id:`d18-e06`,number:6,part:`Part 1 · 어휘·구동사 빈칸 영작`,grammarTag:`Day 18 핵심 · 오피스 이디엄`,questionKo:`빈칸에 2단어를 넣어 "결국 고객 신뢰에 실질적 변화를 만드는 것은 결제 안정성입니다"를 완성하세요.`,stimulusEn:`Checkout reliability is what truly moves __________ __________ for customer trust.`,answer:`the needle`,explanationKo:`눈에 띄는 실질적 성과를 만들어 내다는 move the needle입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "남은 세부 사항을 매끄럽게 조율해 해결합시다" 빈칸 구동사(2단어)를 쓰세요.`,stimulusEn:`Let's __________ __________ the remaining action items before we wrap up.`,answer:`iron out`,explanationKo:`자잘한 세부 사항과 이견을 매끄럽게 해결하다는 iron out입니다.`}},{id:`d18-e07`,number:7,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`Day 13 복습 · 음소거 & walk through`,questionKo:`화상회의 진행 중 어법과 비즈니스 매너가 모두 100% 정확한 문장은?`,stimulusEn:`Day 13 핵심 어법(on mute / walk through)을 점검하세요.`,options:[`Sorry, you are mute! Also let me explain you slide three.`,`Sorry, you're on mute! Once you unmute, I'll walk you through slide three.`,`Your voice is dead! I will walk through you the slide three.`,`Please open your microphone so I can explain about you the deck.`],answer:`Sorry, you're on mute! Once you unmute, I'll walk you through slide three.`,explanationKo:`음소거 상태는 on mute, 단계별 안내 구문은 walk [사람] through [자료]가 정확합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "화면이 멈췄어요—잠깐 나갔다가 다시 접속할게요" 빈칸(3단어: l__ b___ i_)을 채우세요.`,stimulusEn:`My screen is frozen, so I'll drop off and __________ __________ __________.`,answer:`log back in`,explanationKo:`재접속하다는 log back in입니다.`}},{id:`d18-e08`,number:8,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`Day 14 복습 · 이메일 전치사 종합`,questionKo:`다음 영문 이메일의 빈칸 (A), (B)에 들어갈 전치사가 바르게 짝지어진 것은?`,stimulusEn:`I've CC'd finance (A) this thread to keep them in the loop, and please sign off (B) the final copy by Thursday.`,options:[`(A) on — (B) on`,`(A) in — (B) at`,`(A) to — (B) for`,`(A) at — (B) with`],answer:`(A) on — (B) on`,explanationKo:`이메일 참조는 CC [사람] on [스레드], 최종 승인은 sign off on [문서]로 둘 다 전치사 on을 씁니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "편하신 가장 빠른 시간에 검토해 주세요" 빈칸 2단어(e_______ c__________)를 쓰세요.`,stimulusEn:`Please review the attached agreement at your __________ __________.`,answer:`earliest convenience`,explanationKo:`격식 회신 요청은 at your earliest convenience입니다.`}},{id:`d18-e09`,number:9,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`Day 15 vs 18 · by EOD vs at the end of the day`,questionKo:"다음 중 두 표현 `by EOD`와 `at the end of the day`가 문맥상 모두 정확하게 쓰인 문장은?",stimulusEn:`마감 기한 표현과 "결국/본질적으로" 이디엄의 차이를 구분하세요.`,options:[`I'll send the deliverables at the end of the day (= 6 PM), because by EOD quality matters most.`,`I'll send the deliverables by EOD today—at the end of the day, accuracy matters most.`,`I'll send the deliverables until EOD today—at the end of the day means 5 PM.`,`By EOD, customer trust is more important than speed, so reply until Friday.`],answer:`I'll send the deliverables by EOD today—at the end of the day, accuracy matters most.`,explanationKo:`완료 기한은 by EOD, "결국/본질적으로 가장 중요한 것은"이라는 뜻의 이디엄은 at the end of the day입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "포인트 개편은 다음 분기까지 후순위로 미뤄두죠" 빈칸(3단어: t__ b___ b_____)을 채우세요.`,stimulusEn:`Let's put the loyalty redesign on __________ __________ __________ until Q4.`,answer:`the back burner`,explanationKo:`후순위 보류는 put ~ on the back burner입니다.`}},{id:`d18-e10`,number:10,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`Day 16 복습 · 완곡 반론 & 검증`,questionKo:`임원 회의에서 동료의 공격적인 일정 단축안에 대해 품위 있게 반론하고 리스크를 검증하는 가장 세련된 문장은?`,stimulusEn:`공감 + 우려 + 검증 질문을 모두 갖춘 문장을 고르세요.`,options:[`I disagree completely because your plan is reckless and wrong.`,`You make a valid point on urgency; that said, I have reservations about cutting corners on QA—just to play devil's advocate, what if payments fail at launch?`,`Stop talking about Monday launch because finance and QA hate it.`,`I have reservation for a restaurant after this meeting, so let us end.`],answer:`You make a valid point on urgency; that said, I have reservations about cutting corners on QA—just to play devil's advocate, what if payments fail at launch?`,explanationKo:`valid point(인정) + reservations about(완곡 우려) + play devil's advocate(객관적 리스크 검증)의 완벽한 조합입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "그 부수 안건은 다음 주 회의로 보류해 두죠" 빈칸 동사(1단어)를 쓰세요.`,stimulusEn:`Let's __________ that side topic until next week's sync.`,answer:`table`,explanationKo:`미국 비즈니스 영어에서 안건 보류는 동사 table을 씁니다.`}},{id:`d18-e11`,number:11,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`Day 17 복습 · appreciate & consider 어법`,questionKo:`피드백 대화에서 어법상 오류가 전혀 없는 문장은?`,stimulusEn:`appreciate와 consider 뒤의 동명사(V-ing) 구조를 확인하세요.`,options:[`I appreciate you to give feedback, and have you considered to shorten slide four?`,`I really appreciate you flagging slide four—have you considered simplifying the chart?`,`I appreciate to hear your advice, so I will consider cut the bullets.`,`I really appreciate you flagged me and considered simplify the deck.`],answer:`I really appreciate you flagging slide four—have you considered simplifying the chart?`,explanationKo:`appreciate(flagging)와 consider(simplifying) 모두 목적어로 동명사(V-ing)를 취합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "데이터 슬라이드에 조금 개선의 여지가 있습니다" 빈칸(3단어)을 채우세요.`,stimulusEn:`There is a bit of __________ __________ __________ on slide four.`,answer:`room for improvement`,explanationKo:`개선의 여지는 room for improvement입니다.`}},{id:`d18-e12`,number:12,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`Day 18 핵심 · 오피스 이디엄 의미 매칭`,questionKo:`다음 중 비즈니스 이디엄과 그 의미가 **잘못** 짝지어진 것은?`,stimulusEn:`3주차 종합 이디엄의 정확한 뉘앙스를 점검하세요.`,options:[`ballpark figure — 대략적인 추정치`,`get the green light — 프로젝트 최종 진행 승인을 받다`,`cut corners — 마감에 쫓겨 절차를 생략하거나 대충 편법을 쓰다`,`low-hanging fruit — 가장 어렵고 시간이 오래 걸리는 장기 연구 과제`],answer:`low-hanging fruit — 가장 어렵고 시간이 오래 걸리는 장기 연구 과제`,explanationKo:`low-hanging fruit은 반대로 "적은 노력으로 빠르게 성과를 낼 수 있는 손쉬운 고효율 과제"를 뜻합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "결론·핵심 요점은 결제 QA 없이는 출시할 수 없다는 것입니다" 빈칸(2단어: b_____ l___)을 쓰세요.`,stimulusEn:`The __________ __________ is that we can't launch without payment QA.`,answer:`bottom line`,explanationKo:`핵심 결론·요점은 the bottom line입니다.`}},{id:`d18-e13`,number:13,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`Day 18 핵심 · off the table & fast-track`,questionKo:`디렉터가 "Skipping security audits is off the table, so let's fast-track the legal review instead"라고 말했을 때의 정확한 의미는?`,stimulusEn:`off the table과 fast-track의 문맥을 파악하세요.`,options:[`보안 감사를 생략하고 법무 검토는 취소하자`,`보안 감사 생략은 고려 대상이 아니므로, 대신 법무 검토를 신속 처리(패스트트랙)하자`,`보안 감사와 법무 검토를 모두 다음 분기로 미루자`,`회의 테이블에서 보안 감사 보고서를 치워달라`],answer:`보안 감사 생략은 고려 대상이 아니므로, 대신 법무 검토를 신속 처리(패스트트랙)하자`,explanationKo:`off the table은 논의·선택지 제외, fast-track은 최우선 신속 처리를 뜻합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "고정관념에서 벗어나 창의적으로 생각하다" 빈칸(3단어: o______ t__ b__)을 채우세요.`,stimulusEn:`With a tight budget, we need to think __________ __________ __________.`,answer:`outside the box`,explanationKo:`창의적 발상은 think outside the box입니다.`}},{id:`d18-e14`,number:14,part:`Part 2 · 어법·뉘앙스 실전 객관식`,grammarTag:`Day 18 핵심 · wrap one's head around`,questionKo:`갑자기 변경된 복잡한 가격표를 보고 "회신드리기 전에 수정된 수치를 제대로 소화하고 이해할 시간이 한 시간 정도 필요해요"라고 말할 때 빈칸에 알맞은 것은?`,stimulusEn:`Give me an hour to __________ these revised numbers before I circle back.`,options:[`wrap my head around`,`burn my bridges with`,`cut corners on`,`drop off from`],answer:`wrap my head around`,explanationKo:`복잡한 정보나 상황을 충분히 이해하고 소화하다는 wrap one's head around입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "프로덕트 팀과 세일즈 팀 간의 명확한 방향 정렬·합의" 빈칸 명사(1단어: a________)를 쓰세요.`,stimulusEn:`We need clear __________ between product and sales before launch.`,answer:`alignment`,explanationKo:`팀·부서 간 방향 일치와 정렬은 alignment입니다.`}},{id:`d18-e15`,number:15,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`Day 13/18 통합 · 화상회의 오프닝 배열`,questionKo:`주어진 청크를 올바른 순서로 배열하여 화상회의 킥오프 문장을 완성하세요.`,stimulusEn:`[ my screen / to get / Let me / the ball rolling. / share ]`,answer:`Let me share my screen to get the ball rolling.`,explanationKo:`화면 공유(share my screen)와 회의 개시 이디엄(get the ball rolling)을 연결합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "모두 같은 방향을 공유하도록 마감일을 정리하죠." (Let’s recap / our deadlines / so everyone is / on the same page.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`Let's recap our deadlines so everyone is on the same page.`,explanationKo:`so everyone is on the same page로 회의 정리 목적을 분명히 밝힙니다.`}},{id:`d18-e16`,number:16,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`Day 14/15 통합 · 이메일 & 마감 보고 배열`,questionKo:`주어진 청크를 배열하여 첨부 안내와 기한 내 회신 약속 문장을 완성하세요.`,stimulusEn:`[ the revised deck, / I've attached / by EOD Friday. / and I'll / circle back ]`,answer:`I've attached the revised deck, and I'll circle back by EOD Friday.`,explanationKo:`I've attached ~ (첨부) + circle back by EOD Friday(기한 내 회신) 구조입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "QA 트래커는 제가 주도적으로 맡겠습니다." (I’ll take ownership of / the QA tracker.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`I'll take ownership of the QA tracker.`,explanationKo:`take ownership of + 업무 패턴입니다.`}},{id:`d18-e17`,number:17,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`Day 16/18 통합 · 완곡 반론 + 원칙 제시`,questionKo:`우리말 뜻에 맞게 주어진 단어를 활용해 자연스러운 회의 반론 문장을 완성하세요.`,stimulusEn:`우리말: 어떤 취지인지 이해하지만, QA에서 편법을 쓰는 건 고려 대상이 아닙니다. (I see where you’re coming from, / but cutting corners on QA / is off the table.)`,answer:`I see where you're coming from, but cutting corners on QA is off the table.`,explanationKo:`공감 쿠션 뒤에 동명사 주어(cutting corners on QA) + is off the table로 원칙을 선명하게 전합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "결국 가장 중요한 것은 고객 신뢰입니다." (At the end of the day, / customer trust / matters most.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`At the end of the day, customer trust matters most.`,explanationKo:`At the end of the day로 핵심 본질을 강조합니다.`}},{id:`d18-e18`,number:18,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`Day 17/18 통합 · 거절 & 우선순위 전략`,questionKo:`주어진 청크를 배열하여 업무 한계를 밝히며 대안을 제시하는 문장을 완성하세요.`,stimulusEn:`[ fast-track / at capacity, / Since we're / the low-hanging fruit. / let's ]`,answer:`Since we're at capacity, let's fast-track the low-hanging fruit.`,explanationKo:`원인(Since we're at capacity) + 고효율 대안(fast-track the low-hanging fruit) 구조입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "디렉터님께 최종 진행 승인을 받았습니다!" (We got / the green light / from our director!)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`We got the green light from our director!`,explanationKo:`get the green light의 과거형 got the green light입니다.`}},{id:`d18-e19`,number:19,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`Week 3 종합 콩글리시 교정`,questionKo:`다음 콩글리시 문장의 오류 3곳(mute, explain me, until EOD)을 모두 바르게 고쳐 쓰세요.`,stimulusEn:`오류 문장: Sorry, you are mute! Could you explain me the deck until EOD?`,answer:`Sorry, you're on mute! Could you walk me through the deck by EOD?`,acceptableAlt:[`Sorry, you are on mute! Could you walk me through the deck by EOD?`,`Sorry, you're on mute! Could you explain the deck to me by EOD?`],explanationKo:`are mute → on mute, explain me → walk me through(또는 explain ~ to me), until EOD → by EOD로 교정합니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] 오류 교정: I appreciate you to give me a rough number. → appreciate + 동명사 & ballpark figure로 고치세요.`,stimulusEn:`힌트: I appreciate you giving me ~.`,answer:`I appreciate you giving me a ballpark figure.`,explanationKo:`appreciate 뒤 동명사 giving과 대략적 추정치 a ballpark figure 조합입니다.`}},{id:`d18-e20`,number:20,part:`Part 3 · 서술형 어순 배열 & 한영 통문장 영작`,grammarTag:`Week 3 파이널 실전 통문장 영작`,questionKo:`다음 우리말을 Week 3 핵심 표현(iron out, on the same page, wrap up)을 활용해 자연스러운 영어로 작성하세요.`,stimulusEn:`우리말: 모두가 같은 방향을 공유하도록 남은 세부 사항을 조율한 뒤 회의를 마무리하죠. (힌트: Let’s iron out / the remaining details / so we’re all on the same page, / and then wrap up.)`,answer:`Let's iron out the remaining details so we're all on the same page, and then wrap up.`,acceptableAlt:[`Let's iron out the remaining details so everyone is on the same page, and then wrap up.`,`Let's iron out the remaining details so we are all on the same page, and then wrap up.`],explanationKo:`실무 회의의 조율(iron out) → 합의 확인(on the same page) → 종료(wrap up)를 한 호흡에 완성하는 3주차 졸업 문장입니다.`,twinClinic:{questionKo:`[쌍둥이 클리닉] "실질적 성과를 만드는 핵심 기능에 집중합시다." (Let’s focus on / core features / that move the needle.)`,stimulusEn:`영문 전체를 작성하세요.`,answer:`Let's focus on core features that move the needle.`,explanationKo:`관계대명사절 that move the needle로 우선순위 기준을 명확히 세웁니다.`}}],tutorScenario:{openingQuestionEn:`Welcome to our Friday launch readiness sync! Thanks for hopping on—I saw the email you attached earlier. Quick question: with the payment QA bottleneck, should we skip the final test cycle to hold Monday's date, or do you recommend a different plan?`,openingQuestionKo:`금요일 론칭 최종 점검 회의에 오신 걸 환영해요! 접속해 주셔서 감사하고 아까 첨부해 주신 이메일도 잘 봤어요. 짧은 질문 하나 드릴게요—결제 QA 병목이 있는데 월요일 일정을 지키려고 마지막 테스트를 생략할까요, 아니면 다른 대안을 추천하시나요? (Week 3 표현들을 총동원해 공감 → 품질 타협 불가 → 우선순위 조정·타협안 → 기한 내 회신 약속까지 한 번에 브리핑해 보세요!)`,followUpQuestionEn:`That makes total sense—you have my green light! Let's iron out the revised action items so everyone is on the same page, and please circle back with a ballpark timeline by EOD.`,followUpQuestionKo:`완전히 설득됐어요—최종 진행 승인합니다! 모두가 같은 방향을 공유하도록 수정된 실행 과제를 조율하고, 오늘 마감 전까지 대략적인 일정표로 회신해 주세요.`,recommendedChunks:[`I see where you're coming from`,`cutting corners is off the table`,`at the end of the day / move the needle`,`currently at capacity`,`fast-track the low-hanging fruit`,`put ~ on the back burner`,`circle back by EOD`],modelAnswerEn:`I really appreciate you flagging the deadline urgency, and I see where you're coming from on keeping momentum. That said, cutting corners on payment QA has to be off the table—at the end of the day, reliability is what truly moves the needle. Since our team is currently at capacity, I recommend we fast-track the low-hanging fruit fixes, put the secondary redesign on the back burner, and push launch back by 48 hours if needed. Once we get your green light, I'll iron out the action items and circle back by EOD.`}}];export{t as WEEK3_MODULES};